E["item:a-short-note"] = {t="item",n="A Short Note",z="feralas",s="A Short Note asks you to carry Daryn’s letter to Curgle Cranklehop in Tanaris. It requests a picture of Gammerita, a giant snapjaw in the Hinterlands.",h="A Short Note asks you to carry Daryn’s letter to Curgle Cranklehop in Tanaris.",sec={{t="A Letter for Curgle",b="Daryn’s research keeps her in Rut’theran Village, though her latest fascination is the snapjaws on the Hinterlands beach. She wants a picture of Gammerita, a giant snapjaw, and sends you to Tanaris with a letter for Curgle Cranklehop. Curgle has made an invention that can capture a picture.",sp=0}},faq={{q="Who wrote the note?",a="Daryn wrote the letter. She is a historian in Rut’theran Village whose latest fascination is the snapjaws of the Hinterlands.",al={"who sent the letter","daryn note","who is it from"}},{q="Who is Gammerita?",a="Gammerita is a giant snapjaw on the beach in the Hinterlands. Daryn wants a picture of her.",al={"giant snapjaw","who is gammerita","snapjaw target"}},{q="Who is Curgle Cranklehop?",a="Curgle Cranklehop is in Tanaris and has made an invention that can capture a picture.",al={"curgle","who gets the note","tanaris inventor"}},{q="Why does Daryn want a picture?",a="Daryn wants a picture of Gammerita because she cannot leave her research in Rut’theran Village to see the giant snapjaw herself.",al={"why photograph gammerita","why picture snapjaw","what does daryn want"}}},kw={"a short note","curgle cranklehop","daryn","gammerita","hinterlands","picture","snapjaw","tanaris"},rel={"quest:2941","item:super-snapper-fx","zone:hinterlands","zone:tanaris","zone:feralas"},src={"Wowpedia: A Short Note","The Borrower"}}
E["item:a-shrunken-head"] = {t="item",n="A Shrunken Head",z="feralas",s="A shrunken head from Feralas is promised to Neeru Fireblade in Orgrimmar. It will secure the herbs needed for an experiment.",h="A shrunken head from Feralas is promised to Neeru Fireblade in Orgrimmar.",sec={{t="A Grim Bargain",b="Before the herbs can be put to use, Neeru Fireblade in Orgrimmar is owed a grim payment. The head came from a dwarf found in the forests of Feralas. Its bearer carries it to the Cleft of Shadow, where Neeru has prepared an herb mixture for Uzer'i's experiments.",sp=0}},faq={{q="Whose head is it?",a="The head belonged to a dwarf found in the forests of Feralas.",al={"who is the head from","dwarf head","shrunken head owner"}},{q="Who is supposed to receive it?",a="Neeru Fireblade in Orgrimmar is promised the head.",al={"who gets the head","take it to who","neeru head"}},{q="Why does Neeru want the head?",a="The head is payment for herbs Neeru prepared for Uzer'i's experiments.",al={"why bring head","what's it for","head purpose"}},{q="Where do I take the shrunken head?",a="Take the shrunken head to Neeru Fireblade in the Cleft of Shadow in Orgrimmar.",al={"where to bring it","head destination","cleft of shadow"}}},kw={"cleft of shadow","dwarf","experiment","feralas","herbs","neeru fireblade","orgrimmar","shrunken head","uzer'i"},rel={"quest:3121","quest:829","zone:orgrimmar","zone:feralas","subzone:cleft-of-shadow"},src={"Wowpedia: A Shrunken Head","A Strange Request (Feralas)"}}
E["item:a-sparkling-stone"] = {t="item",n="A Sparkling Stone",z="feralas",s="The Sparkling Stone is found within the Equinex Monolith in Feralas. Troyas Moonbreeze identifies it as the Morrow Stone and begins studying its purpose.",h="The Sparkling Stone is found within the Equinex Monolith in Feralas.",sec={{t="At Feathermoon",b="After returning to Feathermoon Stronghold, you bring the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze. He names the stone the Morrow Stone and says he does not yet know what it is meant to do. Its place inside the Equinex Monolith marks it as something worth studying.",sp=0}},faq={{q="What is the Sparkling Stone?",a="Troyas Moonbreeze identifies the Sparkling Stone as the Morrow Stone, an artifact taken from the Equinex Monolith.",al={"sparkling stone","morrow stone","what stone"}},{q="Where do you find the Sparkling Stone?",a="The Sparkling Stone is found inside the Equinex Monolith in Feralas.",al={"stone location","where stone","find morrow stone"}},{q="Who is Troyas Moonbreeze?",a="Troyas Moonbreeze is the scholar at Feathermoon Stronghold who receives the Morrow Stone and the Stave of Equinex for study.",al={"troyas","troyas moonbreeze","who wants the stone"}},{q="What is the stone for?",a="Troyas Moonbreeze does not yet know the Morrow Stone's purpose, but believes it is significant.",al={"stone purpose","what does it do","morrow stone use"}}},kw={"equine monolith","feathermoon stronghold","feralas","morrow stone","sparkling stone","stave of equinex","troyas moonbreeze"},rel={"quest:2942","item:stave-of-equinex","subzone:feathermoon-stronghold-classic","zone:feralas"},src={"Wowpedia: A Sparkling Stone","The Morrow Stone"}}
E["item:camp-mojache-zukk-ash-report"] = {t="item",n="Camp Mojache Zukk'ash Report",z="feralas",s="The Camp Mojache Zukk'ash Report carries gathered knowledge about the insect threat in Feralas. It brings that warning to an expert in Orgrimmar.",h="The Camp Mojache Zukk'ash Report carries gathered knowledge about the insect threat in Feralas.",sec={{t="A Warning Carried",b="Hadoken entrusts the report to you after the Zukk'ash threat at Camp Mojache has been addressed. The document gathers what is known about the insects, whose danger remains. You are to take it to Zilzibin Drumlore in Orgrimmar's Drag, where his knowledge of strange creatures may help the Horde understand the threat.",sp=0},{t="The Old Threat",b="Zilzibin Drumlore recognizes the creatures described in the Camp Mojache report as silithid. He calls them an ancient danger the Horde has chosen to ignore, far worse in his view than anything the Alliance could muster. He asks for aid in bringing the threat to light.",sp=1}},faq={{q="What is the Camp Mojache Zukk'ash Report?",a="It is a document of what has been learned about the Zukk'ash insects threatening Camp Mojache.",al={"zukkash report","camp mojache report","insect report"}},{q="Who should receive the report?",a="Zilzibin Drumlore in the Drag of Orgrimmar is waiting for the report.",al={"who gets the report","zilzibin report","where take report"}},{q="Why does the Horde want this report delivered?",a="Zilzibin Drumlore is an expert on strange creatures, and the Horde hopes he can make use of what has been learned about the Zukk'ash.",al={"why deliver report","what is it for","horde insect report"}},{q="What are the Zukk'ash?",a="Zilzibin identifies the Zukk'ash as silithid, an ancient threat.",al={"zukkash insects","what are zukkash","silithid"}}},ang={["faction:Horde"]="As a member of the Horde, this report carries a warning from Camp Mojache to an expert in Orgrimmar, who calls the silithid an ancient danger."},kw={"camp mojache","drag","feralas","horde","report","silithid","zilzibin drumlore","zukk'ash","zukkash"},rel={"quest:7732","subzone:camp-mojache","zone:feralas","subzone:drag","zone:orgrimmar","topic:horde"},src={"Wowpedia: Camp Mojache Zukk'ash Report","Zukk'ash Report"}}
E["item:crate-of-grimtotem-horns"] = {t="item",n="Crate of Grimtotem Horns",z="feralas",s="The Crate of Grimtotem Horns carries evidence of the Grimtotem Clan in Feralas. Belgrom Rockmaul in Orgrimmar wants to hear what you found.",h="The Crate of Grimtotem Horns carries evidence of the Grimtotem Clan in Feralas.",sec={{t="News from Feralas",b="In Orgrimmar's Valley of Honor, Belgrom Rockmaul receives the Crate of Grimtotem Horns. You found the horns while hunting in Feralas, where the Grimtotem Clan has drawn attention. Belgrom wants to hear what you saw and will pay you for the news.",sp=0}},faq={{q="What is in the crate?",a="The crate holds Grimtotem horns taken from Feralas.",al={"crate contents","horn crate"}},{q="Who wants the crate?",a="Belgrom Rockmaul in Orgrimmar's Valley of Honor wants the Crate of Grimtotem Horns.",al={"who gets horns","Belgrom crate"}},{q="Why does Belgrom want the horns?",a="Belgrom wants to hear what you saw of the Grimtotem Clan in Feralas.",al={"why horns","grimtotem news"}},{q="Where did the horns come from?",a="You found the Grimtotem horns while hunting in Feralas.",al={"horns from where","feralas horns"}},{q="What does Belgrom offer?",a="Belgrom says he will count out coin while you tell him about the Grimtotem.",al={"Belgrom reward","coin for horns"}}},kw={"belgrom rockmaul","crate of grimtotem horns","feralas","grimtotem","grimtotem horns","orgrimmar","valley of honor"},rel={"quest:2974","item:grimtotem-horn","zone:feralas","zone:orgrimmar","subzone:valley-of-honor"},src={"Wowpedia: Crate of Grimtotem Horns","A Grim Discovery (2)"}}
E["item:discarded-knife"] = {t="item",n="Discarded Knife",z="feralas",s="The Discarded Knife is a well-kept blade found beneath the water near a missing boat in Feralas. Ginro Hearthkindle hopes it may offer a clue to Raschal’s fate.",h="The Discarded Knife is a well-kept blade found beneath the water near a missing boat in Feralas.",sec={{t="Beneath the Water",b="At the bottom of the water in Feralas, the Discarded Knife lies near a large piece of a missing boat. Its handle is easy to find in the mud, and the blade appears well cared for. You bring it to Ginro Hearthkindle at Feathermoon Stronghold, who is searching for clues to Raschal’s fate.",sp=0},{t="A Clue in Hand",b="Ginro believes the knife may have belonged to Raschal, though finding it near the boat is not enough to settle the matter. He sends you to Quintis Jonespyre, the Stronghold’s resident druid, for a reading by touch. Quintis calls this art psychometry and hopes it will offer a glimpse of what happened.",sp=0}},faq={{q="Where did the knife come from?",a="The Discarded Knife was found in the mud beneath the water in Feralas, near a large piece of a missing boat.",al={"knife location","where found","knife in water"}},{q="Who might the knife belong to?",a="Ginro Hearthkindle believes the Discarded Knife may have belonged to Raschal, whose fate remains uncertain.",al={"whose knife","raschal knife","knife owner"}},{q="Why does Ginro want the knife?",a="Ginro is searching for clues to Raschal’s fate, and hopes the knife may help reveal what happened.",al={"ginro knife","why bring knife","what clue"}},{q="Who can read the knife’s history?",a="Quintis Jonespyre, Feathermoon Stronghold’s resident druid, uses psychometry to seek an item’s history by touching it.",al={"knife reading","psychometry","quintis knife"}},{q="What is psychometry?",a="Psychometry is Quintis Jonespyre’s art of seeking insight into an item’s history through touch.",al={"what is psychometry","item reading","read object"}}},ang={["class:Druid"]="As a druid, you may recognize Quintis Jonespyre’s psychometry as an unusual art that draws on nature’s secrets."},kw={"boat wreckage","discarded knife","feathermoon stronghold","feralas","ginro hearthkindle","knife","psychometry","quintis jonespyre","raschal"},rel={"quest:4127","quest:4129","quest:4130","subzone:feathermoon-stronghold-classic","zone:feralas","topic:druid"},src={"Wowpedia: Discarded Knife","Boat Wreckage","The Knife Revealed"}}
E["item:feralas-a-history-quest-item"] = {t="item",n="Feralas: A History",z="feralas",s="Troyas Moonbreeze asks you to carry Feralas: A History back to Feathermoon Stronghold. The book matters because he is eager to have it returned.",h="Troyas Moonbreeze asks you to carry Feralas: A History back to Feathermoon Stronghold.",sec={{t="The Return",b="Troyas Moonbreeze waits at Feathermoon Stronghold for Feralas: A History. Daryn Lightwind hands the book over, asks you to take care of it and hurry along, sure that Troyas is eager for your return.",sp=0}},faq={{q="Who is the book for?",a="Troyas Moonbreeze at Feathermoon Stronghold is waiting for Feralas: A History.",al={"who wants the book","deliver book to who"}},{q="What is Feralas: A History?",a="It is a book Troyas Moonbreeze asks you to carry back to him at Feathermoon Stronghold.",al={"feralas book","history book"}},{q="Where do I take the book?",a="Take Feralas: A History to Troyas Moonbreeze at Feathermoon Stronghold.",al={"where to bring book","book destination"}},{q="Why does Troyas want it back?",a="Daryn Lightwind only says Troyas is eager for your return; no further reason is given.",al={"why return book","why is Troyas waiting"}}},kw={"book","feathermoon stronghold","feralas","feralas: a history","return to troyas","troyas moonbreeze"},rel={"quest:2943","quest:2940","zone:feralas","subzone:feathermoon-stronghold-classic"},src={"Wowpedia: Feralas: A History (quest item)","Return to Troyas"}}
E["item:gordunni-cobalt"] = {t="item",n="Gordunni Cobalt",z="feralas",s="At Gordunni Outpost, blue glimmers in the dirt draw Orwin Gizzmick’s eye. He hopes the buried cobalt will fetch a fine price.",h="At Gordunni Outpost, blue glimmers in the dirt draw Orwin Gizzmick’s eye.",sec={{t="Blue in the Dirt",b="Orwin Gizzmick has newly arrived in Feralas and wants samples of the mineral the Gordunni ogres bury at their outpost. He lends you his shovel and points you north from Camp Mojache. Look for the blue glow among the dirt mounds; Orwin wants the cobalt for its value to a buyer.",sp=0}},faq={{q="Who wants the Gordunni Cobalt?",a="Orwin Gizzmick in Camp Mojache wants twelve samples of Gordunni Cobalt.",al={"who wants cobalt","orwin cobalt","gizzmick's mineral"}},{q="Where can I find Gordunni Cobalt?",a="The cobalt lies in dirt mounds at Gordunni Outpost, north of Camp Mojache in Feralas.",al={"cobalt location","where cobalt","blue dirt"}},{q="Why is the cobalt buried?",a="The Gordunni ogres bury the mineral to keep others from getting their hands on it.",al={"why buried","ogres bury cobalt","gordunni dirt"}},{q="What does Orwin want the cobalt for?",a="Orwin hopes to find someone who will pay a fine price for the cobalt.",al={"why orwin wants it","cobalt price","sell cobalt"}}},kw={"camp mojache","cobalt","feralas","gordunni","gordunni cobalt","gordunni outpost","orwin gizzmick","orwin's shovel"},rel={"quest:2987","item:orwin-s-shovel","subzone:gordunni-outpost","subzone:camp-mojache","zone:feralas"},src={"Wowpedia: Gordunni Cobalt","Gordunni Cobalt (quest)"}}
E["item:gordunni-orb"] = {t="item",n="Gordunni Orb",z="feralas",s="A Gordunni Orb is a powerful magical object taken from the Gordunni in Feralas. Its magic may help reveal the purpose of their dark ceremony.",h="A Gordunni Orb is a powerful magical object taken from the Gordunni in Feralas.",sec={{t="A Mage's Orb",b="Rok Orhan in Camp Mojache seeks a Gordunni Orb to learn more about the Gordunni and their magic. The orb is gathered from one of the Gordunni mage-lords. Its power may help uncover what their dark ceremony is for.",sp=0},{t="In Orgrimmar",b="Rok Orhan sends the Gordunni Orb to Uthel'nay at Darkbriar Lodge in Orgrimmar. Uthel'nay recognizes its great power and warns that it is dangerous.",sp=0}},faq={{q="What is the Gordunni Orb?",a="The Gordunni Orb is a powerful magical object held by Gordunni mage-lords in Feralas.",al={"gordunni orb","what orb","mage orb"}},{q="Who wants the orb?",a="Rok Orhan in Camp Mojache seeks the orb to learn more about the Gordunni and their magic.",al={"who wants orb","Rok Orhan orb","camp mojache orb"}},{q="What is the orb used for?",a="Rok Orhan hopes the orb's power will help reveal more about the Gordunni's dark ceremony.",al={"orb purpose","why need orb","what does it do"}},{q="Who can examine the orb?",a="Uthel'nay at Darkbriar Lodge in Orgrimmar can tell more about the orb.",al={"who examines orb","Uthel'nay","orb mage"}},{q="Why is the orb dangerous?",a="Uthel'nay says the Gordunni Orb is very powerful and dangerous.",al={"orb danger","dangerous orb","is it powerful"}}},ang={["class:Mage"]="As a mage, you may recognize why Rok Orhan seeks the orb: its magic could help reveal more about the Gordunni's ceremony.",["faction:Horde"]="As a member of the Horde, you can help Rok Orhan of Camp Mojache learn more about the Gordunni and plan their downfall."},kw={"camp mojache","dark ceremony","darkbriar lodge","feralas","gordunni","gordunni orb","mage-lord","rok orhan","uthel'nay"},rel={"quest:2979","quest:3002","zone:feralas","subzone:camp-mojache","zone:orgrimmar"},src={"Wowpedia: Gordunni Orb","Dark Ceremony","The Gordunni Orb (Classic)"}}
E["item:grimtotem-horn"] = {t="item",n="Grimtotem Horn",z="feralas",s="Grimtotem Horns are taken from Grimtotem tauren west of Camp Mojache in Feralas. Krueg Skullsplitter asks for them after learning the tribe is nearby.",h="Grimtotem Horns are taken from Grimtotem tauren west of Camp Mojache in Feralas.",sec={{t="Taken in Feralas",b="West of Camp Mojache, Grimtotem tauren carry these horns. Krueg Skullsplitter asks you to bring him a collection after learning the clan is in Feralas. He says Belgrom has placed a bounty on the Grimtotem and warns that they are dangerous.",sp=0}},faq={{q="Where do Grimtotem Horns come from?",a="Grimtotem tauren west of Camp Mojache in Feralas carry the horns.",al={"where horns from","grimtotem horn source"}},{q="Who wants the horns?",a="Krueg Skullsplitter in Camp Mojache asks you to bring him Grimtotem Horns.",al={"who needs horns","krueg horns"}},{q="Why does Krueg want them?",a="Krueg asks for the horns after learning that Grimtotem tauren are nearby. He says Belgrom has an interest in the tribe and has placed a bounty on them.",al={"why collect horns","horns for what"}},{q="Who are the Grimtotem?",a="The Grimtotem are a tauren clan found west of Camp Mojache in Feralas.",al={"grimtotem who","grimtotem tauren"}}},ang={["faction:Horde"]="As a Horde traveler, Krueg's warning frames the Grimtotem as a danger to Horde lands and villages."},kw={"belgrom","camp mojache","feralas","grimtotem","grimtotem horn","grimtotem horns","krueg skullsplitter","tauren"},rel={"quest:2974","quest:2973","subzone:camp-mojache","topic:grimtotem-tribe","zone:feralas","topic:tauren"},src={"Wowpedia: Grimtotem Horn","A Grim Discovery (Classic)"}}
E["item:hatecrest-naga-scale"] = {t="item",n="Hatecrest Naga Scale",z="feralas",s="Hatecrest Naga Scales are taken from the naga threatening Sardor Isle in Feralas. Latronicus Moonspear at Feathermoon Stronghold wants them to weaken the naga presence and study what may be made from them.",h="Hatecrest Naga Scales are taken from the naga threatening Sardor Isle in Feralas.",sec={{t="Scales for Feathermoon",b="Latronicus Moonspear asks you to bring ten Hatecrest Naga Scales to Feathermoon Stronghold. He fears the naga will try to secure Sardor Isle, so he means to weaken their presence before that threat grows. The scales must be in good condition. Once he has them, he plans to send them to Pratt for study and possible use in crafting.",sp=0}},faq={{q="What are Hatecrest Naga Scales for?",a="Latronicus Moonspear wants ten good Hatecrest Naga Scales to weaken the naga presence on Sardor Isle. He also plans to send them to Pratt to see whether they can be used in crafting.",al={"why scales","hatecrest scales use","scales purpose"}},{q="Who wants the scales?",a="Latronicus Moonspear at Feathermoon Stronghold asks for ten Hatecrest Naga Scales.",al={"who needs scales","latronicus scales","scales for who"}},{q="Why does Feathermoon want to weaken the naga?",a="Latronicus fears the Hatecrest naga will move to secure Sardor Isle, so he wants their presence weakened before they can do so.",al={"why fight hatecrest","naga threat","why sardor isle"}},{q="What might Pratt do with the scales?",a="Latronicus plans to send the scales to Pratt, who may be able to craft something useful from them.",al={"pratt scales","craft from scales","scales crafting"}}},ang={["race:NightElf"]="As a night elf, you help Latronicus protect Feathermoon Stronghold's interests on Sardor Isle. He says his people seek peace, yet will act to defend what is theirs."},kw={"feathermoon stronghold","hatecrest naga scale","hatecrest scales","latronicus moonspear","naga","pratt","sardor isle"},rel={"quest:2869","zone:feralas","subzone:sardor-isle","subzone:feathermoon-stronghold-classic","topic:naga","quest:2870","quest:2871"},src={"Wowpedia: Hatecrest Naga Scale","Against the Hatecrest (2)"}}
E["item:hippogryph-muisek"] = {t="item",n="Hippogryph Muisek",z="feralas",s="Hippogryph Muisek preserves the spirits of the Frayfeather hippogryphs in Feralas. Witch Doctor Uzer'i asks you to capture them with a Muisek Vessel.",h="Hippogryph Muisek preserves the spirits of the Frayfeather hippogryphs in Feralas.",sec={{t="Spirits Preserved",b="Among the Frayfeather hippogryphs of the High Wilderness, you are to capture ten with the Muisek Vessel. The night elves have long kept hippogryphs as loyal companions, and their spirits are steadfast. The vessel preserves each spirit after its creature is slain.",sp=0}},faq={{q="What is hippogryph muisek?",a="Hippogryph Muisek is the preserved spirit of a Frayfeather hippogryph, captured in a Muisek Vessel.",al={"hippogryph muisek","muisek item"}},{q="Where do I find Frayfeather hippogryphs?",a="Frayfeather hippogryphs live in the High Wilderness, south of Witch Doctor Uzer'i, who asks you to capture them.",al={"hippogryph location","frayfeathers where"}},{q="Why capture the hippogryphs?",a="Uzer'i wants their muisek preserved, since a spirit left free after its creature dies may take the form of a greater creature and threaten those nearby.",al={"why muisek","capture hippogryphs"},sp=1},{q="How many hippogryphs are needed?",a="Uzer'i asks you to capture ten Frayfeather hippogryphs.",al={"how many hippogryphs","muisek count"}}},ang={["race:NightElf"]="As a night elf, you know hippogryphs as loyal companions whose spirits are steadfast. Uzer'i's concern is to preserve those spirits safely."},kw={"feralas","frayfeather","high wilderness","hippogryph","hippogryph muisek","muisek vessel","spirit"},rel={"quest:3124","item:hippogryph-muisek-vessel","subzone:high-wilderness","zone:feralas"},src={"Wowpedia: Hippogryph Muisek","Hippogryph Muisek (Classic)"}}
E["item:hippogryph-muisek-vessel"] = {t="item",n="Hippogryph Muisek Vessel",z="feralas",s="The Hippogryph Muisek Vessel preserves the spirits of hippogryphs in Feralas. It is given to capture their muisek in the High Wilderness.",h="The Hippogryph Muisek Vessel preserves the spirits of hippogryphs in Feralas.",sec={{t="A Preserved Spirit",b="After you have shown you can use the vessel, Witch Doctor Uzer'i asks you to capture hippogryph muisek. The Frayfeather hippogryphs live in the High Wilderness, south of him. Their spirits have long been loyal companions to the night elves. Uzer'i warns that a spirit left free after an animal's death may become a greater creature and seek vengeance.",sp=0}},faq={{q="What does the Hippogryph Muisek Vessel do?",a="The vessel captures hippogryph muisek so their spirits may be preserved.",al={"what's the vessel for","hippogryph vessel use"}},{q="Where do I use the vessel?",a="The Frayfeather hippogryphs are in the High Wilderness, south of Witch Doctor Uzer'i.",al={"where to use muisek vessel","high wilderness vessel"}},{q="Why capture hippogryph muisek?",a="The vessel preserves the hippogryphs' muisek. Witch Doctor Uzer'i warns a spirit left free after death may become a greater creature and seek vengeance.",al={"why capture them","hippogryph spirits"}},{q="Are hippogryphs important to night elves?",a="Hippogryphs have been loyal companions to the night elves for many years.",al={"night elf hippogryphs","hippogryph companions"}}},ang={["race:NightElf"]="Hippogryphs have long been loyal companions to the night elves, and preserving their spirits matters to Witch Doctor Uzer'i."},kw={"frayfeather","high wilderness","hippogryph","hippogryph muisek","hippogryph muisek vessel","muisek","witch doctor uzer'i"},rel={"quest:3124","subzone:high-wilderness","zone:feralas"},src={"Wowpedia: Hippogryph Muisek Vessel","Hippogryph Muisek (Classic)"}}
E["item:jer-kai-s-signet-ring"] = {t="item",n="Jer'kai's Signet Ring",z="feralas",s="Jer'kai's Signet Ring carries her message from the wilds of Feralas to Tyrande Whisperwind in Darnassus. It tells the High Priestess that Jer'kai and Kindal are well and gives credit for your help.",h="Jer'kai's Signet Ring carries her message from the wilds of Feralas to Tyrande Whisperwind in Darnassus.",sec={{t="A Message to Darnassus",b="In Feralas, Jer'kai Moonweaver entrusts you with her signet ring after you help her and Kindal. She asks you to carry it to Tyrande Whisperwind at the Temple of the Moon in Darnassus. The ring bears word that the two are well and gives Tyrande the truth of your help.",sp=0},{t="At the Temple",b="Tyrande hears your account of helping dragonkind and one of her priestesses. She promises to return Jer'kai's ring, sending scouts toward Feralas with it. For now, the ring has carried its message to the High Priestess.",sp=0}},faq={{q="What is Jer'kai's Signet Ring for?",a="Jer'kai asks you to take the ring to Tyrande Whisperwind at the Temple of the Moon in Darnassus. It tells Tyrande that Jer'kai and Kindal are well and gives credit for your help.",al={"jerkai ring","signet ring purpose","ring for tyrande"}},{q="Who gave me the ring?",a="Jer'kai Moonweaver gives you her signet ring in Feralas after you help her and Kindal.",al={"who gave ring","jerkai ring giver","where ring from"}},{q="Who is supposed to receive the ring?",a="Tyrande Whisperwind, the High Priestess at Darnassus's Temple of the Moon, is to receive the ring.",al={"ring recipient","who gets jerkais ring","tyrande ring"}},{q="What does Tyrande do with the ring?",a="Tyrande promises to return the ring to Jer'kai, sending scouts toward Feralas with it.",al={"tyrande response","ring returned","what happens to ring"},sp=1}},ang={["race:NightElf"]="As a night elf, you carry Jer'kai's message to Tyrande Whisperwind, High Priestess of Elune, at the Temple of the Moon."},kw={"darnassus","feralas","jer'kai moonweaver","jer'kai's signet ring","kindal","message","signet ring","temple of the moon","tyrande whisperwind"},rel={"quest:2970","quest:2969","zone:feralas","zone:darnassus","subzone:temple-of-the-moon","npc:tyrande-whisperwind"},src={"Wowpedia: Jer'kai's Signet Ring","Doling Justice (2)"}}
E["item:miniaturization-residue"] = {t="item",n="Miniaturization Residue",z="feralas",s="Miniaturization Residue is left on Feralas giants shrunk by Zorbin Fandazzle’s device. He studies it to improve his shrinking ray and asks for more at the Forgotten Coast docks.",h="Miniaturization Residue is left on Feralas giants shrunk by Zorbin Fandazzle’s device.",sec={{t="Residue from Giants",b="Along the Forgotten Coast, Zorbin Fandazzle seeks residue from giants shrunk with his Ultra-Shrinker. Cliff Giants, Deep Striders, Land Walkers, Shore Striders and Wave Striders all yield it after the device has been used. Zorbin says the residue helps him keep his other zappers from exploding on their users.",sp=0}},faq={{q="What is Miniaturization Residue?",a="Miniaturization Residue is found on Feralas giants after they have been shrunk with Zorbin’s Ultra-Shrinker.",al={"miniaturization residue","what is this residue","giant residue"}},{q="Who wants the residue?",a="Zorbin Fandazzle, at the docks of the Forgotten Coast, asks for Miniaturization Residue.",al={"who wants residue","zorbin residue","who do I bring it to"}},{q="Why does Zorbin need it?",a="Zorbin studies the residue to help ensure his other shrinking devices do not explode on their users.",al={"why residue","what's residue for","zapper research"}},{q="Which giants have it?",a="Cliff Giants, Deep Striders, Land Walkers, Shore Striders and Wave Striders in Feralas can yield residue after being shrunk.",al={"giants residue drops from","what giants","feralas giants"}}},ang={["profession:Engineering"]="As an engineer, you may recognize Zorbin’s interest in residue as a way to improve his shrinking devices."},kw={"engineering","feralas","forgotten coast","giants","miniaturization residue","steamwheedle cartel","zorbin fandazzle","zorpin's ultra-shrinker"},rel={"item:zorbin-s-ultra-shrinker","quest:7003","quest:7725","subzone:forgotten-coast","zone:feralas","topic:steamwheedle-cartel"},src={"Wowpedia: Miniaturization Residue","Zapped Giants","Again With the Zapped Giants"}}
E["item:mysterious-relic"] = {t="item",n="Mysterious Relic",z="feralas",s="The Mysterious Relic is an unfamiliar device found during a naga excavation on the Isle of Dread. Feathermoon Stronghold wants it studied to learn what it is.",h="The Mysterious Relic is an unfamiliar device found during a naga excavation on the Isle of Dread.",sec={{t="A Strange Find",b="Scouts traced Lord Shalzaru’s excavation to a cave south of the main ruins on the Isle of Dread. The naga lord uncovered the Mysterious Relic there, and Latronicus Moonspear asked that it be brought to Feathermoon Stronghold for study.\n\nLatronicus could make little of the device, so he sent it to his wife Vestia, a priestess and scholar. She found it unlike the ruins’ usual objects and unlike naga work. Its nature remains uncertain while she studies it.",sp=0}},faq={{q="Where was the Mysterious Relic found?",a="Lord Shalzaru uncovered the Mysterious Relic in a naga excavation cave south of the main ruins on the Isle of Dread.",al={"relic location","where relic","isle of dread relic"}},{q="Who wants the relic?",a="Latronicus Moonspear asked for the Mysterious Relic to be brought to Feathermoon Stronghold so it could be studied.",al={"who needs relic","latronicus relic","relic for who"}},{q="Who studies the Mysterious Relic?",a="Vestia Moonspear, Latronicus’s wife and a priestess and scholar, studies the Mysterious Relic.",al={"vestia moonspear","who researches relic","relic scholar"}},{q="What is the Mysterious Relic?",a="Vestia says the Mysterious Relic is unlike the objects of the Ruins of Solarsal and is not of naga design. She needs time to study it.",al={"what is relic","weird device","relic meaning"}},{q="Did the naga make the relic?",a="Vestia says the Mysterious Relic is not of naga design, though its maker remains unknown.",al={"naga relic","is it naga made","who made relic"}}},kw={"feathermoon stronghold","isle of dread","latronicus moonspear","lord shalzaru","mysterious relic","naga excavation","relic","vestia moonspear"},rel={"quest:2871","quest:2870","npc:lord-shalzaru","subzone:isle-of-dread","subzone:feathermoon-stronghold-classic","zone:feralas"},src={"Wowpedia: Mysterious Relic","Against Lord Shalzaru","Delivering the Relic"}}
E["item:orwin-s-shovel"] = {t="item",n="Orwin's Shovel",z="feralas",s="Orwin Gizzmick lends his shovel in Camp Mojache for a search for Gordunni cobalt. The blue-glowing mineral is buried at the Gordunni Outpost, where the ogres guard it closely.",h="Orwin Gizzmick lends his shovel in Camp Mojache for a search for Gordunni cobalt.",sec={{t="A Prospector's Tool",b="Orwin Gizzmick has only just reached Feralas, and the mineral buried by the Gordunni ogres has caught his interest. From Camp Mojache, he sends you north with his shovel to gather cobalt from their outpost. The blue glow marks where to dig. Orwin means to carry the samples onward and find a buyer.",sp=0}},faq={{q="Who owns Orwin's Shovel?",a="Orwin Gizzmick lends you his shovel from Camp Mojache so you can dig for Gordunni cobalt.",al={"orwins shovel","orwin shovel","who has the shovel"}},{q="What is Orwin's Shovel for?",a="Orwin's Shovel is used to dig up Gordunni cobalt at the Gordunni Outpost in Feralas.",al={"shovel purpose","what do i dig with","cobalt shovel"}},{q="Where do I use Orwin's Shovel?",a="You use Orwin's Shovel at the Gordunni Outpost north of Camp Mojache, where the cobalt is buried.",al={"where shovel","gordunni outpost shovel","where to dig cobalt"}},{q="Why does Orwin want Gordunni cobalt?",a="Orwin hopes to find someone who will pay well for the cobalt as he continues his travels.",al={"why cobalt","orwin wants cobalt","cobalt buyer"}}},ang={["profession:Mining"]="As a miner, you know the value of a buried seam. Orwin's shovel points you toward cobalt hidden among the Gordunni ogres."},kw={"camp mojache","feralas","gordunni cobalt","gordunni outpost","orwin gizzmick","orwin's shovel","shovel"},rel={"quest:2987","subzone:camp-mojache","subzone:gordunni-outpost","zone:feralas"},src={"Wowpedia: Orwin's Shovel","Gordunni Cobalt (quest)"}}
E["item:rage-scar-yeti-hide"] = {t="item",n="Rage Scar Yeti Hide",z="feralas",s="Rage Scar Yeti Hide comes from the yetis of Rage Scar Hold in northern Feralas. Pratt McGrubben and Jangdor Swiftstrider seek the hides for their work with leather.",h="Rage Scar Yeti Hide comes from the yetis of Rage Scar Hold in northern Feralas.",sec={{t="A Better Hide",b="In northern Feralas, the yetis of Rage Scar Hold yield hides that leatherworkers prize. Pratt McGrubben at Feathermoon Stronghold and Jangdor Swiftstrider at Camp Mojache each seek ten for their work. They hope the hides will prove as resilient as thorium once cured.",sp=0}},faq={{q="Where do Rage Scar Yeti Hides come from?",a="Rage Scar Yeti Hides come from the yetis in Rage Scar Hold, in northern Feralas.",al={"where get yeti hide","rage scar hide source"}},{q="Who wants these hides?",a="Pratt McGrubben at Feathermoon Stronghold and Jangdor Swiftstrider at Camp Mojache both seek Rage Scar Yeti Hides.",al={"who needs the hides","hide for who"}},{q="Why are the hides valuable?",a="The hide may be exceptionally resilient once cured, which makes it promising for leatherwork.",al={"why want yeti hides","hide quality"}},{q="How many hides are needed?",a="Pratt McGrubben and Jangdor Swiftstrider each ask for ten Rage Scar Yeti Hides.",al={"how many","ten hides"}}},kw={"feralas","jangdor swiftstrider","leather","pratt mcgrubben","rage scar hold","rage scar yeti hide","rage scar yetis","yeti hide"},rel={"subzone:rage-scar-hold","zone:feralas","subzone:camp-mojache","subzone:feathermoon-stronghold-classic","quest:7733"},src={"Wowpedia: Rage Scar Yeti Hide","Improved Quality (Classic Alliance)","Improved Quality (Classic Horde)"}}
E["item:raschal-s-report"] = {t="item",n="Raschal's Report",z="feralas",s="Raschal's Report carries word of a silithid infestation in southeastern Feralas. Shandris Feathermoon sends a copy to Gracina Spiritmight at the Temple of the Moon.",h="Raschal's Report carries word of a silithid infestation in southeastern Feralas.",sec={{t="A Copy for Darnassus",b="At Feathermoon Stronghold, Shandris Feathermoon entrusts you with a copy of Raschal's report on the silithid in southeastern Feralas. The main report is being filed in Darnassus. This copy is for Gracina Spiritmight, a priestess of the Temple of the Moon with knowledge of such creatures.",sp=0},{t="The Temple's Counsel",b="Gracina Spiritmight receives you at the Temple of the Moon, where she recognizes the danger described in Raschal's report. She names the insects as silithid and warns that they will consume Feralas rapidly. To her, they are tools of a great threat to both the Horde and the Alliance, and she prays for the resolve to defeat them.",sp=0}},faq={{q="What is Raschal's Report?",a="Raschal's Report describes the silithid infestation in southeastern Feralas.",al={"raschal report","what's in the report"}},{q="Who is Raschal's Report for?",a="A copy of Raschal's Report is meant for Gracina Spiritmight, a priestess at the Temple of the Moon in Darnassus.",al={"who gets the report","report for gracina"}},{q="Who asks you to carry the report?",a="Shandris Feathermoon entrusts you with a copy of Raschal's Report for Gracina Spiritmight.",al={"who sent me","shandris report"}},{q="What are the insects in the report?",a="Gracina identifies the insects described in Raschal's Report as silithid.",al={"feralas bugs","what are silithid"}},{q="Why does Gracina need the report?",a="Gracina has broad knowledge of creatures like the silithid, and Shandris believes receiving the report will benefit them all.",al={"why bring it to gracina","temple report"}}},ang={["race:NightElf"]="As a night elf, you bring Shandris Feathermoon's report to Gracina Spiritmight at the Temple of the Moon, where she recognizes the silithid threat to Feralas.",["class:Priest"]="As a priest, you carry the report to Gracina Spiritmight, a priestess whose knowledge of such creatures may help the defenders of Feralas."},kw={"darnassus","feralas","gracina spiritmight","raschal","raschal's report","shandris feathermoon","silithid","southeastern feralas","temple of the moon"},rel={"quest:4267","zone:feralas","npc:shandris-feathermoon","zone:darnassus","subzone:temple-of-the-moon","topic:alliance","topic:horde"},src={"Wowpedia: Raschal's Report","Rise of the Silithid (Feralas)"}}
E["item:shay-s-bell"] = {t="item",n="Shay's Bell",z="feralas",s="Shay’s Bell is a cherished bell kept in a chest in Feralas. Shay Leafrunner says its sound can call her back when she wanders.",h="Shay’s Bell is a cherished bell kept in a chest in Feralas.",sec={{t="A Familiar Sound",b="Shay Leafrunner keeps her bell in a chest in Feralas. She loves its sound and says it will bring her running back when she wanders away. Rockbiter is waiting for Shay at his camp, and the bell is meant to help guide her home.",sp=0}},faq={{q="What is Shay’s Bell for?",a="Shay says the bell’s sound will get her attention and bring her back if she wanders off.",al={"shay bell","bell use","call shay"}},{q="Where can I find Shay’s Bell?",a="Shay’s Bell is kept in Shay’s Chest in Feralas.",al={"bell location","shay chest","where bell"}},{q="Who does the bell belong to?",a="The bell is precious to Shay Leafrunner, who loves its sound.",al={"whose bell","shay item","bell owner"}},{q="Who is Shay trying to find?",a="Shay Leafrunner is trying to find her friend Rockbiter, who is at his camp.",al={"where shay going","shay friend","rockbiter"}}},kw={"feralas","rockbiter","shay","shay leafrunner","shay's bell","shay's chest","wandering shay"},rel={"quest:2845","zone:feralas","quest:2844"},src={"Wowpedia: Shay's Bell","Wandering Shay"}}
E["item:silvermane-stalker-flank"] = {t="item",n="Silvermane Stalker Flank",z="feralas",s="Silvermane Stalker Flanks are raw meat Agnar Beastamer seeks in the Hinterlands. He needs them to feed a Sprite Darter hatchling.",h="Silvermane Stalker Flanks are raw meat Agnar Beastamer seeks in the Hinterlands.",sec={{t="A First Meal",b="Agnar Beastamer is preparing for the egg to hatch, and worries the young Sprite Darter may not survive without a good first meal. He asks you to bring five Silvermane Stalker Flanks. The meat is meant for the hatchling when it emerges.",sp=0}},faq={{q="Who wants Silvermane Stalker Flanks?",a="Agnar Beastamer in the Hinterlands wants five Silvermane Stalker Flanks to feed a Sprite Darter hatchling.",al={"who needs the flanks","agnar's meat","who wants this meat"}},{q="What are the flanks for?",a="Agnar plans to feed the raw meat to a Sprite Darter when its egg hatches.",al={"why the meat","baby sprite food","what's this flank for"}},{q="How many flanks does Agnar need?",a="Agnar Beastamer asks you to bring five Silvermane Stalker Flanks.",al={"how many pieces","five flanks","amount of meat"}},{q="Where do Silvermane Stalker Flanks come from?",a="Silvermane Stalker Flanks come from Silvermane Stalkers in the Hinterlands.",al={"where to find flanks","stalker meat","silvermane flank source"}},{q="What does a Sprite Darter eat?",a="Sprite Darters eat both meat and vegetation. Agnar asks for raw Silvermane Stalker Flanks as a first meal for the hatchling.",al={"sprite darter diet","what do darters eat","baby dragon food"}}},kw={"agn ar beastamer","agnarbeastamer","food for baby","hinterlands","raw meat","silvermane stalker","silvermane stalker flank","sprite darter"},rel={"quest:4297","quest:2969","zone:hinterlands","npc:sprite-darter"},src={"Wowpedia: Silvermane Stalker Flank","Food for Baby"}}
E["item:snapshot-of-gammerita"] = {t="item",n="Snapshot of Gammerita",z="feralas",s="In the Hinterlands, Gammerita’s image is captured with Curgle’s Super Snapper FX. Daryn Lightwind in Rut’theran Village wants the snapshot for her studies.",h="In the Hinterlands, Gammerita’s image is captured with Curgle’s Super Snapper FX.",sec={{t="A Picture for Daryn",b="Curgle lends the Super Snapper FX for a picture of Gammerita in the Hinterlands. Daryn Lightwind waits in Rut’theran Village to receive the snapshot and says Curgle’s invention has met her expectations.",sp=0}},faq={{q="Who is Gammerita?",a="Gammerita is a creature in the Hinterlands, and Daryn Lightwind asks for her picture.",al={"gammerita","who's gammerita"}},{q="Who wants this snapshot?",a="Daryn Lightwind wants it for her studies; she waits in Rut’theran Village.",al={"who wants gammerita pic","snapshot for who"}},{q="How was the snapshot taken?",a="Curgle’s Super Snapper FX takes the snapshot when aimed at Gammerita.",al={"how take gammerita photo","super snapper picture"}},{q="What is the Super Snapper FX?",a="The Super Snapper FX is Curgle’s invention, lent out so a picture of Gammerita can be made.",al={"super snapper","curgle invention"}},{q="Where can I find Gammerita?",a="Gammerita is in the Hinterlands.",al={"gammerita location","where gammerita"}}},kw={"daryn lightwind","gammerita","hinterlands","rut’theran village","snapshot of gammerita","super snapper fx"},rel={"quest:2944","item:super-snapper-fx","zone:hinterlands"},src={"Wowpedia: Snapshot of Gammerita","The Super Snapper FX"}}
E["item:stave-of-equinex"] = {t="item",n="Stave of Equinex",z="feralas",s="The Stave of Equinex is an energized staff tied to the Equinex Monolith in Feralas. Its power is needed to open the ancient stone.",h="The Stave of Equinex is an energized staff tied to the Equinex Monolith in Feralas.",sec={{t="The Silent Monolith",b="At the Ruins of Ravenwind in Feralas, Troyas' Stave can be made into the Stave of Equinex. Four flames still burn nearby: Samha, Imbel, Byltan, and Lahassa. Their essences rouse the stave beside the Equinex Monolith. The staff is a key, and the stone monument holds something within.",sp=0},{t="A Fading Power",b="When the energized Stave of Equinex touches the monolith, a small door opens in its cold surface. Beams of light fill the ruins as the hidden artifact is taken. The stave's power then begins to fade, and Troyas Moonbreeze at Feathermoon Stronghold can study what was found.",sp=1}},faq={{q="What does the Stave of Equinex do?",a="The Stave of Equinex is a key that opens the Equinex Monolith in the Ruins of Ravenwind.",al={"stave purpose","what is equinex stave"}},{q="How is Troyas' Stave changed?",a="The essences of the four flames Samha, Imbel, Byltan, and Lahassa energize Troyas' Stave beside the Equinex Monolith.",al={"energize troyas stave","make equinex stave"}},{q="Where is the Equinex Monolith?",a="The Equinex Monolith stands among the Ruins of Ravenwind in Feralas, west of the Dream Bough.",al={"monolith location","where is equinex"}},{q="What is inside the monolith?",a="A small door in the monolith opens to reveal an artifact. Troyas Moonbreeze identifies the stone taken from it as the Morrow Stone.",al={"monolith artifact","what's in equinex"},sp=1},{q="Why does the stave lose power?",a="The Stave of Equinex begins to lose its energy as soon as the artifact is removed from the monolith.",al={"stave fading","why stave weak"},sp=1}},kw={"byltan","equinex monolith","feralas","imbel","lahassa","morrow stone","ruins of ravenwind","samha","stave of equinex","troyas' stave"},rel={"quest:2879","quest:2942","item:a-sparkling-stone","item:troyas-stave","zone:feralas","subzone:ruins-of-ravenwind","subzone:dream-bough"},src={"Wowpedia: Stave of Equinex","The Stave of Equinex","The Morrow Stone"}}
E["item:super-snapper-fx"] = {t="item",n="Super Snapper FX",z="feralas",s="The Super Snapper FX is Curgle's camera, lent to you for Daryn Lightwind in Rut'theran Village. Daryn wants a picture of Gammerita, a creature from the Hinterlands.",h="The Super Snapper FX is Curgle's camera, lent to you for Daryn Lightwind in Rut'theran Village.",sec={{t="A New Invention",b="Daryn Lightwind sends you to Curgle for her new invention, the Super Snapper FX. She asks for a snapshot of Gammerita, the creature from the Hinterlands, and expects you to bring the picture back to Rut'theran Village. Curgle says to aim at your subject and press the button.",sp=0}},faq={{q="What is the Super Snapper FX?",a="The Super Snapper FX is a camera made by Curgle. Curgle lends it to you to take a picture of Gammerita for Daryn Lightwind.",al={"super snapper","snapper camera"}},{q="Who wants a picture of Gammerita?",a="Daryn Lightwind in Rut'theran Village asks you to bring back a snapshot of Gammerita from the Hinterlands.",al={"who needs the photo","daryn picture"}},{q="Who made the Super Snapper FX?",a="Curgle built the Super Snapper FX for Daryn Lightwind.",al={"who built snapper","curgle invention"}},{q="What does the Super Snapper FX do?",a="Aim the Super Snapper FX at what you want to photograph and press its button.",al={"how does the snapper work","camera button"}}},kw={"c amate","c camera","camer","cargle","daryn lightwind","gammerita","snapshot","super snapper","super snapper fx"},rel={"quest:2944","item:snapshot-of-gammerita","zone:feralas","zone:hinterlands","subzone:rut-theran-village"},src={"Wowpedia: Super Snapper FX","The Super Snapper FX"}}
E["item:thick-yeti-hide"] = {t="item",n="Thick Yeti Hide",z="feralas",s="In Feralas, yeti hides draw the attention of leatherworkers who prize fine materials. Pratt McGrubben and Jangdor Swiftstrider seek them for their work.",h="In Feralas, yeti hides draw the attention of leatherworkers who prize fine materials.",sec={{t="A Leatherworker’s Mark",b="Feralas yetis are prized by two leatherworkers for their thick hides. Pratt McGrubben at Feathermoon Stronghold and Jangdor Swiftstrider at Camp Mojache each ask for ten. They promise a choice of their leather goods in return. Both believe careful tanning can make these hides remarkably resilient.",sp=0}},faq={{q="Where do thick yeti hides come from?",a="Thick Yeti Hides come from yetis in Feralas. Many are found in Feral Scar Vale, just inland from the Forgotten Coast.",al={"thick hide source","where yeti hides","yeti hide feralas"}},{q="Who wants thick yeti hides?",a="Pratt McGrubben at Feathermoon Stronghold and Jangdor Swiftstrider at Camp Mojache each seek ten Thick Yeti Hides.",al={"who needs hides","pratt hides","jangdor hides"}},{q="What are the hides used for?",a="Pratt McGrubben and Jangdor Swiftstrider want the hides for their leatherworking. They believe skilled tanning can make them exceptionally resilient.",al={"yeti hide use","what for hides","leatherworking hides"}},{q="What do the leatherworkers offer?",a="Each leatherworker offers a choice of crafted leather goods for a stack of ten Thick Yeti Hides.",al={"hide trade","ten hides reward","what do i get"}}},ang={["profession:Tailoring"]="As a leatherworker, you may appreciate why Pratt McGrubben and Jangdor Swiftstrider prize hides they believe can be treated to remarkable strength."},kw={"feral scar vale","feralas","forgotten coast","jangdor swiftstrider","leatherworking","pratt mcgrubben","tanning","thick yeti hide","yeti"},rel={"quest:2821","zone:feralas","subzone:feral-scar-vale","subzone:forgotten-coast","subzone:camp-mojache","subzone:feathermoon-stronghold-classic"},src={"Wowpedia: Thick Yeti Hide","The Mark of Quality (Classic Alliance)","The Mark of Quality (Classic Horde)"}}
E["item:troyas-stave"] = {t="item",n="Troyas' Stave",z="feralas",s="Troyas' Stave may be the key to the Equinex Monolith in the Ruins of Ravenwind. Four lingering flames hold the power needed to test it.",h="Troyas' Stave may be the key to the Equinex Monolith in the Ruins of Ravenwind.",sec={{t="The Four Flames",b="Among the Ruins of Ravenwind in Feralas, Troyas' Stave is meant for the Equinex Monolith. The four flames Samha, Imbel, Byltan, and Lahassa still burn nearby, each holding an essence. Gather them, then use their power beside the monolith to energize the stave.",sp=0},{t="The Monolith",b="When the energized stave touches the cold face of the Equinex Monolith, a small door opens. Within lies a sacred artifact, and beams of light fill the ruins around the stone.",sp=1}},faq={{q="What is Troyas' Stave for?",a="Troyas' Stave is meant to unlock the Equinex Monolith in the Ruins of Ravenwind.",al={"troyas stave","what does the stave do"}},{q="Where is the Equinex Monolith?",a="The Equinex Monolith stands in the Ruins of Ravenwind, in Feralas west of the Dream Bough.",al={"equinex monolith location","where is monolith"}},{q="How do I energize Troyas' Stave?",a="Recover the essences of Samha, Imbel, Byltan, and Lahassa, then use them beside the Equinex Monolith.",al={"energize stave","four flames"}},{q="What are the four flames called?",a="The four flames are Samha, Imbel, Byltan, and Lahassa.",al={"flame names","samha imbel byltan lahassa"}},{q="What is inside the Equinex Monolith?",a="A sacred artifact rests inside the Equinex Monolith.",al={"monolith artifact","what's in the monolith"},sp=1}},kw={"byltan","dream bough","equinex monolith","feralas","imbel","lahassa","ruins of ravenwind","samha","stave of equinex","troyas' stave"},rel={"quest:2879","item:stave-of-equinex","subzone:ruins-of-ravenwind","subzone:dream-bough","zone:feralas"},src={"Wowpedia: Troyas' Stave","The Stave of Equinex"}}
E["item:water-elemental-core"] = {t="item",n="Water Elemental Core",z="feralas",s="A Water Elemental Core is a source of raw power sought by Zorbin Fandazzle on Feralas’s Forgotten Coast. Sea Sprays and Sea Elementals carry them along the shore.",h="A Water Elemental Core is a source of raw power sought by Zorbin Fandazzle on Feralas’s Forgotten Coast.",sec={{t="Cores on the Coast",b="Near the dock on Feralas’s Forgotten Coast, Zorbin Fandazzle asks for Water Elemental Cores. Sea Sprays and Sea Elementals along the coast carry them. Zorbin says he needs the cores for his Ultra-Shrinker refinement and to keep his engineering shop running.",sp=0}},faq={{q="What is a Water Elemental Core?",a="A Water Elemental Core is found within the Sea Sprays and Sea Elementals along Feralas’s Forgotten Coast. Zorbin Fandazzle uses the cores as raw power for his Ultra-Shrinker refinement.",al={"water core","elemental core","what's the core for"}},{q="Where do Water Elemental Cores come from?",a="Sea Sprays and Sea Elementals along the Forgotten Coast of Feralas carry Water Elemental Cores.",al={"where get cores","core location","sea spray cores"}},{q="Who wants Water Elemental Cores?",a="Zorbin Fandazzle, near the dock on the Forgotten Coast, wants Water Elemental Cores for his work.",al={"who needs cores","zorbin cores","who do i bring them to"}},{q="Why does Zorbin need the cores?",a="Zorbin says the cores provide raw power for his Ultra-Shrinker refinement and help him keep his engineering shop running.",al={"why cores","zapping fuel","ultra shrinker power"}},{q="What is Zorbin Fandazzle doing on the coast?",a="Zorbin Fandazzle is trying to set up an engineering shop on the Forgotten Coast of Feralas.",al={"zorbin shop","engineering shop","what is he building"}}},ang={["profession:Engineering"]="As an engineer, you may recognize Zorbin Fandazzle’s need for raw power: he seeks Water Elemental Cores for his Ultra-Shrinker refinement."},kw={"engineering","feralas","forgotten coast","sea elemental","sea spray","ultra-shrinker","water core","water elemental core","zorbin fandazzle"},rel={"subzone:forgotten-coast","quest:7721","quest:7726","zone:feralas","topic:steamwheedle-cartel"},src={"Wowpedia: Water Elemental Core","Fuel for the Zapping","Refuel for the Zapping"}}
E["item:xerash-s-herb-pouch"] = {t="item",n="Neeru's Herb Pouch",z="feralas",s="Neeru's Herb Pouch carries herbs for Witch Doctor Uzer'i in Feralas. He needs them to prepare a muisek vessel.",h="Neeru's Herb Pouch carries herbs for Witch Doctor Uzer'i in Feralas.",sec={{t="Herbs for Uzer'i",b="Witch Doctor Uzer'i needs Neeru Fireblade's herbs for a ritual in Feralas. Neeru is satisfied with the shrunken head, and sends the pouch along with word of that approval. Uzer'i applies the herbs as he prepares the muisek vessel, hoping his latest incantations will prove powerful.",sp=0}},faq={{q="Who needs Neeru's Herb Pouch?",a="Witch Doctor Uzer'i needs Neeru's Herb Pouch to prepare a muisek vessel.",al={"who needs the pouch","herb pouch for who"}},{q="What is in the pouch?",a="The pouch holds herbs Neeru Fireblade gathered for Witch Doctor Uzer'i.",al={"what herbs","pouch contents"}},{q="Why does Uzer'i want the herbs?",a="Witch Doctor Uzer'i applies the herbs while preparing a muisek vessel for a ritual.",al={"why herbs","what does uzeri need them for"}},{q="What does Neeru say about the shrunken head?",a="Neeru is satisfied with the shrunken head and asks that Witch Doctor Uzer'i be told.",al={"neeru shrunken head","is neeru satisfied"}},{q="What is a muisek vessel?",a="Witch Doctor Uzer'i is preparing a muisek vessel for a ritual involving his latest incantations.",al={"muisek vessel","what's muisek"}}},kw={"feralas","herbs","muisek vessel","neeru fireblade","neeru's herb pouch","shrunken head","witch doctor uzer'i"},rel={"quest:3122","npc:witch-doctor-uzer-i","zone:feralas"},src={"Wowpedia: Xerash's Herb Pouch","Return to Witch Doctor Uzer'i"}}
E["item:zorbin-s-ultra-shrinker"] = {t="item",n="Zorbin's Ultra-Shrinker",z="feralas",s="Zorbin’s Ultra-Shrinker is a goblin device used on giants along Feralas’s western coast. Zorbin Fandazzle studies the residue left behind and values the goodwill it earns among his Steamwheedle Cartel friends.",h="Zorbin’s Ultra-Shrinker is a goblin device used on giants along Feralas’s western coast.",sec={{t="A Goblin Device",b="At the Forgotten Coast docks, Zorbin Fandazzle puts his Ultra-Shrinker to work on Feralas’s giants. The device reduces them to a more manageable form, leaving residue for his research. Zorbin welcomes more of it, and says the service carries word of your work to his goblin friends in the Steamwheedle Cartel.",sp=0}},faq={{q="What does Zorbin’s Ultra-Shrinker do?",a="Zorbin’s Ultra-Shrinker reduces giants in Feralas to a more manageable form and leaves residue for his research.",al={"what does the shrinker do","shrink giant device","zorbin shrink ray"}},{q="Who is Zorbin Fandazzle?",a="Zorbin Fandazzle is a goblin at the Forgotten Coast docks in Feralas who studies residue from shrunken giants.",al={"who is zorbin","zorbin fandazzle","goblin at the docks"}},{q="Where does Zorbin use the device?",a="Zorbin Fandazzle is at the docks of the Forgotten Coast, and the giants he studies are along Feralas’s western coast.",al={"where is zorbin","forgotten coast shrinker","feralas giant device"}},{q="Why does Zorbin want the residue?",a="Zorbin studies Miniaturization Residue, which is left by giants reduced with his Ultra-Shrinker.",al={"why residue","what's miniaturization residue for","zorbin research"}},{q="What does Zorbin offer for helping him?",a="Zorbin offers coin and says he will spread word of your service among his goblin friends in the Steamwheedle Cartel.",al={"zorbin compensation","cartel reputation","what do i get from zorbin"}}},ang={["profession:Engineering"]="As an engineer, you may appreciate Zorbin’s goblin device, built to shrink Feralas’s giants for study."},kw={"feralas","forgotten coast","giants","goblin device","miniaturization residue","steamwheedle cartel","zorbin fandazzle","zorbin's ultra-shrinker"},rel={"quest:7725","quest:7003","item:miniaturization-residue","subzone:forgotten-coast","zone:feralas","topic:steamwheedle-cartel","topic:goblin"},src={"Wowpedia: Zorbin's Ultra-Shrinker","Again With the Zapped Giants"}}
E["item:zukk-ash-carapace"] = {t="item",n="Zukk'ash Carapace",z="feralas",s="A Zukk'ash Carapace is evidence taken from the insect-like Zukk'ash in Feralas. Hadoken Swiftstrider at Camp Mojache wants them while the Horde investigates the threat near the Writhing Deep.",h="A Zukk'ash Carapace is evidence taken from the insect-like Zukk'ash in Feralas.",sec={{t="Carapace Evidence",b="South of the gnolls in Feralas, the Zukk'ash dwell in the Writhing Deep. Hadoken Swiftstrider at Camp Mojache seeks their carapaces as evidence while the Horde scouts the insects and their effect on the gnolls. Their presence is troubling enough to demand study.",sp=0}},faq={{q="What is a Zukk'ash Carapace?",a="A Zukk'ash Carapace is the hard covering of one of the insect-like Zukk'ash in Feralas.",al={"zukkash shell","what is this carapace"}},{q="Where do Zukk'ash Carapaces come from?",a="The Zukk'ash in Feralas yield carapaces. They dwell in the Writhing Deep, south of the gnolls.",al={"where find carapaces","zukkash shell location"}},{q="Who wants the carapaces?",a="Hadoken Swiftstrider at Camp Mojache wants Zukk'ash Carapaces as evidence of the hunt.",al={"who needs zukkash shells","Hadoken carapaces"}},{q="Why are the carapaces being collected?",a="Hadoken Swiftstrider wants the carapaces as evidence and intends to have them analyzed. The Horde hopes to learn more about the Zukk'ash threat.",al={"why collect shells","what are carapaces for"}}},ang={["faction:Horde"]="As a member of the Horde, you can help Camp Mojache investigate the Zukk'ash threat by bringing Hadoken Swiftstrider their carapaces as evidence."},kw={"camp mojache","carapace","feralas","hadoken swiftstrider","writhing deep","zukk'ash","zukk'ash carapace","zukk'ash infestation"},rel={"quest:7730","zone:feralas","subzone:writhing-deep","subzone:camp-mojache"},src={"Wowpedia: Zukk'ash Carapace","Zukk'ash Infestation (Classic)"}}
E["npc:falfindel-waywarder"] = {t="npc",n="Falfindel Waywarder",z="feralas",s="At Thalanaar, Falfindel Waywarder keeps watch over the border between Feralas and Thousand Needles. The night elf druid works to heal corrupted lands and guard Kalimdor’s southern wilderness. Travelers from Stonetalon or the Barrens often seek his aid to restore balance to the wild.",h="At Thalanaar, Falfindel Waywarder keeps watch over the border between Feralas and Thousand Needles.",sec={{t="Watch at the Southern Border",b="Falfindel Waywarder stands at Thalanaar, the night elf outpost on the edge of Feralas. The outpost marks the passage from forest to mesas and salt plains. Travelers who have crossed far across the continent greet him there. From this post, he watches for local threats and dangers to lands across Kalimdor.",sp=0},{t="Healing the Charred Vale",b="Falfindel Waywarder watches from the south, but the ruin of the Charred Vale in Stonetalon Mountains weighs on him. Dark sorcery and fire scarred that wilderness. When adventurers bring aid for its recovery, he calls on the forest spirits. Falfindel summons swarms of wisps and sends them north to mend the scorched earth.",sp=0},{t="Eyes on the Quilboar and the Wastes",b="Falfindel Waywarder also watches the region around Thalanaar, including the quilboar dens of Razorfen Kraul. He studies recovered journals and gathers word of quilboar leaders. His watch helps the Alliance understand the dangers threatening the passes between Feralas and the central deserts.",sp=0}},faq={{q="Where is Falfindel Waywarder located?",a="Falfindel Waywarder is stationed at Thalanaar, the night elf outpost on the border between Feralas and Thousand Needles.",al={"falfindel location","where is falfindel","falfindel waywarder map"},it="place",gp=true},{q="What is Falfindel's role at Thalanaar?",a="Falfindel Waywarder watches regional threats, including the quilboar of Razorfen Kraul, and coordinates efforts to restore ruined lands such as the Charred Vale.",al={"what does falfindel do","falfindel purpose","falfindel quests"},it="purpose"},{q="How does Falfindel help the Charred Vale?",a="When adventurers bring aid for the Charred Vale, Falfindel Waywarder summons forest wisps and sends them north to Stonetalon to heal the blighted land.",al={"falfindel stonetalon","falfindel charred vale","reclaiming the charred vale falfindel"}},{q="Why is Falfindel interested in Razorfen Kraul?",a="Falfindel Waywarder studies the quilboar threat at Razorfen Kraul. He examines items such as Lonebrow's journal to follow the influence of leaders like the Crone of the Kraul.",al={"crone of the kraul falfindel","lonebrow journal falfindel","falfindel quilboar"},it="motive"},{q="Is Falfindel aligned with the Alliance or neutral?",a="Falfindel Waywarder is a night elf druid allied with Darnassus and the Alliance. Horde travelers will find Thalanaar hostile.",al={"is falfindel alliance","falfindel faction"},it="side"},{q="What does Falfindel say to travelers?",a="Falfindel Waywarder greets friendly visitors warmly and notes their long journey: “You look as though you have traveled from afar.”",al={"falfindel gossip","falfindel quote"}},{q="Who is Falfindel Waywarder?",a="Falfindel Waywarder is a night elf stationed at the outpost of Thalanaar, bordering Feralas and the Thousand Needles. Attuned to the health of the land and the perils facing the southern reaches of Kalimdor, he watches over travelers and works closely with fellow night elves to counter emerging threats to the wilderness.",al={"who is falfindel","falfindel waywarder lore","who is falfindel waywarder"},it="identity",add="444437e8"},{q="What does Falfindel Waywarder want?",a="Falfindel seeks to protect the fragile wilderness and aid the healing of devastated lands. He directs allies to summon forest spirits to revitalize the Charred Vale, coordinates deliveries to keep local outposts supplied, and seeks to eliminate the corrupted quilboar crone lurking within Razorfen Kraul.",al={"what does falfindel want","falfindel goals","falfindel quests purpose"},it="wants",add="e0cb4d91"},{q="Why is Falfindel Waywarder here?",a="Falfindel serves as a druid and guide at Thalanaar, guarding the passage between Thousand Needles and Feralas. From this remote outpost, he monitors the rising quilboar threat spilling from the Barrens and coordinates efforts to restore balance to blighted forests across central and southern Kalimdor.",al={"why is falfindel here","why is falfindel at thalanaar","falfindel purpose"},it="why_here",add="2bf92e29"}},ang={["race:NightElf"]="As a night elf, you see Falfindel Waywarder keep watch on Kalimdor’s frontiers, mend nature’s scars, and guard against dangers in the wild.",["class:Druid"]="As a druid, you share Falfindel Waywarder’s sacred work of restoration as he sends forest spirits and wisps to heal Stonetalon’s scorched soil.",["faction:Alliance"]="As an Alliance traveler making the long trek south from the Barrens or Stonetalon, you can find a welcome at Thalanaar with Falfindel Waywarder and its watch."},kw={"charred vale","falfindel","feralas","stonetalon","thalanaar","thousand needles","waywarder","wisps"},rel={"subzone:thalanaar","quest:1057","quest:1100","quest:1101","zone:feralas","zone:thousandneedles","subzone:charred-vale","topic:night-elf"},src={"Falfindel Waywarder"}}
E["npc:kindal-moonweaver"] = {t="npc",n="Kindal Moonweaver",z="feralas",s="From a hidden perch in Feralas, Kindal Moonweaver watches the Grimtotem Compound and its captured beasts. Troubled by their mistreatment, she seeks help to free them and protect young animals. She is kin to Jer'kai Moonweaver, and both defend the forest's creatures.",h="From a hidden perch in Feralas, Kindal Moonweaver watches the Grimtotem Compound and its captured beasts.",sec={{t="A Watcher in the Clifftops",b="East of Dire Maul, Kindal Moonweaver watches the valley from a hidden perch along a narrow, winding mountain path. The path lies behind timber, north of the Grimtotem Compound. Feralas is contested by the Horde, the night elves of Feathermoon, and the ancient ruins of Eldre'Thalas.\n\nKindal's concern is the nearby hollow, where the Grimtotem tribe keeps a fortified compound. They capture and pen local wildlife for cruel ends. From her concealed overlook, Kindal watches for anyone willing to brave the enemy camp and free the beasts.",sp=0},{t="Compassion for the Wild",b="Kindal seeks to preserve Feralas's sacred balance and protect its gentle creatures from their brutish captors. With her kin, Jer'kai Moonweaver, she works to free caged beasts and find help for young animals left stranded by poaching.\n\nHer concern is close at hand: freeing caged sprites and finding a home for an orphaned sprite darter.",sp=0}},faq={{q="Where is Kindal Moonweaver located?",a="Kindal hides along Feralas's northern cliffs, east of Dire Maul and above the Grimtotem Compound. A narrow, hidden mountain path winds uphill behind timber to her perch.",al={"kindal moonweaver location","how to find kindal","where is kindal"}},{q="Who is Kindal Moonweaver?",a="Kindal Moonweaver is a solitary night elf who protects Feralas's wildlife. She watches the Grimtotem Compound and seeks to stop its capture of local beasts.",al={"kindal lore","who is kindal"}},{q="What is Kindal's goal in Feralas?",a="Kindal wants to free creatures held in cages at the nearby Grimtotem Compound and find safe shelter for orphaned beasts of the wilderness.",al={"kindal quest purpose","why is kindal here"}},{q="Is Kindal Moonweaver related to Jer'kai Moonweaver?",a="Yes. Kindal is kin to Jer'kai Moonweaver, and both work to rescue mistreated and displaced woodland creatures in Feralas.",al={"jerkai moonweaver connection","kindal and jerkai"}},{q="Why is Kindal opposing the Grimtotem?",a="The Grimtotem clan in the compound below Kindal's perch captures and cages Feralas's wild beasts. Kindal wants to free the creatures and punish their captors.",al={"kindal grimtotem","grimtotem compound kindal"}},{q="Does Kindal Moonweaver offer quests to both factions?",a="No. Kindal makes her requests only to the Alliance, enlisting its adventurers to free the caged creatures from the Grimtotem.",al={"is kindal friendly to horde","can horde talk to kindal"}}},ang={["race:NightElf"]="As a night elf, you see Kindal guarding beasts threatened by outsiders, alone in Feralas's wilds.",["class:Druid"]="As a druid, you may share Kindal's devotion to forest life and her effort to free nature spirits from cruel iron cages.",["class:Hunter"]="As a hunter of Kalimdor's beasts, you can respect Kindal's work to protect wild young and punish those who capture game for sport or malice."},kw={"dire maul","feralas","freedom for all creatures","grimtotem compound","hidden path","jer'kai moonweaver","kindal moonweaver"},rel={"zone:feralas","subzone:grimtotem-compound","subzone:hidden-path","subzone:dire-maul","topic:night-elf"},src={"Kindal Moonweaver"}}
E["npc:lord-shalzaru"] = {t="npc",n="Lord Shalzaru",z="feralas",s="On the Isle of Dread, Lord Shalzaru rules the Hatecrest naga by cruelty. His followers dig through ruined elven settlements, and the ancient relic he uncovered now draws mainland investigators.",h="On the Isle of Dread, Lord Shalzaru rules the Hatecrest naga by cruelty.",sec={{t="Master of the Hatecrest",b="Along Feralas’s southern coast, Lord Shalzaru commands the Hatecrest naga. From his cavern lair on the Isle of Dread, he rules by force and cruelty. His followers search Kalimdor’s ancient ruins for forgotten treasures and powerful relics left by the Sundering.",sp=0},{t="The Mysterious Relic",b="South of the main ruins on the Isle of Dread, Lord Shalzaru uncovered a strange ancient relic. Its purpose and power remain unknown, yet it is now held by a powerful naga warlord. Mainland operatives seek champions to enter his lair, end his command, and secure the relic before the Hatecrest turn it to darker ends.",sp=0}},faq={{q="Who is Lord Shalzaru?",a="Lord Shalzaru commands the Hatecrest naga and their excavations on the Isle of Dread, off Feralas’s coast.",al={"lord shalzaru lore","shalzaru","who is shalzaru"}},{q="Where can Lord Shalzaru be found?",a="Lord Shalzaru lairs in a cave south of the main elven ruins on the Isle of Dread, off Feralas’s southwestern coast.",al={"shalzaru location","where is lord shalzaru","isle of dread cave"}},{q="What is the Hatecrest?",a="The Hatecrest are a hostile naga tribe along Feralas’s coast and islands. Under Shalzaru’s command, they search ancient ruins and terrorize coastal waters.",al={"hatecrest naga","hatecrest tribe"}},{q="What relic does Lord Shalzaru possess?",a="Lord Shalzaru uncovered a mysterious ancient relic of unknown origin and power during an excavation on the Isle of Dread. Mainland factions seek champions to claim it.",al={"shalzaru relic","mysterious relic feralas"}},{q="Why must Lord Shalzaru be defeated?",a="Defeating Lord Shalzaru breaks Hatecrest leadership on the Isle of Dread and lets champions recover his relic before the naga can harness it.",al={"against lord shalzaru","kill lord shalzaru"}},{q="What are the Hatecrest digging for in Feralas?",a="The Hatecrest search ruined Night Elf settlements shattered in the Great Sundering. They seek powerful magical relics and remnants of Highborne history beneath soil and waves.",al={"hatecrest excavation","why are naga in feralas"}}},ang={["race:NightElf"]="As a Night Elf, you know the Hatecrest violate Kalimdor’s ancient ruins. Reclaiming Shalzaru’s relic keeps the Highborne’s dark legacy from empowering his naga kin.",["faction:Alliance"]="As an Alliance member, securing Shalzaru’s relic and stopping the Hatecrest warlord helps protect remote Alliance outposts on Feralas’s untamed coast.",["faction:Horde"]="As a member of the Horde, you know scouts watch Feralas’s coastal threats. Striking down the naga lord removes an unpredictable danger near Camp Mojache’s sphere of interest."},kw={"feralas","hatecrest","isle of dread","lord shalzaru","mysterious relic","naga","shalzaru"},rel={"subzone:isle-of-dread","zone:feralas","topic:naga"},src={"Lord Shalzaru"}}
E["npc:shandris-feathermoon"] = {t="npc",n="Shandris Feathermoon",z="feralas",s="At Feathermoon Stronghold on Sardor Isle, Shandris Feathermoon commands night elf forces across Kalimdor. For ten thousand years, she has served as Tyrande Whisperwind's right hand.",h="At Feathermoon Stronghold on Sardor Isle, Shandris Feathermoon commands night elf forces across Kalimdor.",sec={{t="Tyrande's Right Hand",b="For ten thousand years, Shandris Feathermoon has stood beside Tyrande Whisperwind as her right hand among the Sentinels. She is one of the night elves' oldest defenders, serving through the long vigil that followed the Sundering.",sp=0},{t="Rise of the Sentinels",b="After the Great Sundering, the Sentinels were founded. Shandris became an indispensable commander in the night elf military.",sp=0},{t="The Bastion of Feralas",b="From Sardor Isle, General Shandris Feathermoon commands the Sentinel army in the field and oversees Feathermoon Stronghold. The elven fortress watches over Feralas's primal wilds. From the island outpost, she monitors savage gnolls, lingering Gordunni ogres, hate-fueled satyrs, and the Horde's growing power in southern Kalimdor.",sp=0}},faq={{q="Who is Shandris Feathermoon?",a="Shandris Feathermoon commands the Sentinel army, the night elves' standing military force. For ten thousand years, she has served as High Priestess Tyrande Whisperwind's right hand and led the Sentinels from Feathermoon Stronghold in Feralas.",al={"who is shandris","shandris lore","who is the night elf general in feralas"}},{q="Where can Shandris Feathermoon be found?",a="Shandris commands from Feathermoon Stronghold on Sardor Isle, off Feralas's western coast in southern Kalimdor.",al={"shandris location","where is shandris feathermoon","feathermoon stronghold leader"}},{q="What is Shandris's relationship to Tyrande Whisperwind?",a="For ten thousand years, Shandris has served Tyrande Whisperwind as her right hand among the Sentinels. Tyrande leads the night elves from Darnassus, while Shandris commands the Sentinel army in the field from Feathermoon Stronghold.",al={"is shandris tyrande daughter","tyrande and shandris","tyrande adopted child"}},{q="Did Shandris fight against the Burning Legion?",a="The histories told here record no battle against the Burning Legion. Shandris has served beside Tyrande Whisperwind among the Sentinels for ten thousand years and now commands the army from Feathermoon Stronghold.",al={"war of the ancients shandris","did shandris fight archimonde"}},{q="Why is she stationed in Feralas instead of Teldrassil?",a="As General of the Sentinels, Shandris directs frontline military operations across Kalimdor. Feathermoon Stronghold is the Alliance's primary staging ground and bulwark in the wild southern forests, watching hostile ogres, satyrs, and Horde activity.",al={"why is shandris in feralas","why feathermoon stronghold"}}},ang={["race:NightElf"]="As a Kaldorei, you can look to General Feathermoon as a model of Sentinel discipline and duty. She has guarded your people since the long vigil began.",["class:Hunter"]="As a hunter, you can look to Shandris as one of the Sentinels' finest marksmen. She has watched over the night elves for ten thousand years.",["faction:Alliance"]="As an Alliance soldier in southern Kalimdor, you can rely on General Feathermoon for naval presence, strategic leadership, and a fortified sanctuary on Sardor Isle.",["faction:Horde"]="As a member of the Horde, you face General Feathermoon, a dangerous and cunning tactician. Her fortress off the Feralas coast threatens your expansion in the region."},kw={"feathermoon","feralas","general","kaldorei","sardor isle","sentinels","shandris","tyrande"},rel={"subzone:feathermoon-stronghold-classic","npc:tyrande-whisperwind","zone:feralas","topic:sentinels","quest:1043"},src={"Shandris Feathermoon"}}
E["npc:sprite-darter"] = {t="npc",n="Sprite Darter",z="feralas",s="Among Feralas's ancient trees, Sprite Darters flit while the Grimtotem seek to capture them. These rare faerie dragons are revered for their spiritual and magical qualities.",h="Among Feralas's ancient trees, Sprite Darters flit while the Grimtotem seek to capture them.",sec={{t="Faerie Dragons of the Wild",b="Sprite Darters glide through Feralas's ancient forests on iridescent wings. Shy and peaceful, these elusive woodland beasts draw the attention of those who study Kalimdor's wild places for their natural power and resistance to magic.",sp=0},{t="Grimtotem Captivity",b="The Grimtotem tauren of Feralas have begun rounding up and caging many Sprite Darters, though no one knows why. Kindal Moonweaver, a concerned night elf, seeks allies to break the cages and free the trapped hatchlings before the Grimtotem bend them to their will.",sp=0},{t="Spiritual Interest",b="Sprite Darters also interest those who study primal power. At Camp Mojache, Witch Doctor Uzer'i, a troll spiritualist, studies the natural energies and muisek within them. He seeks their essence to understand the unique magic thriving throughout Feralas.",sp=0}},faq={{q="What are Sprite Darters?",a="Sprite Darters are small faerie dragons found in Feralas's wilderness. Their shimmering wings, bond with nature, and elusive magic set them apart.",al={"sprite darter info","what is a sprite darter","are sprite darters dragons"}},{q="Why are the Grimtotem tauren capturing them?",a="No one knows why the Grimtotem are capturing Sprite Darters. The clan has been netting and caging many in the woods, perhaps to exploit their rare spiritual and magical qualities.",al={"why grimtotem cages","grimtotem sprite darters","why are darters caged"}},{q="Who is trying to protect the Sprite Darters?",a="Kindal Moonweaver works to protect Sprite Darters. The elf in Feralas calls on allies to break Grimtotem cages and free the captives.",al={"who protects sprite darters","kindal moonweaver sprite darters","alliance sprite darter quest"}},{q="Why is Witch Doctor Uzer'i interested in Sprite Darters?",a="Witch Doctor Uzer'i seeks the essence, or muisek, of Sprite Darters to learn about Feralas's primal spiritual forces and magical wildlife.",al={"witch doctor uzeri sprite darter","uzeri darter quest"}},{q="Can you raise a Sprite Darter?",a="Those who help Kindal Moonweaver free captive hatchlings and defend their nests may be entrusted with a rare Sprite Darter Egg to rear and protect.",al={"sprite darter egg","sprite darter pet","can i get a sprite darter"},sp=1},{q="Are Sprite Darters hostile?",a="Wild Sprite Darters are generally skittish and passive toward travelers. If threatened or provoked, they defend themselves with bursts of nature magic.",al={"are sprite darters dangerous","do sprite darters attack"}}},ang={["race:NightElf"]="As a night elf, you revere faerie dragons as sacred wardens of the forest. Freeing captured Sprite Darters from the Grimtotem is part of caring for the woods.",["faction:Alliance"]="As an ally of Kindal Moonweaver, you can help free captive hatchlings in Feralas and hinder the hostile Grimtotem tribe.",["faction:Horde"]="As a troll spiritualist, you may study spiritual muisek and Feralas's ancient essence, as Witch Doctor Uzer'i does at Camp Mojache.",["class:Druid"]="As a druid, you regard faerie dragons as kin to nature spirits. Their capture by poachers disrupts the forest's balance."},kw={"darter egg","faerie dragon","feralas","grimtotem","kindal moonweaver","muisek","sprite darter","witch doctor uzer'i"},rel={"zone:feralas","npc:kindal-moonweaver","npc:witch-doctor-uzer-i","topic:tauren","topic:alliance","topic:horde"},src={"Sprite Darter"}}
E["npc:witch-doctor-uzer-i"] = {t="npc",n="Witch Doctor Uzer'i",z="feralas",s="At Camp Mojache, Witch Doctor Uzer'i seeks to bind the spirits of powerful natural creatures into weapons for the Horde. He calls those lingering spirits muisek and studies magic the night elves have used for millennia.",h="At Camp Mojache, Witch Doctor Uzer'i seeks to bind the spirits of powerful natural creatures into weapons for...",sec={{t="Harnessing the Muisek",b="Witch Doctor Uzer'i studies Feralas's natural magic through the old rites of troll spiritualism. Night elves have drawn on forest beast spirits for millennia, and Uzer'i believes the Horde should claim that power. He calls a creature's lingering spirit muisek. His vessels shrink fallen beings and trap their spirits before they escape, so he can store and study their essence.",sp=0},{t="Grisly Bargains and Ritual Vessels",b="Uzer'i needed rare reagents to finish his vessels. After killing an Alliance dwarf in the Feralas timber, he severed the dwarf's head and arranged a trade with Neeru Fireblade, a warlock in Orgrimmar's Cleft of Shadow. Neeru gave him rare herbs for the grisly prize, and Uzer'i completed his first vessels. He could then capture the spirits of local wildkin, hippogryphs, faerie dragons, treants, and mountain giants.",sp=1},{t="Forging Weapons of Spirit",b="Capturing muisek is only the beginning of Uzer'i's ambition. He gathers sinew, enchanted minerals, and petrified splintered logs from the creatures whose spirits he traps. Then he joins those materials with bound muisek. Through his rites, he binds ancient forest spirits into weapons for the Horde. Uzer'i also follows rumors of hidden places of power across Azeroth, including the ancient, submerged Sunken Temple.",sp=0}},faq={{q="What is muisek?",a="Muisek is the lingering spiritual essence of living creatures. Uzer'i uses enchanted vessels to shrink slain beasts and natural guardians, trapping their spirits before they disperse.",al={"what is muisek","muisek meaning","define muisek"}},{q="Why is Uzer'i trading dwarf heads to Orgrimmar?",a="Uzer'i needed rare reagents for his ritual vessels. After killing an Alliance dwarf in Feralas, he traded the severed head to Neeru Fireblade in Orgrimmar for herbs to bind muisek spirits.",al={"dwarf head quest","why send head to neeru","neeru fireblade trade"}},{q="What kind of creatures does Uzer'i target?",a="Uzer'i targets creatures tied to the natural world and long allied with the night elves. They include wildkin from the Hinterlands, along with hippogryphs, faerie dragons, treants, and mountain giants in Feralas.",al={"what beasts does uzeri hunt","uzeri spirit targets","which animals for muisek"}},{q="What does Uzer'i do with the captured spirits?",a="Uzer'i joins captured muisek with natural materials such as splintered logs, sinew, and minerals. He binds the spirits into weapons, giving them the power of ancient forest guardians.",al={"weapons of spirit","why collect muisek","muisek weapon rewards"}},{q="Where is Witch Doctor Uzer'i located?",a="Witch Doctor Uzer'i lives at Camp Mojache, the Horde's main settlement beneath central Feralas's canopy.",al={"uzeri location","where is uzeri","witch doctor uzeri spot"}},{q="What does Uzer'i know about the Sunken Temple?",a="Uzer'i has heard of the submerged Atal'ai sanctuary called the Sunken Temple. He directs those who want to investigate it to Marvon Rivetseeker, a goblin explorer.",al={"uzeri sunken temple","sunken temple feralas quest","temple of atal hakkar uzeri"}}},ang={["faction:Horde"]="As a member of the Horde, you can see Uzer'i's work to master Kalimdor's primal magic and turn it against the Alliance, including the night elves.",["race:Troll"]="As a troll, you can recognize Uzer'i's traditional witch doctor rites, shrunken vessels, and voodoo used to harness life essences.",["class:Shaman"]="As a shaman, you can recognize Uzer'i's focus on communion with spirits. His forceful capture of elemental and wild essences favors witchery over reverent balance.",["race:NightElf"]="As a night elf, you can see why Uzer'i's practices are blasphemous. Sacred treants, hippogryphs, and mountain giants are killed and bound into weapons."},kw={"camp mojache","faerie dragon","feralas","mountain giant","muisek","neeru fireblade","treant","uzer'i","witch doctor"},rel={"subzone:camp-mojache","zone:feralas","quest:829","topic:troll","topic:horde","subzone:high-wilderness","zone:hinterlands","zone:orgrimmar"},src={"Witch Doctor Uzer'i"}}
E["quest:2766"] = {t="quest",n="Find OOX-22/FE!",z="feralas",s="A homing robot has crashed in Feralas, and Oglethorpe Obnoticus calls for help through a strange metal egg. Carry its beacon to a cave near Feral Scar Vale.",h="A homing robot has crashed in Feralas, and Oglethorpe Obnoticus calls for help through a strange metal egg.",sec={{t="A Voice in the Egg",b="Turn the knob on the metal egg, and it opens into a gnomish contraption. Oglethorpe Obnoticus speaks from within. His homing robot has crashed, and he promises payment if you recover it. He has worked out that the machine lies in a cave near Feral Scar Vale. Carry the beacon there.",sp=0},{t="What the Cave Holds",b="A robotic chicken lies wrecked in the cave. Oglethorpe Obnoticus confirms it is his homing robot. It needs a jump-start before it can fly to Booty Bay for repairs. Place the beacon inside, and the robot whirs to life. Then Oglethorpe's voice comes from the robot itself.",sp=1}},faq={{q="Who is speaking through the distress beacon?",a="Oglethorpe Obnoticus speaks through the beacon. His homing robot has crashed, and he asks you to bring the beacon to it.",al={"who made the beacon","who is talking","oglethorpe who"}},{q="Where does the beacon point you to go?",a="The beacon points to a cave near Feral Scar Vale in Feralas. Oglethorpe has worked out the robot's coordinates.",al={"where is the robot","homing robot location","where to take beacon"}},{q="What is the beacon?",a="The beacon is a strange egg-shaped metal device. Turn its knob, and it opens into a gnomish contraption with a voice inside.",al={"what is the egg","what is oox-22/fe","distress beacon"}},{q="What comes after this step?",a="Rescue OOX-22/FE! follows.",al={"next quest","what follows find oox-22/fe","after the cave"}}},kw={"distress beacon","feral scar vale","feralas","homing robot","mechanical chicken","oglethorpe obnoticus","oox-22/fe"},rel={"quest:2767","subzone:feral-scar-vale","zone:feralas","subzone:booty-bay"},m={start="OOX-22/FE Distress Beacon",["end"]="Feral Scar Vale",level="45",faction="Neutral",id=2766},src={"Find OOX-22/FE!"}}
E["quest:2767"] = {t="quest",n="Rescue OOX-22/FE!",z="feralas",s="In Feral Scar Vale, OOX-22/FE! waits for your help on the way to the Forgotten Coast dock. Once it arrives, Oglethorpe Obnoticus wants to speak with you in Booty Bay.",h="In Feral Scar Vale, OOX-22/FE!",sec={{t="A Safe Place to Take Off",b="OOX-22/FE needs an open, safe place for its lengthy take-off. The gnome's voice crackles through the robot as he explains that its built-in cloaking needs time before it works again. Oglethorpe Obnoticus also needs time to make it work. He suggests the Forgotten Coast dock, where everything can be brought online. You escort the robot there from where it stands.",sp=0},{t="Afterwards, Booty Bay",b="Once OOX-22/FE reaches the dock safely, Oglethorpe Obnoticus wants you to speak with him in Booty Bay.",sp=0}},faq={{q="Where does OOX-22/FE need to go?",a="OOX-22/FE needs to reach the dock along the Forgotten Coast. You escort it from Feral Scar Vale, where you found it.",al={"where do i take the chicken","oox-22/fe destination","feralas chicken escort path"}},{q="Who is Oglethorpe Obnoticus?",a="Oglethorpe Obnoticus is a master inventor whose homing robot series includes OOX-22/FE. He speaks through the robot and can be found in Booty Bay.",al={"who made the robot chicken","who is oglethorpe obnoticus","chicken inventor"}},{q="Why does the robot need to reach the dock?",a="The dock offers an open, safe place for the lengthy take-off, and Oglethorpe says there is enough room to get everything online. The robot's built-in cloaking needs time before it works again.",al={"why escort oox-22","why walk to the dock"}},{q="Where do I report afterwards?",a="Once OOX-22/FE reaches the dock safely, speak to Oglethorpe Obnoticus in Booty Bay.",al={"where is oglethorpe","turn in location","who do i talk to after"}}},kw={"booty bay","feral scar vale","feralas","forgotten coast","homing robot","oglethorpe obnoticus","oox-22/fe","robot chicken"},rel={"quest:2766","subzone:feral-scar-vale","subzone:forgotten-coast","subzone:booty-bay","zone:feralas"},m={start="Homing Robot OOX-22/FE, Feral Scar Vale",["end"]="Oglethorpe Obnoticus, Booty Bay",level="45",id=2767},src={"Rescue OOX-22/FE!"}}
E["quest:2821"] = {t="quest",n="The Mark of Quality",z="feralas",s="At Feathermoon Stronghold, Pratt McGrubben seeks ten thick yeti hides and offers a choice of leather goods.",h="At Feathermoon Stronghold, Pratt McGrubben seeks ten thick yeti hides and offers a choice of leather goods.",sec={{t="Pratt's Philosophy",b="Pratt McGrubben, a leatherworker at Feathermoon Stronghold, insists on the finest work. In search of fine materials, he found thick yeti hides. Yetis are native to Feralas, and many live around Feral Scar Vale, just inland of the Forgotten Coast.",sp=0},{t="The Offer",b="Bring Pratt a stack of ten hides at Feathermoon Stronghold. In return, you may choose one of the leather goods he has crafted.",sp=0},{t="Pratt's Thoughts on the Hides",b="Pratt McGrubben asks whether you felt the hides’ texture. Properly treated, they could prove tougher than iron, and few people know of them. Pratt knows many treating solutions. He hopes to shape the hides into pieces worthy of a true mark of quality.",sp=1}},faq={{q="Who is asking for the hides?",a="Pratt McGrubben, the leatherworker at Feathermoon Stronghold, asks for the hides.",al={"quest giver","pratt mcgrubben","who gives the mark of quality"}},{q="Where can the yetis be found?",a="Around Feral Scar Vale, just inland of the Forgotten Coast, where many of Feralas's native yetis live.",al={"yeti location","where are yetis","feral scar vale"}},{q="How many hides does Pratt want?",a="Pratt wants ten hides in one stack.",al={"how many yeti hides","hide count"}},{q="What do I get for the hides?",a="Pratt offers your choice of one of the leather goods he has crafted in exchange for the stack.",al={"what does pratt give","mark of quality payment"}}},kw={"feathermoon stronghold","feral scar vale","feralas","forgotten coast","pratt mcgrubben","the mark of quality","thick yeti hide","yetis"},rel={"subzone:feathermoon-stronghold-classic","subzone:feral-scar-vale","zone:feralas","subzone:forgotten-coast"},m={start="Pratt McGrubben",["end"]="Pratt McGrubben",level="46",faction="Alliance",id=2821,ri={"Thick Yeti Hide"}},src={"The Mark of Quality (Classic Alliance)"}}
E["quest:2822"] = {t="quest",n="The Mark of Quality",z="feralas",s="At Camp Mojache, Jangdor Swiftstrider seeks ten thick yeti hides and will not compromise on quality.",h="At Camp Mojache, Jangdor Swiftstrider seeks ten thick yeti hides and will not compromise on quality.",sec={{t="A Matter of Pride",b="Jangdor Swiftstrider takes pride in fine leatherwork. He has found thick yeti hides in Feralas, where the yetis make their home. Many roam west of Camp Mojache in Feral Scar Vale, just inland of the Forgotten Coast.",sp=0},{t="The Offer",b="Bring Jangdor a stack of ten hides at Camp Mojache. In return, he will let you choose one of the leather goods he has made.",sp=0},{t="Jangdor's Thoughts on the Hides",b="Jangdor says special treatment can make the hides hold up as well as iron. Finding the right tanning mix will take many attempts. He believes these hides can raise his mark of quality higher than before.",sp=1}},faq={{q="Who is asking for the hides?",a="Jangdor Swiftstrider, the leatherworker at Camp Mojache in Feralas, is asking for the hides.",al={"who gives the quest","quest giver mark of quality","where is jangdor"}},{q="Where can the yetis be found?",a="Yetis make their home in Feralas. Many roam west of Camp Mojache in Feral Scar Vale, just inland of the Forgotten Coast.",al={"where are the yetis","yeti hide location","where is feral scar vale"}},{q="How many hides are required?",a="Ten hides, brought in one stack.",al={"how many yeti hides","yeti hide count","mark of quality requirement"}},{q="What do I get for the hides?",a="Jangdor offers you a choice of the leather goods he has made in exchange for the stack.",al={"what does jangdor give","mark of quality payment"}}},kw={"camp mojache","feral scar vale","feralas","forgotten coast","jangdor swiftstrider","leatherworking","thick yeti hide","yeti"},rel={"subzone:camp-mojache","subzone:feral-scar-vale","subzone:forgotten-coast","zone:feralas"},m={start="Jangdor Swiftstrider",["end"]="Jangdor Swiftstrider",level="46",faction="Horde",id=2822,ri={"Thick Yeti Hide"}},src={"The Mark of Quality (Classic Horde)"}}
E["quest:2844"] = {t="quest",n="The Giant Guardian",z="feralas",s="Rockbiter searches for Shay, the night elf girl he was meant to watch over. Worried, he asks you to look for her.",h="Rockbiter searches for Shay, the night elf girl he was meant to watch over.",sec={{t="Gone While His Back Was Turned",b="Rockbiter last saw Shay while they walked through the ruins just north of where he stands. Then he turned around, and she was gone. Unsure what to do, he asks you to search for his little friend. Your legs can carry you much faster than his.",sp=0},{t="When You Find Her",b="Shay is glad you found her. A little lost, she still cannot help remarking on what a beautiful place this is.",sp=1}},faq={{q="Who is Rockbiter looking for?",a="Rockbiter is looking for Shay, a little night elf girl and his friend. He was meant to watch over her.",al={"who is shay","who is the missing girl","who got lost"}},{q="Where was Shay last seen?",a="Rockbiter last saw Shay as they walked through the ruins just north of where he stands.",al={"where did shay go","last seen location","where are the ruins"}},{q="Why does Rockbiter ask someone else to search?",a="Rockbiter is worried and unsure what to do. He thinks your legs can carry you much faster than his.",al={"why cant rockbiter search","why send an adventurer"}}},kw={"feralas","giant guardian","lost girl","rockbiter","ruins","shay","shay leafrunner"},rel={"quest:2845","zone:feralas"},m={start="Rockbiter",["end"]="Shay Leafrunner",level="49",faction="Alliance",id=2844},src={"The Giant Guardian"}}
E["quest:2845"] = {t="quest",n="Wandering Shay",z="feralas",s="Shay Leafrunner is distracted by the sights along the way as she tries to return to Rockbiter, her friend.",h="Shay Leafrunner is distracted by the sights along the way as she tries to return to Rockbiter, her friend.",sec={{t="A Girl Easily Distracted",b="Shay was meant to be watched by Rockbiter. She wants to return to him, but the many things around her catch her eye and lead her astray.",sp=0},{t="The Bell in the Chest",b="A bell in the chest beside Shay always catches her attention, and she treasures its sound. If she wanders off, ring it and she promises to come running back. You can carry the bell to Rockbiter's camp, where Shay hopes to be taken.",sp=0}},faq={{q="Who is Shay Leafrunner trying to get back to?",a="Shay is trying to get back to her friend Rockbiter, who was meant to watch her. You can take her to his camp.",al={"who is rockbiter","shay friend","where does shay go"}},{q="Why does Shay wander off?",a="The many things to see distract Shay, so she wanders off.",al={"why is shay lost","how did shay get lost","why did shay wander off"}},{q="How do I keep Shay from straying?",a="Shay's bell is in a chest beside her, and she treasures its sound. She promises that ringing it will bring her running back if she wanders off.",al={"how to control shay","shay bell","what does the bell do"}},{q="What comes before this?",a="The Giant Guardian comes before this. Rockbiter sends you to look for Shay there.",al={"previous quest","giant guardian","what leads to wandering shay"}}},kw={"escort","feralas","giant guardian","rockbiter","shay leafrunner","shay's bell"},rel={"quest:2844","zone:feralas"},m={start="Shay Leafrunner",["end"]="Rockbiter",level="49",faction="Alliance",id=2845,ri={"Shay's Bell"}},src={"Wandering Shay"}}
E["quest:2855"] = {t="quest",n="Wild Leather Shoulders",z="feralas",s="In Camp Mojache, Jangdor Swiftstrider seeks supplies to craft Wild Leather Shoulders. He needs six thick armor kits and a wildvine brought to his workshop.",h="In Camp Mojache, Jangdor Swiftstrider seeks supplies to craft Wild Leather Shoulders.",sec={{t="Supplies for Jangdor",b="Jangdor Swiftstrider makes his camp among the Horde in Camp Mojache. To craft Wild Leather Shoulders, he requires six thick armor kits and a single wildvine brought directly to him.",sp=0}},faq={{q="Who wants the Wild Leather Shoulders supplies?",a="Jangdor Swiftstrider seeks the materials in Camp Mojache.",al={"who gives wild leather shoulders","jangdor swiftstrider quest","who needs thick armor kits camp mojache"}},{q="Where is Jangdor Swiftstrider?",a="Jangdor Swiftstrider stays in Camp Mojache.",al={"jangdor swiftstrider location","where is jangdor","camp mojache leatherworker"}},{q="What items does Jangdor Swiftstrider need?",a="He needs six thick armor kits and one wildvine.",al={"wild leather shoulders materials","thick armor kits needed","what does jangdor need"}}},kw={"camp mojache","jangdor swiftstrider","thick armor kit","wild leather shoulders","wildvine"},rel={"subzone:camp-mojache"},m={faction="Horde",id=2855},src={"In-game quest text: Wild Leather Shoulders"},fv=true}
E["quest:2856"] = {t="quest",n="Wild Leather Vest",z="feralas",s="Jangdor Swiftstrider at Camp Mojache requires specialized goods from skilled crafters. You are asked to supply turtle scale armor pieces along with a rare wildvine.",h="Jangdor Swiftstrider at Camp Mojache requires specialized goods from skilled crafters.",sec={{t="Supplies for Camp Mojache",b="Turtle scale armor and rare wildvine must be gathered across the wilds. Carrying the finished breastplates, gloves, and vine to Camp Mojache fulfills Jangdor Swiftstrider's request.",sp=0}},faq={{q="What materials does Jangdor Swiftstrider require?",a="He asks for two Turtle Scale Breastplates, two Turtle Scale Gloves, and a Wildvine.",al={"wild leather vest items","what do i bring jangdor","jangdor swiftstrider materials"}},{q="Where is Jangdor Swiftstrider found?",a="Jangdor Swiftstrider makes his camp at Camp Mojache.",al={"where is jangdor swiftstrider","jangdor swiftstrider location","who gives wild leather vest"}},{q="What is Camp Mojache?",a="Camp Mojache is the Horde settlement where Jangdor Swiftstrider waits for his leatherwork supplies.",al={"what is camp mojache","where is camp mojache"}}},kw={"camp mojache","jangdor swiftstrider","turtle scale breastplate","turtle scale gloves","wild leather vest","wildvine"},rel={"subzone:camp-mojache"},m={faction="Horde",id=2856},src={"In-game quest text: Wild Leather Vest"},fv=true}
E["quest:2857"] = {t="quest",n="Wild Leather Helmet",z="feralas",s="Jangdor Swiftstrider at Camp Mojache seeks skilled materials to shape a Wild Leather Helmet. Bringing him Nightscape armor and Wildvine allows the tauren artisan to ply his craft in Feralas.",h="Jangdor Swiftstrider at Camp Mojache seeks skilled materials to shape a Wild Leather Helmet.",sec={{t="The Crafter at Camp Mojache",b="At Camp Mojache, Jangdor Swiftstrider works his craft among the Horde travelers of Feralas. To fashion a Wild Leather Helmet, he requires two Nightscape Tunics, two Nightscape Headbands, and a single stem of Wildvine. If you bring him these tailored pieces and rare jungle vines, he can finish the headpiece.",sp=0}},faq={{q="Who is Jangdor Swiftstrider?",a="Jangdor Swiftstrider makes his camp at Camp Mojache, where he trades with travelers and works leather.",al={"who is jangdor swiftstrider","where is jangdor","jangdor swiftstrider location"}},{q="Where is Camp Mojache?",a="Camp Mojache is a Horde outpost in the forests of Feralas.",al={"where is camp mojache","camp mojache location"}},{q="What items does Jangdor Swiftstrider ask for?",a="Jangdor Swiftstrider requires two Nightscape Tunics, two Nightscape Headbands, and a stem of Wildvine.",al={"what materials does jangdor need","wild leather helmet materials","items needed for wild leather helmet"}}},kw={"camp mojache","feralas","jangdor swiftstrider","nightscape headband","nightscape tunic","wild leather helmet","wildvine"},rel={"subzone:camp-mojache"},m={faction="Horde",id=2857},src={"In-game quest text: Wild Leather Helmet"},fv=true}
E["quest:2862"] = {t="quest",n="War on the Woodpaw",z="feralas",s="At Camp Mojache, Hadoken Swiftstrider asks you to thin the Woodpaw gnolls’ growing numbers. Their attacks have grown more fevered, and ten Woodpaw Gnoll Manes will answer his call.",h="At Camp Mojache, Hadoken Swiftstrider asks you to thin the Woodpaw gnolls’ growing numbers.",sec={{t="A Threat to the Camp",b="Hadoken Swiftstrider says the camp’s survival matters more than the gnolls’ claim to Feralas. Unless Camp Mojache stands firm, he warns, the gnolls may drive it from the whole region. Their attacks have grown more fevered, so he wants their numbers thinned. For ten Woodpaw gnoll manes, he offers generous pay.",sp=0},{t="Hadoken's Response",b="Hadoken Swiftstrider calls the manes a good start. He has made the same request of others who have fought the gnolls before, and their efforts once held them back. Lately, the gnolls have pushed north into the area Camp Mojache holds sway over far more often. Their attacks have turned savage, almost desperate. Hadoken says he has a plan that might settle the matter.",sp=1}},faq={{q="Who offers this bounty in Feralas?",a="Hadoken Swiftstrider offers the bounty at Camp Mojache.",al={"who gives war on the woodpaw","where to turn in war on the woodpaw","quest giver war on the woodpaw"}},{q="Why is Camp Mojache targeting the Woodpaw gnolls?",a="Hadoken regards the Woodpaw gnolls as a constant danger to Camp Mojache. Their attacks have grown more fevered, and he fears the camp will be driven from the whole region unless it stands firm.",al={"why fight woodpaw","woodpaw problem","why are gnolls attacking"}},{q="What proof does Hadoken Swiftstrider require?",a="Hadoken Swiftstrider requires ten Woodpaw Gnoll Manes.",al={"what items needed war on the woodpaw","woodpaw quest items","what do i bring hadoken"}}},kw={"alpha strike","camp mojache","feralas","gnolls","hadoken swiftstrider","manes","woodpaw"},rel={"subzone:camp-mojache","zone:feralas","topic:gnoll"},m={start="Hadoken Swiftstrider",["end"]="Hadoken Swiftstrider",level="42",faction="Horde",id=2862},src={"Classic quest text: War on the Woodpaw"}}
E["quest:2863"] = {t="quest",n="Alpha Strike",z="feralas",s="The Horde's stalemate with the Woodpaw gnolls may be broken by striking their leaders in quick succession. Hadoken Swiftstrider asks you to bring down five Alphas within one hour.",h="The Horde's stalemate with the Woodpaw gnolls may be broken by striking their leaders in quick succession.",sec={{t="Five Alphas in an Hour",b="Hadoken Swiftstrider believes the Woodpaw ranks will fall into chaos if their Alphas die one after another. The blows may also show the gnolls that the Horde can destroy them. He asks you to carry out the plan. Five Alphas must fall within one hour, or the stalemate continues.",sp=0},{t="Afterwards",b="Hadoken Swiftstrider expects the slain leaders and thinner ranks to make the gnolls hesitate before storming the camp. He still needs to learn what has driven them into such a frenzy. He hopes to find out before they regroup.",sp=1}},faq={{q="Who gives this quest?",a="Hadoken Swiftstrider gives you this work as he faces the Horde's stalemate against the Woodpaw gnolls.",al={"who gives alpha strike","hadoken swiftstrider","quest giver"}},{q="Why the one-hour limit?",a="The plan depends on the Alphas falling in quick succession to throw the gnoll ranks into chaos. Five must fall within one hour.",al={"why one hour","why rapid succession","alpha strike timer"}},{q="What are the Alphas?",a="The Alphas are leaders among the Woodpaw gnolls, who call themselves Alphas.",al={"woodpaw alphas","gnoll alphas","who are the targets"}},{q="How many Alphas must I kill?",a="You must kill five Alphas within one hour, then return to Hadoken Swiftstrider.",al={"how many alphas","alpha count"}}},kw={"alpha strike","feralas","gnolls","hadoken swiftstrider","woodpaw","woodpaw alpha"},rel={"zone:feralas","topic:gnoll"},m={start="Hadoken Swiftstrider",["end"]="Hadoken Swiftstrider",level="43",faction="Horde",id=2863},src={"Alpha Strike (Classic)"}}
E["quest:2866"] = {t="quest",n="The Ruins of Solarsal",z="feralas",s="South of Shandris Feathermoon, Hatecrest naga crowd the Ruins of Solarsal. She sends you among the old stones to look for anything out of the ordinary.",h="South of Shandris Feathermoon, Hatecrest naga crowd the Ruins of Solarsal.",sec={{t="Naga in the Old Stones",b="Shandris Feathermoon says explorers searched the ruins long ago and found nothing of note. So the stones were left alone. Now Hatecrest naga have taken them in alarming numbers. Their presence first seemed to herald an attack, and that danger remains. Yet Shandris suspects something else may be happening. She asks you to walk through the ruins and notice anything out of the ordinary.",sp=0},{t="What Stands Out",b="A gazebo differs from the surrounding stonework and is plainly newer. Small glyphs repeat along its sides, though no one knows where they came from or what they mean. The stone is warm to the touch.",sp=1}},faq={{q="Where are the Ruins of Solarsal?",a="The ruins lie south of Shandris Feathermoon.",al={"ruins of solarsal location","where is solarsal","where to find solarsal"}},{q="Why is Shandris Feathermoon concerned about the ruins?",a="Hatecrest naga have occupied the ruins in alarming numbers. Their presence first seemed like preparation for an attack, and that remains possible. Shandris suspects something else may be happening.",al={"why send me to solarsal","shandris feathermoon solarsal reason","why investigate solarsal"}},{q="What were the Ruins of Solarsal before the naga arrived?",a="The ruins pre-date modern times. Shandris says they were explored long ago, but nothing of note was found, so they were left alone.",al={"solarsal history","what is solarsal"}},{q="Which naga are in the ruins?",a="Hatecrest naga are in the ruins.",al={"who is at solarsal","solarsal enemies","naga tribe in solarsal"}}},kw={"feathermoon stronghold","feralas","gazebo","glyphs","hatecrest","naga","shandris feathermoon","solarsal"},rel={"npc:shandris-feathermoon","quest:2867","topic:naga","zone:feralas"},m={start="Shandris Feathermoon",["end"]="Solarsal Gazebo",level="43",faction="Alliance",id=2866},src={"The Ruins of Solarsal"}}
E["quest:2867"] = {t="quest",n="Return to Feathermoon Stronghold",z="feralas",s="You return to Feathermoon Stronghold with news of a strange gazebo at the heart of the Ruins of Solarsal. General Shandris Feathermoon awaits your report.",h="You return to Feathermoon Stronghold with news of a strange gazebo at the heart of the Ruins of Solarsal.",sec={{t="Carrying the Report Home",b="At Feathermoon Stronghold, General Shandris Feathermoon awaits your news of the strange gazebo. You carry your findings back from the heart of the ruins so she can hear what you saw.",sp=0},{t="On Your Return",b="Shandris finds your report on the gazebo disturbing. The naga may not have meant to attack, yet their continued presence bodes ill for the push into Feralas. Feathermoon Stronghold needs more help against the Hatecrest naga, and Shandris offers you further work if you are willing.",sp=1}},faq={{q="Who do I report to after the ruins?",a="Report to General Shandris Feathermoon at Feathermoon Stronghold.",al={"who do i turn this in to","who wants the report","where to turn in return to feathermoon stronghold"}},{q="What should I report?",a="Tell General Shandris Feathermoon about the strange gazebo at the center of the Ruins of Solarsal.",al={"what do i tell shandris","what was found at solarsal"}},{q="What comes before this?",a="The Ruins of Solarsal comes before your return. Shandris sent you to explore the ruins and investigate the naga there.",al={"previous quest","what leads here"}}},kw={"feathermoon stronghold","feralas","hatecrest","naga","ruins of solarsal","shandris feathermoon","solarsal gazebo"},rel={"quest:2866","npc:shandris-feathermoon","subzone:feathermoon-stronghold-classic","zone:feralas","topic:naga"},m={start="Solarsal Gazebo",["end"]="Shandris Feathermoon",level="43",faction="Alliance",id=2867},src={"Return to Feathermoon Stronghold"}}
E["quest:2869"] = {t="quest",n="Against the Hatecrest",z="feralas",s="At Feathermoon Stronghold, Latronicus Moonspear means to face the Hatecrest naga before they make their move. He asks you to bring him ten Hatecrest Scales in good condition.",h="At Feathermoon Stronghold, Latronicus Moonspear means to face the Hatecrest naga before they make their move.",sec={{t="Acting Before It Is Too Late",b="Latronicus Moonspear expects the naga to try to claim the island someday. He wants to act before they can, so he asks you to bring ten Hatecrest Scales in good condition. You will have to see for yourself how to get them. He hopes gathering the scales will weaken the naga presence on Sardor Isle and give you your first taste of fighting naga.",sp=0},{t="Peace and Duty",b="Latronicus says night elves cherish peace and harmony, not war. Still, he will not leave their interests unguarded. Protecting them is his duty to General Feathermoon and the stronghold.",sp=0},{t="Afterwards",b="Latronicus finds the scales more than satisfactory. He plans to send them to Pratt in case anything useful can be crafted from them. He also has another task for you.",sp=1}},faq={{q="Who gives this quest and where?",a="Latronicus Moonspear asks for the scales and receives them at Feathermoon Stronghold.",al={"who starts against the hatecrest","latronicus moonspear location","where to turn in against the hatecrest"}},{q="Why does Latronicus Moonspear want Hatecrest scales?",a="Latronicus expects the naga to try to secure Sardor Isle someday, so he wants to act first. Gathering scales may weaken their presence there.",al={"why kill hatecrest","hatecrest scale purpose","why collect naga scales"}},{q="How many scales are needed?",a="You need ten Hatecrest Scales in good condition.",al={"how many scales","scale count"}},{q="Where are the Hatecrest naga found?",a="Latronicus speaks of a naga presence on Sardor Isle.",al={"hatecrest location","where to find hatecrest","sardor isle naga"}}},kw={"against the hatecrest","feathermoon stronghold","feralas","hatecrest","hatecrest naga scale","latronicus moonspear","naga","sardor isle"},rel={"subzone:feathermoon-stronghold-classic","subzone:sardor-isle","topic:naga","zone:feralas"},m={start="Latronicus Moonspear",["end"]="Latronicus Moonspear",level="43",faction="Alliance",id=2869,ri={"Hatecrest Naga Scale"}},src={"Against the Hatecrest (2)"}}
E["quest:2870"] = {t="quest",n="Against Lord Shalzaru",z="feralas",s="At Feathermoon Stronghold, Latronicus Moonspear asks you to stop Lord Shalzaru and recover the relic he found.",h="At Feathermoon Stronghold, Latronicus Moonspear asks you to stop Lord Shalzaru and recover the relic he found.",sec={{t="The Naga Chain of Command",b="Latronicus Moonspear has fresh reports on the naga chain of command. Royals give orders among their ranks. Lord Shalzaru is one of the crueler royals.",sp=0},{t="An Odd Relic",b="Scouts say Lord Shalzaru uncovered an odd relic while the naga dug in a cave on the Isle of Dread. The cave lies over the water, south of the main ruins. Latronicus wants you to stop Shalzaru and end the dig. Then bring the Mysterious Relic to Feathermoon Stronghold for study.",sp=0},{t="When It Is Done",b="Lord Shalzaru's fall may leave the naga in disarray for a while, Latronicus believes, perhaps for good. He thinks the threat is now more under control than ever. He has one more thing to ask of you.",sp=1}},faq={{q="Who is Lord Shalzaru?",a="Lord Shalzaru is one of the crueler naga royals. Royals give the orders among the naga ranks.",al={"shalzaru","who is shalzaru","lord shalzaru lore"}},{q="Where is Lord Shalzaru located?",a="Scouts place Lord Shalzaru's dig in a cave on the Isle of Dread, over the water and south of the main ruins.",al={"where is shalzaru","shalzaru cave location","find shalzaru"}},{q="What is the relic?",a="The Mysterious Relic is an odd object Lord Shalzaru uncovered while the naga were digging. Latronicus wants you to bring it to him for study.",al={"mysterious relic feralas","what is the relic","shalzaru relic"}},{q="Where do I deliver the relic?",a="Bring the relic to Latronicus Moonspear at Feathermoon Stronghold.",al={"who gets the relic","turn in shalzaru"}}},kw={"feathermoon stronghold","feralas","hatecrest","isle of dread","latronicus moonspear","lord shalzaru","mysterious relic","naga","shalzaru"},rel={"npc:lord-shalzaru","subzone:isle-of-dread","subzone:feathermoon-stronghold-classic","quest:2871","quest:2869","topic:naga","zone:feralas"},m={start="Latronicus Moonspear",["end"]="Latronicus Moonspear",level="45",faction="Alliance",id=2870,ri={"Mysterious Relic"}},src={"Against Lord Shalzaru"}}
E["quest:2871"] = {t="quest",n="Delivering the Relic",z="feralas",s="At Feathermoon Stronghold, Latronicus Moonspear sends you with the Mysterious Relic to his wife Vestia. He cannot make sense of it, and hopes she can tell what it is.",h="At Feathermoon Stronghold, Latronicus Moonspear sends you with the Mysterious Relic to his wife Vestia.",sec={{t="A Scholar's Eye",b="Latronicus Moonspear cannot make sense of the device, wager or no wager. He says his wife Vestia is a fine priestess to their community and one of the most learned scholars anywhere. If anyone can work out what the relic is, she can. They need to know. Vestia is only a short walk away, though she is surely busy studying.",sp=0},{t="Vestia's First Look",b="Vestia Moonspear knows you have aided General Feathermoon and Latro against the naga. At first glance, the relic does not seem to come from the ruins where it was found, nor does it bear naga design. It is something far more alien. Studying it will take time. When she is done, she may call on your talents if you are nearby.",sp=1}},faq={{q="Who is Vestia Moonspear?",a="Vestia Moonspear is Latronicus Moonspear's wife. He calls her a fine priestess to their community and one of the most learned scholars anywhere. She is at Feathermoon Stronghold.",al={"vestia moonspear","who is vestia","latro wife"}},{q="Where does the Mysterious Relic come from?",a="The Mysterious Relic is the relic Lord Shalzaru uncovered when the naga were digging in a cave on the Isle of Dread.",al={"where did the relic come from","relic origin","mysterious relic source"}},{q="What does Latronicus Moonspear know about the relic?",a="Latronicus Moonspear knows little about the relic. He cannot make heads or tails of the device, so he wants his wife to examine it.",al={"what does latronicus know","latro device"}},{q="Where do I take the relic?",a="Take the Mysterious Relic to Vestia Moonspear at Feathermoon Stronghold. Latronicus says she is just around the bend.",al={"who gets the relic","delivering the relic destination"}}},kw={"delivering the relic","feathermoon stronghold","feralas","latronicus moonspear","mysterious relic","vestia moonspear"},rel={"quest:2870","npc:lord-shalzaru","topic:naga","zone:feralas"},m={start="Latronicus Moonspear",["end"]="Vestia Moonspear",level="45",faction="Alliance",id=2871},src={"Delivering the Relic"}}
E["quest:2879"] = {t="quest",n="The Stave of Equinex",z="feralas",s="At the Ruins of Ravenwind, Troyas Moonbreeze tests whether his stave can open the Equinex Monolith. You gather the essences of four flames still burning among the ruins.",h="At the Ruins of Ravenwind, Troyas Moonbreeze tests whether his stave can open the Equinex Monolith.",sec={{t="A Key for the Monolith",b="Troyas Moonbreeze thinks his stave may be the Stave of Equinex, a key to the Equinex Monolith in the Ruins of Ravenwind. Four flames still burn there: Samha, Imbel, Byltan and Lahassa. Each yields an essence. You use all four at the monolith to energize the stave. If it is truly the key, the monolith will open and reveal a sacred artifact.",sp=0},{t="At the Stone",b="The energized stave is almost impossible to hold as its power rumbles through you. You reach for the monolith's cold surface, and a small door opens. Beams of light spill around the stone as you take what lies inside.",sp=1}},faq={{q="Where is the Equinex Monolith located?",a="The Equinex Monolith stands in the Ruins of Ravenwind, west of the Dream Bough on the mainland.",al={"equinex monolith location","where is monolith","find equinex monolith"}},{q="What are the four flames I need?",a="The four flames are Samha, Imbel, Byltan and Lahassa. They still burn in the Ruins of Ravenwind, and you gather the essence of each.",al={"four flames","flame names feralas","ravenwind flames"}},{q="What is the Stave of Equinex for?",a="Troyas Moonbreeze says the Stave of Equinex may be a key to the Equinex Monolith, which holds a sacred artifact.",al={"what does the stave do","stave of equinex purpose","why energize stave"}},{q="Where do I energize the stave?",a="You energize the stave beside the Equinex Monolith, using the essences of all four flames.",al={"where to use essences","energize stave location"}}},kw={"byltan","dream bough","equinex monolith","feralas","imbel","lahassa","ruins of ravenwind","samha","stave of equinex","troyas moonbreeze"},rel={"quest:2943","subzone:ruins-of-ravenwind","subzone:dream-bough","zone:feralas"},m={start="Troyas Moonbreeze",["end"]="Equinex Monolith",level="50",faction="Alliance",id=2879,ri={"Stave of Equinex"}},src={"The Stave of Equinex"}}
E["quest:2902"] = {t="quest",n="Woodpaw Investigation",z="feralas",s="At Camp Mojache, Hadoken Swiftstrider suspects the Woodpaw gnolls are following written plans. He sends you south to search their camps for battle plans.",h="At Camp Mojache, Hadoken Swiftstrider suspects the Woodpaw gnolls are following written plans.",sec={{t="A Search for Plans",b="After Alpha Strike, Hadoken Swiftstrider sends you back to the Woodpaw. He doubts the gnolls are clever, yet their recent assaults have been too well coordinated to be chance. He suspects they keep a written record of their strategy. If you find it, he may learn what stirred them up, so he asks you to search the camps and bring back anything that looks like battle plans.",sp=0},{t="What the Map Shows",b="The map gives Hadoken the plans he sought. Arrows cross it and may mark troop movements, though most point south, away from Camp Mojache to the north. Elsewhere, a drawing resembles a large insect. Tick marks beneath it may count gnoll losses to unknown bugs.",sp=1}},faq={{q="Who sends you to investigate the Woodpaw gnolls?",a="Hadoken Swiftstrider at Camp Mojache sends you to investigate the Woodpaw gnolls.",al={"who gives woodpaw investigation","quest giver woodpaw investigation"}},{q="Why does Hadoken believe the gnolls have battle plans?",a="The Woodpaw's recent assaults have been too well coordinated to be improvised. Hadoken expects a written strategy that could show what stirred them up.",al={"why do gnolls have plans","woodpaw strategy"}},{q="Where are the battle plans located?",a="The battle plans are in the Woodpaw camps south of Camp Mojache.",al={"where are woodpaw plans","where to find woodpaw battle map"}},{q="What came before Woodpaw Investigation?",a="Alpha Strike comes right before this search.",al={"previous quest woodpaw investigation","woodpaw chain prerequisite"}}},kw={"battle map","battle plans","camp mojache","feralas","gnolls","hadoken swiftstrider","woodpaw"},rel={"subzone:camp-mojache","quest:2903","topic:gnoll","zone:feralas"},m={start="Hadoken Swiftstrider",["end"]="Woodpaw Battle Map",level="43",faction="Horde",id=2902},src={"Classic quest text: Woodpaw Investigation"}}
E["quest:2903"] = {t="quest",n="The Battle Plans",z="feralas",s="You carry the Woodpaw battle plans toward Camp Mojache, where Hadoken Swiftstrider hopes to learn what the gnolls intend.",h="You carry the Woodpaw battle plans toward Camp Mojache, where Hadoken Swiftstrider hopes to learn what the...",sec={{t="Back to Camp Mojache",b="After Woodpaw Investigation, you bring the Woodpaw battle plans back to Hadoken Swiftstrider at Camp Mojache. He needs firm evidence of what the gnolls intend.",sp=0},{t="Hadoken's Reading",b="Hadoken Swiftstrider says the plans are just what they needed. Most of the scrawl is beyond him, but he has read enough battle plans to see the gnolls fight on two fronts. One front is Camp Mojache. Most of their strength is turned against an enemy to the south. Hadoken senses something larger behind the fighting and believes they need to learn who that second enemy is.",sp=1}},faq={{q="Where do these battle plans need to go?",a="Take the plans to Hadoken Swiftstrider at Camp Mojache.",al={"who gets the plans","where to turn in the battle plans","the battle plans turn in"}},{q="What came before this step?",a="Woodpaw Investigation came before this, when you searched for the gnolls' plans.",al={"previous quest","what leads to battle plans","battle plans prerequisite"}},{q="Where did the battle plans come from?",a="The plans belong to the gnolls. You found them in gnoll camps south of Camp Mojache during Woodpaw Investigation.",al={"who made the map","which gnolls made the plans","woodpaw plans origin"}}},kw={"battle plans","camp mojache","feralas","gnolls","hadoken swiftstrider","woodpaw"},rel={"quest:2902","subzone:camp-mojache","zone:feralas","topic:gnoll"},m={start="Woodpaw Battle Map",["end"]="Hadoken Swiftstrider",level="43",id=2903},src={"Classic quest text: The Battle Plans"}}
E["quest:2939"] = {t="quest",n="In Search of Knowledge",z="feralas",s="Troyas Moonbreeze sends you to seek Daryn Lightwind in Rut'theran Village. He found a stave in the rubble of Feralas and wants to learn what it is.",h="Troyas Moonbreeze sends you to seek Daryn Lightwind in Rut'theran Village.",sec={{t="An Ordinary Stave",b="Troyas Moonbreeze says the ruins of Feralas are dangerous, yet they have much to tell of what happened there. A few days ago, he searched the rubble to the south and found a stave that seemed ordinary. Still, he feels there is more to it. He and Angelas searched their books, but found no word of the stave.",sp=0},{t="A Colleague in Darnassus",b="Troyas has a colleague in Darnassus who may know what the stave is. He asks you to speak with Daryn Lightwind in Rut'theran Village.",sp=0},{t="Daryn's Reply",b="Daryn Lightwind grumbles that Troyas keeps pestering her with wild notions about finding something important. She thinks the ogres or harpies now living in the ruins probably carried off anything truly valuable long ago. You are welcome to look around, she says, though she doubts the books there will help.",sp=1}},faq={{q="Who sends you to Daryn Lightwind?",a="Troyas Moonbreeze sends you to Daryn because he wants to learn what the stave he found in the Feralas ruins really is.",al={"who starts in search of knowledge","quest giver"}},{q="What did Troyas find?",a="Troyas found a stave in the rubble to the south of where he works. It seems ordinary, but he feels there is more to it.",al={"what did troyas find","feralas stave"}},{q="Where is Daryn Lightwind?",a="Daryn Lightwind is in Rut'theran Village. Troyas describes her as a colleague in Darnassus.",al={"daryn lightwind location","where is daryn"}},{q="Why does Troyas send you to Daryn?",a="Troyas and Angelas found nothing about the stave in their books. Daryn may be able to tell them what it is.",al={"why visit daryn lightwind","why darnassus"}}},kw={"angelas","darnassus","daryn lightwind","feralas","ruins","rut'theran village","stave","troyas moonbreeze"},rel={"zone:feralas","subzone:rut-theran-village","zone:darnassus"},m={start="Troyas Moonbreeze",["end"]="Daryn Lightwind",level="47",faction="Alliance",id=2939},src={"In Search of Knowledge"}}
E["quest:2942"] = {t="quest",n="The Morrow Stone",z="feralas",s="At the Equinex Monolith, taking the artifact begins to drain the Stave of Equinex. You carry the Sparkling Stone and the stave back to Troyas Moonbreeze at Feathermoon Stronghold.",h="At the Equinex Monolith, taking the artifact begins to drain the Stave of Equinex.",sec={{t="Back to Feathermoon Stronghold",b="The Stave of Equinex begins to lose energy when you take the artifact from the monolith. Troyas Moonbreeze at Feathermoon Stronghold awaits word of what you found. Bring him the Sparkling Stone and the stave.",sp=0},{t="Troyas's Findings",b="After you leave, Troyas studies the stone and names it the Morrow Stone. He does not yet know its purpose, but believes anything hidden inside the monolith as it was must hold great significance. He will continue his studies and hopes you will stand with him.",sp=1}},faq={{q="Where does this begin?",a="It begins at the Equinex Monolith, when you take the artifact from it.",al={"where do I get this quest","where to start morrow stone","equinex monolith start"}},{q="Who do I bring the stone to?",a="Bring the stone to Troyas Moonbreeze at Feathermoon Stronghold, along with the Stave of Equinex.",al={"who turns in morrow stone","where is troyas moonbreeze","who gets the sparkling stone"}},{q="What happens to the Stave of Equinex?",a="The stave's energy begins to fade as soon as you take the artifact from the monolith.",al={"stave of equinex energy","what happens to the staff","why did the stave lose power"}},{q="What comes before this?",a="It follows The Stave of Equinex, where you energized the stave beside the monolith.",al={"previous quest","what quest comes before the morrow stone","prerequisite quest"}}},kw={"equinex monolith","feathermoon stronghold","feralas","morrow stone","sparkling stone","stave of equinex","troyas moonbreeze"},rel={"quest:2879","subzone:feathermoon-stronghold-classic","zone:feralas"},m={start="Equinex Monolith",["end"]="Troyas Moonbreeze",level="50",faction="Alliance",id=2942,ri={"A Sparkling Stone"}},src={"The Morrow Stone"}}
E["quest:2969"] = {t="quest",n="Freedom for All Creatures",z="feralas",s="At the Grimtotem camp, Kindal Moonweaver asks you to free the captured faerie dragons. Neither Kindal nor Jer'kai knows what the Grimtotem clan intends. Kindal will go with you, while Jer'kai stays behind.",h="At the Grimtotem camp, Kindal Moonweaver asks you to free the captured faerie dragons.",sec={{t="Dragons in the Pen",b="Kindal Moonweaver calls the Grimtotem clan filthy for taking faerie dragons. Neither Kindal nor Jer'kai knows what the clan intends, only that it means no good. They are not strong enough to fight into the camp, so Kindal asks you to help free the sprite darters. The Bamboo Cage Key opens their pen, and Kindal wants them to escape alive. Bring strong friends to stand with you.",sp=0},{t="Kindal's Lookout",b="Kindal waits on a ledge behind the Grimtotem Compound, above the water. A path climbs the cliff face to reach him. Kindal fights beside you through the camp. Jer'kai stays behind.",sp=0},{t="Afterward",b="Once the darters are free, Kindal gives thanks to Elune. The freed dragons may not remain free, so Kindal and Jer'kai intend to take the fight to the Grimtotem. Kindal sends you to speak with Jer'kai.",sp=1}},faq={{q="Who is capturing the faerie dragons?",a="Kindal Moonweaver says the Grimtotem clan is capturing the faerie dragons. Kindal and Jer'kai do not know what the clan wants with them.",al={"who captured the faerie dragons","who has the sprite darters","grimtotem cages"}},{q="Where is Kindal Moonweaver?",a="Kindal Moonweaver waits on a ledge behind the Grimtotem Compound, above the water. Go left of the compound to find a path behind a tree that climbs the cliff face.",al={"where is kindal","kindal moonweaver location","how to get to kindal moonweaver"}},{q="Does Jer'kai come along?",a="No. Jer'kai stays behind, while Kindal goes with you.",al={"does jerkai help","jerkai involvement"}},{q="What do I need to free the sprite darters?",a="The Bamboo Cage Key, which Kindal gives you, opens the pen in the Grimtotem camp. Kindal asks you to bring strong friends.",al={"bamboo cage key","how to free sprite darters"}},{q="What follows this quest?",a="Doling Justice comes next in the chain.",al={"next quest freedom for all creatures","what next after saving sprite darters"}}},kw={"bamboo cage","elune","faerie dragon","feralas","grimtotem compound","jer'kai","kindal moonweaver","sprite darter"},rel={"npc:kindal-moonweaver","npc:sprite-darter","subzone:grimtotem-compound","quest:2970","zone:feralas","topic:elune"},m={start="Kindal Moonweaver",["end"]="Kindal Moonweaver",level="47",faction="Alliance",id=2969},src={"Freedom for All Creatures"}}
E["quest:2970"] = {t="quest",n="Doling Justice",z="feralas",s="In Feralas, Jer'kai Moonweaver and Kindal are ready to strike back after the sprite darters' rescue. Jer'kai asks you to thin the Grimtotem ranks, then return to him.",h="In Feralas, Jer'kai Moonweaver and Kindal are ready to strike back after the sprite darters' rescue.",sec={{t="Taking the Fight to the Grimtotem",b="After the sprite darter rescue, Jer'kai Moonweaver and Kindal are ready to strike at the Grimtotem. They can thin the tauren ranks together without much risk, and welcome your help.\n\nYou have seen the camp below, and more lie to the east. Choose your own tactics against Grimtotem Naturalists, Raiders and Shamans, then return to Jer'kai.",sp=0}},faq={{q="Who gives Doling Justice?",a="In Feralas, Jer'kai Moonweaver asks for your help after Kindal has explained what they plan following the sprite darter rescue.",al={"who gives doling justice","quest giver doling justice","jer'kai moonweaver"}},{q="Which Grimtotem are targeted?",a="The targets are Grimtotem Naturalists, Grimtotem Raiders and Grimtotem Shamans among the Grimtotem clan.",al={"what enemies do i kill","doling justice targets","grimtotem kills"}},{q="Where are the Grimtotem camps?",a="One Grimtotem camp lies below Jer'kai, in sight, and she says more camps lie to the east.",al={"where are the grimtotem","grimtotem camp location","where do i go"}},{q="What comes before Doling Justice?",a="Freedom for All Creatures comes first. There, you freed the sprite darters from the Grimtotem camp.",al={"prior quest","doling justice prerequisite","previous step"}}},kw={"doling justice","feralas","grimtotem","jer'kai moonweaver","kindal moonweaver","naturalist","raider","shaman"},rel={"quest:2969","zone:feralas","topic:tauren"},m={start="Jer'kai Moonweaver",["end"]="Jer'kai Moonweaver",level="47",faction="Alliance",id=2970},src={"Doling Justice"}}
E["quest:2972"] = {t="quest",n="Doling Justice",z="feralas",s="In Feralas, Jer'kai Moonweaver sends you to Darnassus with a ring for High Priestess Tyrande Whisperwind. It will show that Jer'kai and Kindal are well and support your account.",h="In Feralas, Jer'kai Moonweaver sends you to Darnassus with a ring for High Priestess Tyrande Whisperwind.",sec={{t="A Ring for the High Priestess",b="Jer'kai Moonweaver and Kindal have little to offer in Feralas, yet they want you to know they are grateful. Jer'kai gives you a signet ring for High Priestess Tyrande Whisperwind at the Temple of the Moon in Darnassus. The ring shows Tyrande that the pair are well and lends weight to your account.",sp=0},{t="Tyrande's Answer",b="High Priestess Tyrande Whisperwind is pleased that you helped dragonkind and one of her priestesses. She says Jer'kai was right to send you and promises the ring will be returned to Jer'kai. Scouts are soon to head toward Feralas, with the ring among the matters they will look into.",sp=1}},faq={{q="Who gives the signet ring?",a="Jer'kai Moonweaver gives you the signet ring in Feralas, with thanks from Kindal as well.",al={"who starts this quest","quest giver"}},{q="Where does the signet ring go?",a="The ring goes to High Priestess Tyrande Whisperwind at the Temple of the Moon in Darnassus.",al={"where do I take the ring","turn in location","who gets jerkai's signet ring"}},{q="Why does Jer'kai give you the ring?",a="Jer'kai and Kindal have little to give in the wilderness. The ring shows Tyrande they are well and supports your account.",al={"purpose of the signet ring","why jerkai signet ring"}},{q="What comes next in the chain?",a="The chain continues with An Orphan Looking For a Home.",al={"next quest","where to go next"}}},kw={"darnassus","feralas","jer'kai moonweaver","kindal moonweaver","signet ring","teldrassil","temple of the moon","tyrande whisperwind"},rel={"npc:tyrande-whisperwind","subzone:temple-of-the-moon","quest:3841","quest:2970","quest:2969","zone:feralas","zone:darnassus"},m={start="Jer'kai Moonweaver",["end"]="Tyrande Whisperwind",level="47",faction="Alliance",id=2972},src={"Doling Justice (2)"}}
E["quest:2973"] = {t="quest",n="A New Cloak's Sheen",z="feralas",s="At Camp Mojache, Krueg Skullsplitter asks you to gather wings for Korrin’s cloak. He came to Feralas with companions sent by their masters in Orgrimmar.",h="At Camp Mojache, Krueg Skullsplitter asks you to gather wings for Korrin’s cloak.",sec={{t="A Cloak for Korrin",b="Krueg Skullsplitter came to Feralas with companions sent by their masters in Orgrimmar. His life-mate Korrin loves new clothes, so he plans a cloak adorned with delicate faerie dragon wings. The sprite darters he seeks live west of Camp Mojache. Bring Krueg ten Iridescent Sprite Darter Wings.",sp=0},{t="Krueg's Warning",b="Krueg warns that provoked sprite darters are dangerous. Nearby night elves tend to hole up in the forests, so take even greater care around them.",sp=0}},faq={{q="Who is Krueg Skullsplitter?",a="Krueg Skullsplitter is at Camp Mojache. He came to Feralas with companions sent by their masters in Orgrimmar.",al={"who is krueg","krueg skullsplitter lore","krueg in feralas"}},{q="Why does Krueg want sprite darter wings?",a="Krueg plans a cloak adorned with faerie dragon wings for his life-mate Korrin, who loves new clothes.",al={"why need darter wings","sprite darter wing purpose","what is krueg making"}},{q="Where are the sprite darters located?",a="The sprite darters live west of Camp Mojache.",al={"where to find sprite darters","sprite darter location","where are faerie dragons in feralas"}},{q="What dangers does Krueg warn about?",a="Sprite darters, which turn dangerous when provoked, and the night elves nearby, who tend to hole up in the forests and call for even greater care.",al={"krueg warnings","threats in the forest feralas"}}},kw={"camp mojache","cloak","faerie dragon","feralas","iridescent wings","korrin","krueg skullsplitter","sprite darter"},rel={"subzone:camp-mojache","npc:sprite-darter","zone:feralas","zone:orgrimmar"},m={start="Krueg Skullsplitter",["end"]="Krueg Skullsplitter",level="45",faction="Horde",id=2973},src={"Classic quest text: A New Cloak's Sheen"}}
E["quest:2974"] = {t="quest",n="A Grim Discovery",z="feralas",s="In Camp Mojache, Krueg Skullsplitter hears that you met tauren in Feralas and names them the Grimtotem. Belgrom has put a bounty on them, and Krueg asks for twenty horns.",h="In Camp Mojache, Krueg Skullsplitter hears that you met tauren in Feralas and names them the Grimtotem.",sec={{t="Word of the Grimtotem",b="You tell Krueg Skullsplitter about the tauren you met in Feralas. He names them as the Grimtotem clan. Belgrom, one of Krueg's masters, has put a bounty on them and takes a keen interest in their kind. Krueg warns you that the Grimtotem are evil and must not be underestimated. He wants twenty horns brought back before they can raze villages or pilfer land.",sp=0},{t="The Horns Delivered",b="Krueg judges the horns good and says you have helped him twice. Belgrom will hear of it as soon as Krueg returns to Orgrimmar.",sp=1}},faq={{q="Who gives A Grim Discovery?",a="Krueg Skullsplitter gives it to you in Camp Mojache after you tell him you met tauren in Feralas.",al={"who gives grim discovery","krueg skullsplitter quest","quest giver grim discovery"}},{q="Why does Krueg want Grimtotem horns?",a="Krueg calls the Grimtotem evil and wants them struck before they can raze villages or pilfer land. Belgrom, one of Krueg's masters in Orgrimmar, has also put a bounty on them.",al={"why kill grimtotem","grimtotem threat feralas","why grimtotem horns"}},{q="Who is Belgrom?",a="Krueg calls Belgrom one of his masters. Belgrom is interested in the Grimtotem and has put a bounty on them.",al={"belgrom orgrimmar","who is belgrom"}},{q="How many horns does Krueg want?",a="Krueg wants twenty Grimtotem horns brought to him in Camp Mojache. He would like piles of them if you can manage.",al={"grimtotem horn count","how many grimtotem horns"}},{q="What follows A Grim Discovery?",a="The chain continues with A Grim Discovery, part two.",al={"next quest grim discovery","grim discovery chain"}}},kw={"belgrom","camp mojache","feralas","grimtotem","horns","krueg skullsplitter"},rel={"subzone:camp-mojache","zone:feralas","topic:tauren","zone:orgrimmar"},m={start="Krueg Skullsplitter",["end"]="Krueg Skullsplitter",level="45",faction="Horde",id=2974,ri={"Grimtotem Horn"}},src={"A Grim Discovery (Classic)"}}
E["quest:2975"] = {t="quest",n="The Ogres of Feralas",z="feralas",s="At Camp Mojache, Rok Orhan calls for the Gordunni to be driven back. Their outpost lies up the river to the north.",h="At Camp Mojache, Rok Orhan calls for the Gordunni to be driven back.",sec={{t="The Mark of the Gordunni",b="Rok Orhan says the Gordunni ogres scar the land around Camp Mojache. Drive the tribe back before it reaches deeper into Feralas. Follow the river north to find their outpost. There, slay ten Gordunni Ogres, ten Gordunni Ogre-Magi and five Gordunni Brutes to show the tribe they are unwelcome.",sp=0}},faq={{q="Who wants the Gordunni ogres driven back?",a="Rok Orhan at Camp Mojache wants the Gordunni ogres driven back.",al={"who gives the quest","quest giver","rok orhan"}},{q="Why does Rok Orhan want the Gordunni pushed back?",a="Rok Orhan says the Gordunni scar the land and must be stopped before they spread farther into Feralas.",al={"why kill the ogres","gordunni motive","why fight gordunni"}},{q="Where is the Gordunni outpost?",a="Follow the river north to find the Gordunni outpost.",al={"ogre outpost location","where are the ogres","gordunni location feralas"}},{q="Which Gordunni must be slain?",a="Slay ten Gordunni Ogres, ten Gordunni Ogre-Magi and five Gordunni Brutes.",al={"how many ogres","gordunni kill count"}},{q="What follows this quest?",a="The chain continues with The Ogres of Feralas two.",al={"next quest ogres of feralas","ogres of feralas chain"}}},kw={"brute","camp mojache","feralas","gordunni","ogre","ogre mage","rok orhan"},rel={"subzone:camp-mojache","zone:feralas"},m={start="Rok Orhan",["end"]="Rok Orhan",level="43",faction="Horde",id=2975},src={"The Ogres of Feralas (1)"}}
E["quest:2976"] = {t="quest",n="A Grim Discovery",z="feralas",s="In Orgrimmar, Belgrom Rockmaul awaits the Grimtotem horns and your account of Feralas. Krueg Skullsplitter says you did the work and deserve the best of the bounty. This follows the first A Grim Discovery.",h="In Orgrimmar, Belgrom Rockmaul awaits the Grimtotem horns and your account of Feralas.",sec={{t="The Crate of Horns",b="Krueg Skullsplitter admits he spoke of a bounty after the first A Grim Discovery. You did the work, so he believes you deserve the best of the payoff. He packs the horns into a crate for you to carry to Belgrom Rockmaul in the Valley of Honor. Belgrom wants to hear what you saw, and Krueg says he will make your hard work worth it.",sp=0},{t="Belgrom's Interest",b="Belgrom Rockmaul is struck by news of the Grimtotem. He asks whether you truly met them while hunting in Feralas. His peers will want to hear the story, so he asks you to tell him more as the coin is counted out. Belgrom thanks you for the information.",sp=1}},faq={{q="Who gives this part of A Grim Discovery?",a="Krueg Skullsplitter gives you the horns in a crate to carry to Belgrom Rockmaul.",al={"who gives a grim discovery","krueg skullsplitter quest","quest giver a grim discovery 2"}},{q="Where does the crate of Grimtotem horns go?",a="The crate of Grimtotem horns goes to Belgrom Rockmaul in the Valley of Honor in Orgrimmar.",al={"where do i take the horns","belgrom rockmaul location","turn in grim discovery 2"}},{q="Why is the bounty yours?",a="Krueg says you did the work, so you deserve the best of the payoff.",al={"why grimtotem horns","bounty grim discovery"}},{q="What does Belgrom want from you?",a="Your report of what you saw. Krueg promises that your hard work will be worth it.",al={"belgrom rockmaul grimtotem","why care about feralas grimtotem"}},{q="What comes before this step?",a="The first A Grim Discovery comes before this part. You brought Krueg Grimtotem horns.",al={"grim discovery chain","prerequisite for grim discovery 2","prior quests"}}},kw={"belgrom rockmaul","bounty","feralas","grimtotem","horns","krueg skullsplitter","orgrimmar","valley of honor"},rel={"quest:2974","zone:feralas","zone:orgrimmar","subzone:valley-of-honor"},m={start="Krueg Skullsplitter",["end"]="Belgrom Rockmaul",level="45",faction="Horde",id=2976},src={"A Grim Discovery (2)"}}
E["quest:2978"] = {t="quest",n="The Gordunni Scroll",z="feralas",s="At the Gordunni Outpost, the Gordunni Scroll may reveal a gathering or ceremony. Rok Orhan at Camp Mojache wants to see it and learn what it means for the Gordunni.",h="At the Gordunni Outpost, the Gordunni Scroll may reveal a gathering or ceremony.",sec={{t="The Soiled Scroll",b="You find a soiled scroll at the Gordunni Outpost. Its image seems to show a gathering or ceremony. Rok Orhan at Camp Mojache wants to see it and learn what it might mean for the Gordunni.",sp=0}},faq={{q="What does the Gordunni Scroll show?",a="The Gordunni Scroll seems to show a meeting or ceremony.",al={"what does the scroll show","gordunni scroll contents","scroll drawing"}},{q="Who wants the Gordunni Scroll?",a="Rok Orhan at Camp Mojache wants to see the Gordunni Scroll.",al={"who wants the scroll","where do i take the scroll","turn in gordunni scroll"}},{q="Where is the Gordunni Scroll found?",a="You find the Gordunni Scroll at the Gordunni Outpost.",al={"where is the gordunni scroll","gordunni scroll location"}},{q="What follows the Gordunni Scroll?",a="Dark Ceremony follows the Gordunni Scroll.",al={"what is the next quest","after the gordunni scroll","gordunni scroll chain"}}},kw={"camp mojache","ceremony","feralas","gordunni outpost","gordunni scroll","ogres","rok orhan"},rel={"quest:2979","subzone:camp-mojache","subzone:gordunni-outpost","zone:feralas","quest:3002"},m={start="Gordunni Scroll",["end"]="Rok Orhan",level="43",faction="Horde",id=2978},src={"The Gordunni Scroll"}}
E["quest:2979"] = {t="quest",n="Dark Ceremony",z="feralas",s="At Camp Mojache, Rok Orhan studies the Gordunni Scroll and seeks an orb from a Gordunni mage-lord. He hopes it will reveal more about the ceremony and the Gordunni's magic.",h="At Camp Mojache, Rok Orhan studies the Gordunni Scroll and seeks an orb from a Gordunni mage-lord.",sec={{t="Plans for a Dark Ceremony",b="Rok Orhan reads the Gordunni Scroll as plans for a dark ceremony. He believes the Gordunni mage-lords conduct it. Find one of them and take his orb. A mage's orb holds great power, and Rok hopes it will teach him more about the ceremony and the magic the Gordunni wield.",sp=0},{t="When the Orb Is Delivered",b="Rok Orhan expects the orb to teach him more about the Gordunni. He will use what he learns to plan their downfall.",sp=1}},faq={{q="Who gives Dark Ceremony?",a="Rok Orhan at Camp Mojache gives it after reading the Gordunni Scroll you brought.",al={"who gives dark ceremony","dark ceremony questgiver"}},{q="Who carries out the dark ceremony?",a="Rok Orhan reads the plans as showing that the Gordunni mage-lords conduct the ceremony.",al={"who is performing the dark ceremony","gordunni ritual leader"}},{q="What orb is Rok Orhan after?",a="Rok Orhan wants an orb taken from one of the Gordunni mage-lords. A mage's orb holds great power, and she expects it to teach her more about the ceremony and the Gordunni's magic.",al={"why get gordunni orb","purpose of gordunni orb"}},{q="What follows Dark Ceremony?",a="The chain continues with The Gordunni Orb.",al={"next quest after dark ceremony","dark ceremony chain"}}},kw={"camp mojache","dark ceremony","feralas","gordunni","gordunni orb","mage-lord","rok orhan"},rel={"quest:2978","quest:3002","subzone:camp-mojache","zone:feralas"},m={start="Rok Orhan",["end"]="Rok Orhan",level="46",faction="Horde",id=2979,ri={"Gordunni Orb"}},src={"Dark Ceremony"}}
E["quest:2980"] = {t="quest",n="The Ogres of Feralas",z="feralas",s="In Feralas, Rok Orhan sends you southwest of Camp Mojache to drive back the Gordunni ogres. You have proved yourself a true fighter, and he trusts you with this work in the High Wilderness.",h="In Feralas, Rok Orhan sends you southwest of Camp Mojache to drive back the Gordunni ogres.",sec={{t="Into the High Wilderness",b="Rok Orhan trusts you with this work because you have proved yourself a true fighter. Southwest of Camp Mojache, the High Wilderness holds abandoned, wrecked structures on ground the night elves once owned.\n\nWithered trees and desecrated ground mark the Gordunni's territory. Rok warns that these ogres are far tougher than the earlier ones. Ten Gordunni Shamans, ten Gordunni Warlocks and five Gordunni Maulers are to fall.",sp=0}},faq={{q="Who sends you to the High Wilderness?",a="Rok Orhan sends you from Camp Mojache.",al={"quest giver","rok orhan","who starts this"}},{q="Where are these Gordunni?",a="The Gordunni are in the High Wilderness, southwest of Camp Mojache, around wrecked structures on ground the night elves once owned. Withered trees and desecrated ground mark the spot.",al={"where are the ogres","high wilderness location","ruins location"}},{q="Which ogres must be killed?",a="Ten Gordunni Shamans, ten Gordunni Warlocks and five Gordunni Maulers must fall.",al={"who do i kill","ogre targets","gordunni types"}},{q="What comes before this step?",a="Before this step, Rok Orhan sent you against the ogres at their outpost to the north.",al={"prerequisite","previous quest","chain order"}}},kw={"camp mojache","feralas","gordunni","high wilderness","maulers","rok orhan","shamans","warlocks"},rel={"quest:2975","subzone:camp-mojache","subzone:high-wilderness","zone:feralas","quest:2982"},m={start="Rok Orhan",["end"]="Rok Orhan",level="44",faction="Horde",id=2980},src={"The Ogres of Feralas (2)"}}
E["quest:2982"] = {t="quest",n="The High Wilderness",z="feralas",s="In Feralas, Angelas Moonbreeze worries as Troyas enters the High Wilderness alone. Gordunni ogres hold that ground, and she hopes you can make the ruins southeast of here safer by culling them.",h="In Feralas, Angelas Moonbreeze worries as Troyas enters the High Wilderness alone.",sec={{t="Worry for Troyas",b="Angelas Moonbreeze and Troyas explore the scattered ruins of Feralas, though the work is dangerous. Lately, Troyas goes to the High Wilderness alone, and Angelas fears for him. Gordunni ogres hold that ground and welcome no one into their territory. So Angelas asks you to make the ruins southeast of here safer for Troyas by culling eight Gordunni Warlocks, eight Gordunni Shamans and eight Gordunni Brutes.",sp=0},{t="Afterward",b="After you finish the work, Angelas thanks you warmly. She asks you to keep it from Troyas.",sp=1}},faq={{q="Who asks you to clear out the High Wilderness?",a="Angelas Moonbreeze asks you to clear the High Wilderness. She explores Feralas's ruins with Troyas.",al={"who is angelas","angelas moonbreeze","who gives the high wilderness quest"}},{q="Why does Angelas want the Gordunni ogres thinned out?",a="Troyas has been going alone to the High Wilderness, and Angelas worries for him. Gordunni ogres hold the area and welcome no visitors.",al={"why kill gordunni","why kill ogres in high wilderness","angelas reason"}},{q="Where is the High Wilderness ruin?",a="Angelas points you to the ruins southeast of here.",al={"where is high wilderness","high wilderness location","ruins to the southeast"}},{q="Which Gordunni must be slain?",a="You are asked to slay eight Gordunni Warlocks, eight Gordunni Shamans and eight Gordunni Brutes.",al={"who do i kill high wilderness","gordunni targets high wilderness"}},{q="What is said about the Gordunni's magic?",a="Angelas warns that Gordunni magic seems to ravage the ground beneath them. She bids you stay watchful around the ogres.",al={"gordunni magic","ogre spells","what magic wreaks havoc"}}},kw={"angelas moonbreeze","feralas","gordunni","gordunni brute","gordunni shaman","gordunni warlock","high wilderness","ogres","troyas"},rel={"subzone:high-wilderness","zone:feralas"},m={start="Angelas Moonbreeze",["end"]="Angelas Moonbreeze",level="44",faction="Alliance",id=2982},src={"The High Wilderness (quest)"}}
E["quest:2987"] = {t="quest",n="Gordunni Cobalt",z="feralas",s="Orwin Gizzmick has come to Feralas seeking cobalt buried by the Gordunni ogres. He asks you to search the Gordunni Outpost, north of Camp Mojache, for twelve samples.",h="Orwin Gizzmick has come to Feralas seeking cobalt buried by the Gordunni ogres.",sec={{t="Buried Minerals",b="New to Feralas, Orwin Gizzmick has heard that the Gordunni ogres bury interesting minerals. They guard the minerals fiercely, keeping them from folk like Orwin. He does not know what they want them for.\n\nOrwin gives you a shovel and points you north of Camp Mojache to the Gordunni Outpost. Follow the blue glow and dig up twelve samples of Gordunni cobalt.",sp=0},{t="When the Cobalt Is Delivered",b="Orwin means to carry the cobalt on his further travels. He is certain someone will pay a pretty penny for it. He gives you something for your trouble.",sp=1}},faq={{q="Who wants Gordunni cobalt?",a="Orwin Gizzmick wants Gordunni cobalt. He has just arrived in Feralas and is at Camp Mojache.",al={"who starts gordunni cobalt","orwin gizzmick quest","who wants cobalt"}},{q="Where is the Gordunni cobalt?",a="The Gordunni cobalt lies buried at the Gordunni Outpost, north of Camp Mojache.",al={"gordunni cobalt location","where to find cobalt feralas","where is gordunni outpost"}},{q="How do you spot the buried cobalt?",a="A blue glow marks where the cobalt is buried. Dig there to find it.",al={"how to spot cobalt","finding cobalt feralas","blue glow ogre dirt"}},{q="Why do the ogres bury their cobalt?",a="Orwin says the ogres bury their cobalt and guard it fiercely to keep folk like him from getting hold of it. He does not know what they want it for.",al={"why is cobalt buried","why do gordunni bury cobalt","ogre cobalt buried"}},{q="How much cobalt does Orwin want?",a="Orwin wants twelve samples, dug up with his shovel.",al={"cobalt count","how many gordunni cobalt"}}},kw={"camp mojache","cobalt","feralas","gizzmick","gordunni","gordunni outpost","ogres","orwin","shovel"},rel={"zone:feralas","subzone:camp-mojache","subzone:gordunni-outpost"},m={start="Orwin Gizzmick",["end"]="Orwin Gizzmick",level="43",faction="Horde",id=2987,ri={"Gordunni Cobalt"}},src={"Gordunni Cobalt (quest)"}}
E["quest:3002"] = {t="quest",n="The Gordunni Orb",z="feralas",s="After Dark Ceremony, Rok Orhan sends you to Orgrimmar with the Gordunni Orb. Uthel'nay at Darkbriar Lodge can judge its power.",h="After Dark Ceremony, Rok Orhan sends you to Orgrimmar with the Gordunni Orb.",sec={{t="Beyond a Warrior's Knowledge",b="After Dark Ceremony, Rok Orhan holds the Gordunni Orb. He knows the Gordunni well, but a warrior cannot judge the orb's power. So he sends you to Orgrimmar with it. There, Uthel'nay at Darkbriar Lodge can tell you more.",sp=0},{t="Uthel'nay's Verdict",b="Uthel'nay finds the Gordunni Orb fascinating. The mage says it is very powerful and very dangerous.",sp=1}},faq={{q="Who sends you to Uthel'nay?",a="After you bring back the orb from Dark Ceremony, Rok Orhan sends you to Uthel'nay.",al={"gordunni orb chain","dark ceremony followup","prerequisites for the gordunni orb"}},{q="Why does Rok Orhan not examine the orb?",a="Rok Orhan knows the Gordunni well, but as a warrior she cannot judge the orb's power. She knows a mage in Orgrimmar who can tell you more.",al={"why send orb to orgrimmar","why rok orhan gives orb away","why uthel'nay"}},{q="Where is Uthel'nay?",a="Uthel'nay is at Darkbriar Lodge in Orgrimmar.",al={"uthel'nay location","where is uthelnay","darkbriar lodge location"}},{q="What comes before The Gordunni Orb?",a="Dark Ceremony comes first. Rok Orhan sent you to take an orb from a Gordunni mage-lord.",al={"gordunni orb prerequisite","gordunni orb previous quest"}}},kw={"darkbriar lodge","feralas","gordunni","gordunni orb","orgrimmar","rok orhan","uthel'nay"},rel={"quest:2979","quest:2978","zone:feralas","zone:orgrimmar"},m={start="Rok Orhan",["end"]="Uthel'nay",level="47",faction="Horde",id=3002},src={"The Gordunni Orb (Classic)"}}
E["quest:3062"] = {t="quest",n="Dark Heart",z="feralas",s="At Camp Mojache, Talo Thornhoof seeks Edana Hatetalon’s heart to end the hatred she spreads.",h="At Camp Mojache, Talo Thornhoof seeks Edana Hatetalon’s heart to end the hatred she spreads.",sec={{t="The Harpy Queen",b="Edana Hatetalon rules the Northspring brood in ruins to the west. Talo calls her pure evil and says she feels nothing but hatred for everyone. He has heard her heart is made of crystal. He asks you to face her and bring back her dark heart, so her hatred can be stopped.",sp=0},{t="A Summons",b="Talo has heard that harpies carry a horn. Sound it near the Hatetalon stones in the northern part of the ruins, and it is said to draw Edana out. Talo relishes the thought that death, rather than her kin, will answer her call.",sp=0},{t="On Your Return",b="Talo Thornhoof is certain Edana Hatetalon is gone for good. He will keep her heart in memory of what you did.",sp=1}},faq={{q="Who is Edana Hatetalon?",a="Edana Hatetalon rules the Northspring harpies in the western ruins. Talo calls her pure evil and says she feels only hatred. He has heard her heart is crystal.",al={"edana hatetalon","harpy queen feralas","who is the harpy queen"}},{q="How can Edana Hatetalon be summoned?",a="Talo has heard that harpies carry a horn. Sound it near the Hatetalon stones in the northern part of the ruins, and it is said to call the queen.",al={"how to summon edana","blow horn feralas","hatetalon stones"}},{q="Who gives the hunt for Edana Hatetalon?",a="Talo Thornhoof at Camp Mojache gives the hunt for Edana Hatetalon.",al={"who gives dark heart","talo thornhoof","where to get dark heart"}},{q="Why does Talo Thornhoof want Edana's heart?",a="Talo wants to stop the hatred Edana spreads over the land. He asks you to bring back her dark heart.",al={"why dark heart","talo thornhoof motive"}}},kw={"camp mojache","dark heart","edana hatetalon","feralas","harpy","hatetalon stones","northspring","talo thornhoof"},rel={"subzone:camp-mojache","zone:feralas","topic:harpy"},m={start="Talo Thornhoof",["end"]="Talo Thornhoof",level="50",faction="Horde",id=3062},src={"Classic quest text: Dark Heart"}}
E["quest:3063"] = {t="quest",n="Vengeance on the Northspring",z="feralas",s="Talo Thornhoof seeks vengeance on the Northspring harpies to the west. Once a hunter who feared no creature, Talo has hated them since they ambushed Talo in the forest.",h="Talo Thornhoof seeks vengeance on the Northspring harpies to the west.",sec={{t="An Old Hunter's Grudge",b="Talo Thornhoof once hunted the wild without fear. After a hard fight, Talo stayed in the forest to hone a weapon. Then harpies closed in, and Talo barely escaped to safety. Their cries still echo in Talo's memory. Talo's life was never the same, and the hatred has endured. Now Talo wants revenge.",sp=0},{t="The Northspring Harpies",b="The Northspring harpies live to the west. Talo asks you to kill four Northspring Harpies, four Northspring Roguefeathers, four Northspring Windcallers and four Northspring Slayers. Their wings are black as night, Talo warns. They can vanish into the darkness.",sp=0},{t="After the Hunt",b="Talo Thornhoof, an old tauren, thanks you for the hunt. Your work has brought peace to a troubled mind.",sp=1}},faq={{q="Who is Talo Thornhoof?",a="Talo Thornhoof once hunted the wild without fear. Harpies ambushed Talo in the forest, and Talo was never the same afterward.",al={"talo thornhoof lore","who gives vengeance on the northspring","talo feralas"}},{q="Where are the Northspring harpies located?",a="The Northspring harpies live to the west of Talo Thornhoof.",al={"northspring harpies location","where are northspring harpies","harpy location feralas"}},{q="Why does Talo want revenge against the harpies?",a="After a hard fight, Talo Thornhoof stayed in the forest to hone a weapon. Harpies surrounded Talo, who barely escaped. Talo was never the same and has carried hatred ever since.",al={"why kill northspring harpies","talo thornhoof backstory","why talo hates harpies"}},{q="Which harpies does Talo want killed?",a="Talo wants four each of the Northspring Harpies, Northspring Roguefeathers, Northspring Windcallers and Northspring Slayers killed.",al={"vengeance on the northspring targets","which harpies to kill","northspring harpy types"}},{q="What do the Northspring harpies look like?",a="Talo says the Northspring harpies have wings black as night and can vanish into the darkness.",al={"harpy appearance","northspring harpy wings"}}},kw={"feralas","harpies","northspring","revenge","roguefeather","slayer","talo thornhoof","windcaller"},rel={"zone:feralas","topic:harpy"},m={start="Talo Thornhoof",["end"]="Talo Thornhoof",level="50",faction="Horde",id=3063},src={"Classic quest text: Vengeance on the Northspring"}}
E["quest:3121"] = {t="quest",n="A Strange Request",z="feralas",s="In Feralas, Witch Doctor Uzer'i sends you to Orgrimmar for a concoction.",h="In Feralas, Witch Doctor Uzer'i sends you to Orgrimmar for a concoction.",sec={{t="A Promised Payment",b="Witch Doctor Uzer'i says Neeru Fireblade in Orgrimmar has a concoction needed to begin work in Feralas. Uzer'i will not yet explain what it is for. You carry a shrunken head, promised to Neeru in exchange for the herbs. It belonged to some poor dwarf Uzer'i came across in the forest. Neeru waits in the Cleft of Shadow.",sp=0},{t="Neeru's Herbs",b="Neeru Fireblade has been waiting for Uzer'i's delivery. In return, Neeru gives you the herb mixture prepared for Uzer'i's experiments.",sp=1}},faq={{q="Who gives A Strange Request?",a="Witch Doctor Uzer'i sends you to Orgrimmar with a shrunken head.",al={"who gives a strange request","who starts this","strange request quest giver"}},{q="Where is Neeru Fireblade?",a="Neeru Fireblade is in the Cleft of Shadow, in Orgrimmar.",al={"where is neeru fireblade","where do i go","shrunken head delivery location"}},{q="Whose head is the shrunken head?",a="Uzer'i says the head belonged to some poor dwarf found in the forest.",al={"whose head is this","shrunken head identity","who was the dwarf"}},{q="Why does Uzer'i send a shrunken head to Neeru?",a="Uzer'i promised the head to Neeru in exchange for the herbs, and needs the concoction Neeru has mixed up.",al={"why does neeru want the head","neeru fireblade trade"}},{q="What follows A Strange Request?",a="The chain continues with Return to Witch Doctor Uzer'i.",al={"what is next","next quest after strange request"}}},kw={"a strange request","cleft of shadow","feralas","neeru fireblade","orgrimmar","shrunken head","witch doctor uzer'i"},rel={"quest:3122","npc:witch-doctor-uzer-i","subzone:cleft-of-shadow","zone:feralas","zone:orgrimmar"},m={start="Witch Doctor Uzer'i",["end"]="Neeru Fireblade",level="45",faction="Horde",id=3121},src={"A Strange Request (Feralas)"}}
E["quest:3123"] = {t="quest",n="Testing the Vessel",z="feralas",s="You return to Witch Doctor Uzer'i, who tests the ritual and your skill. Now you must capture ten wildkin in the Hinterlands and bring them with the vessel back to Feralas.",h="You return to Witch Doctor Uzer'i, who tests the ritual and your skill.",sec={{t="A Vessel for the Hinterlands",b="Witch Doctor Uzer'i tests the ritual you just performed and your own skill. The vessel Uzer'i gives you can shrink a creature and trap it inside. You travel to the Hinterlands to find wildkin. Their kind once belonged to Elune, the night elf goddess, as pets. Uzer'i names the vicious, primitive, savage owlbeasts as your quarry. Capture ten before their spirits slip away, then return with them and the vessel to Uzer'i in Feralas.",sp=0},{t="Afterward",b="Witch Doctor Uzer'i explains what happens when a creature dies violently. Its muisek may escape and hunt for revenge. Shrinking a fallen creature, as you did, keeps the muisek from getting away. Uzer'i now says you may use the vessel at will.",sp=1}},faq={{q="Who gives Testing the Vessel?",a="Witch Doctor Uzer'i gives it to you and hands you the vessel.",al={"quest giver testing the vessel","who gives testing the vessel"}},{q="Where are the wildkin?",a="Uzer'i sends you to the Hinterlands to find wildkin.",al={"where to find wildkin","wildkin location"}},{q="Which creatures are the targets?",a="The targets are wildkin, vicious, primitive or savage owlbeasts. Uzer'i wants ten.",al={"which wildkin to kill","testing the vessel targets"}},{q="What is the link between the wildkin and Elune?",a="Uzer'i says wildkin once belonged to Elune, the night elf goddess, as pets.",al={"wildkin elune lore","why wildkin"}},{q="What can the vessel do?",a="The vessel shrinks a fallen creature and traps it inside, keeping its spirit from getting away.",al={"how does muisek vessel work","vessel power"}},{q="What follows Testing the Vessel?",a="The chain continues with Hippogryph Muisek.",al={"next quest testing the vessel","what comes after testing the vessel"}}},kw={"elune","feralas","hinterlands","muisek","owlbeast","uzer'i","vessel","wildkin"},rel={"npc:witch-doctor-uzer-i","zone:hinterlands","zone:feralas","topic:elune","quest:3122"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="47",faction="Horde",id=3123,ri={"Beast Muisek"}},src={"Testing the Vessel (Classic)"}}
E["quest:3124"] = {t="quest",n="Hippogryph Muisek",z="feralas",s="In the High Wilderness, Frayfeather hippogryphs carry spirits Uzer'i wants you to capture. Their muisek can escape unless you act quickly.",h="In the High Wilderness, Frayfeather hippogryphs carry spirits Uzer'i wants you to capture.",sec={{t="Loyal Companions",b="Witch Doctor Uzer'i trusts you with the vessel and asks you to capture another creature's spirit. Hippogryphs have long been companions to the night elves, and their spirits are loyal and steadfast. You need ten Frayfeather hippogryphs of any kind. Kill each one, then quickly shrink and capture it with the vessel to preserve its muisek. Uzer'i places them in the High Wilderness, south of the camp.",sp=0},{t="Uzer'i's Warning",b="Witch Doctor Uzer'i warns that a slain animal's muisek may escape and take the shape of a greater creature. Then its revenge would bring no peace. The work is dangerous, and Uzer'i says you have done it well again.",sp=1}},faq={{q="Who sends you to capture hippogryphs?",a="Witch Doctor Uzer'i sends you to capture hippogryphs after Testing the Vessel.",al={"hippogryph muisek quest giver","who gives hippogryph muisek","where to get hippogryph muisek"}},{q="Where are the Frayfeather hippogryphs found?",a="Uzer'i places the Frayfeather hippogryphs in the High Wilderness, south of the camp.",al={"where are frayfeather hippogryphs","hippogryph location feralas","where to find hippogryphs in feralas"}},{q="Why does Witch Doctor Uzer'i want hippogryph spirits?",a="Hippogryphs are old companions of the night elves, and Uzer'i says their spirits are loyal and steadfast. He wants their muisek preserved.",al={"why hippogryphs","why capture hippogryph muisek","uzeri hippogryph reasoning"}},{q="How is the muisek captured?",a="Kill a Frayfeather hippogryph, then quickly shrink and capture it with the muisek vessel. Ten are wanted, of any kind.",al={"how to use muisek vessel","how to get hippogryph muisek","capturing frayfeather muisek"}},{q="What step comes before this in the chain?",a="Testing the Vessel comes before this. There, you proved trustworthy and able to use the muisek vessel.",al={"hippogryph muisek prerequisite","previous quest hippogryph muisek","prereq for hippogryph muisek"}}},kw={"feralas","frayfeather","high wilderness","hippogryph muisek","muisek vessel","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","subzone:high-wilderness","zone:feralas","quest:3123"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="47",faction="Horde",id=3124,ri={"Hippogryph Muisek"}},src={"Hippogryph Muisek (Classic)"}}
E["quest:3125"] = {t="quest",n="Faerie Dragon Muisek",z="feralas",s="West of Witch Doctor Uzer'i, the Horde seeks the spirits of faerie dragons. Sprite darters and sprite dragons bear the strength Uzer'i hopes to capture.",h="West of Witch Doctor Uzer'i, the Horde seeks the spirits of faerie dragons.",sec={{t="Fragile Looks, Strong Spirit",b="Witch Doctor Uzer'i sees strength in faerie dragons, though they look delicate. They have long been allies to the night elves, and Uzer'i wants the Horde to share their power. Uzer'i gives you a Muisek Vessel and sends you west. Slay eight sprite darters or sprite dragons, then use the vessel on each fallen faerie dragon to shrink and capture its spirit.",sp=0},{t="Back at Uzer'i's Side",b="When you return with the captured spirits, Witch Doctor Uzer'i thanks you. The Horde can now draw on the faerie dragons' spiritual power. Uzer'i hopes you will agree to one more job.",sp=1}},faq={{q="Why does Witch Doctor Uzer'i want faerie dragon spirits?",a="Uzer'i says faerie dragons look fragile but hold a powerful spirit. They have long been allies to the night elves, and Uzer'i wants the Horde to benefit from their strength too.",al={"why faerie dragons","faerie dragon muisek purpose","why kill sprite darters"}},{q="Where can the faerie dragons be found?",a="The faerie dragons lie west of Witch Doctor Uzer'i.",al={"where are sprite darters","sprite darter location","faerie dragon location feralas"}},{q="What creatures provide this muisek?",a="Sprite darters and sprite dragons provide the muisek. You need to kill and capture eight of them.",al={"which mobs for muisek","what do i kill for faerie dragon muisek","faerie dragon muisek targets"}},{q="What must be done to the fallen creatures?",a="Use the Muisek Vessel on each fallen faerie dragon to shrink it and capture its muisek.",al={"how to get faerie dragon muisek","how does muisek vessel work","capturing muisek"}},{q="Where does this step fit among Uzer'i's requests?",a="This step follows Hippogryph Muisek. Treant Muisek follows it.",al={"what quest comes before this","muisek chain order","what is next after faerie dragon muisek"}}},kw={"faerie dragon muisek","feralas","hippogryph muisek","horde","muisek vessel","sprite darter","sprite dragon","treant muisek","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","quest:3126","npc:sprite-darter","topic:horde","zone:feralas"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="45",faction="Horde",id=3125},src={"Classic quest text: Faerie Dragon Muisek"}}
E["quest:3126"] = {t="quest",n="Treant Muisek",z="feralas",s="In Feralas, Witch Doctor Uzer'i turns your search to the wandering treants. After the faerie dragons, he sends you to find three forest walkers.",h="In Feralas, Witch Doctor Uzer'i turns your search to the wandering treants.",sec={{t="Slow Protectors",b="The night elves have made treants their allies against the Horde. Uzer'i says they move slowly, yet none can deny their strength as protectors. He means to put that strength to work for the Horde.",sp=0},{t="Three Forest Walkers",b="Uzer'i asks you to find and kill three wandering forest walkers. When each treant falls, use the Muisek Vessel to shrink and capture it.",sp=0},{t="Uzer'i's Verdict",b="When you return, Witch Doctor Uzer'i thanks you. He says the collection of muisek is nearly complete.",sp=1}},faq={{q="Who sends adventurers after the treants?",a="Witch Doctor Uzer'i sends you after the treants, following the faerie dragons.",al={"who gives treant muisek","treant muisek quest giver","uzeri treant quest"}},{q="Why does Witch Doctor Uzer'i want treant muisek?",a="The night elves have made treants their allies against the Horde. Uzer'i wants their protective power put to work for the Horde.",al={"why kill forest walkers","why treant muisek","uzeri treant motive"}},{q="What creatures must be found for Treant Muisek?",a="You need to find three wandering forest walkers roaming the forest.",al={"which treants to kill","wandering forest walkers","treant muisek targets"}},{q="How are the treants captured?",a="When a wandering forest walker falls, use the Muisek Vessel to shrink and capture it.",al={"how to use muisek vessel","capturing forest walkers","shrink treants"}},{q="Where does Treant Muisek fit among Uzer'i's requests?",a="Treant Muisek follows Faerie Dragon Muisek. Mountain Giant Muisek comes next.",al={"treant muisek chain","what comes after faerie dragon muisek","next quest after treant muisek"}}},kw={"feralas","muisek vessel","treant muisek","treants","uzer'i","wandering forest walker"},rel={"npc:witch-doctor-uzer-i","quest:3125","quest:3127","zone:feralas","topic:horde"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="50",faction="Horde",id=3126},src={"Classic quest text: Treant Muisek"}}
E["quest:3127"] = {t="quest",n="Mountain Giant Muisek",z="feralas",s="Northwest across Feralas, you face the last creatures Witch Doctor Uzer'i hopes to harness: mountain giants.",h="Northwest across Feralas, you face the last creatures Witch Doctor Uzer'i hopes to harness: mountain giants.",sec={{t="Giants of the Rocky Ground",b="Witch Doctor Uzer'i says mountain giants came down from the mountains to aid the night elves when the Burning Legion first arrived in the world. Their immense size marks them, and rocky ground trembles beneath their steps. Uzer'i hopes to harness power on that scale.\n\nSeven Land Walkers or Cliff Giants must fall. Then the Muisek Vessel can shrink and capture them.",sp=0},{t="Uzer'i's Boast",b="When you return, Witch Doctor Uzer'i speaks of what the gathered materials make possible. Uzer'i claims they can trap the creatures' spirits forever in whatever Uzer'i wishes.",sp=1}},faq={{q="Who asks for the mountain giants' muisek?",a="Witch Doctor Uzer'i asks for the mountain giants' muisek. Uzer'i calls it your last request.",al={"quest giver","who gives mountain giant muisek","uzeri quest"}},{q="Where are the mountain giants located?",a="Uzer'i sends you northwest across Feralas, where the mountain giants roam rocky terrain.",al={"mountain giant location","where are land walkers","cliff giant location"}},{q="Why are mountain giants here?",a="By Uzer'i's account, the mountain giants came down from the mountains to aid the night elves when the Burning Legion first arrived in the world.",al={"why are giants here","mountain giant lore feralas"}},{q="Which creatures provide the required muisek?",a="Land Walkers and Cliff Giants provide the muisek. Seven are needed, and the Muisek Vessel shrinks and captures each fallen giant.",al={"what do i kill for muisek","which giants count"}},{q="What comes before this in the sequence?",a="Treant Muisek comes before this, and Weapons of Spirit is listed after it.",al={"previous quest","muisek chain order"}}},kw={"burning legion","cliff giant","feralas","land walker","mountain giant muisek","muisek vessel","treant muisek","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","quest:3126","quest:3129","zone:feralas","topic:burning-legion"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="50",faction="Horde",id=3127},src={"Classic quest text: Mountain Giant Muisek"}}
E["quest:3128"] = {t="quest",n="Natural Materials",z="feralas",s="In Camp Mojache, Natural Materials are needed by Witch Doctor Uzer'i for an endeavor. The materials come from treants, mountain giants, faerie dragons, owlbeasts and hippogryphs, alongside the other trials.",h="In Camp Mojache, Natural Materials are needed by Witch Doctor Uzer'i for an endeavor.",sec={{t="Gathering for the Witch Doctor",b="After you return to Witch Doctor Uzer'i, another list of materials awaits alongside the other trials. Bring two splintered logs from a Feralas treant. Mountain giants and faerie dragons westward carry six pieces of encrusted minerals. Owlbeasts in the Hinterlands or hippogryphs in Feralas provide twenty pieces of resilient sinew. Any of these creatures can yield the forty metallic fragments needed.",sp=0},{t="Uzer'i's Verdict",b="Witch Doctor Uzer'i is pleased when you bring back the materials. Joined with the muisek, they should bring the results he has wanted.",sp=1}},faq={{q="Who requests these natural materials?",a="Witch Doctor Uzer'i in Camp Mojache requests them.",al={"who gives natural materials","natural materials quest giver","where to start natural materials"}},{q="What creatures hold the splintered logs?",a="A Feralas treant provides the two splintered logs you need.",al={"where to get splintered logs","who drops splintered log","splintered log source"}},{q="Where can encrusted minerals be gathered?",a="Mountain giants and faerie dragons westward carry the six encrusted minerals you need.",al={"how to get encrusted minerals","encrusted minerals source","who drops encrusted minerals"}},{q="Which beasts provide the resilient sinew?",a="Owlbeasts in the Hinterlands or hippogryphs in Feralas provide the twenty pieces of resilient sinew you need.",al={"resilient sinew drop","where to find resilient sinew","who has resilient sinew"}},{q="Where do metallic fragments come from?",a="The forty metallic fragments can come from treants, mountain giants, faerie dragons, owlbeasts or hippogryphs.",al={"metallic fragments source","how to get metallic fragments","who drops metallic fragments"}},{q="What came before this request?",a="This request follows Return to Witch Doctor Uzer'i.",al={"natural materials prerequisite","previous quest natural materials","what leads to natural materials"}}},kw={"camp mojache","encrusted minerals","feralas","metallic fragments","muisek","natural materials","resilient sinew","splintered log","the hinterlands","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","subzone:camp-mojache","zone:feralas","quest:3122","zone:hinterlands"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="50",faction="Horde",id=3128},src={"Natural Materials"}}
E["quest:3129"] = {t="quest",n="Weapons of Spirit",z="feralas",s="Witch Doctor Uzer'i is preparing weapons for you in Feralas. The work takes time, so you wait while the spirits are bound.",h="Witch Doctor Uzer'i is preparing weapons for you in Feralas.",sec={{t="A Moment's Patience",b="Witch Doctor Uzer'i has the materials and the spirits you captured. Imbuing weapons with muisek takes hard work, so Uzer'i asks you to wait while the weapons are prepared.",sp=0},{t="When the Wait Ends",b="Witch Doctor Uzer'i returns with weapons for you to choose from. The captured creatures' spirits are sealed inside for good, and you can wield their energy as your own.",sp=1}},faq={{q="Who is behind Weapons of Spirit?",a="Witch Doctor Uzer'i sent you to gather muisek. This follows Mountain Giant Muisek.",al={"who gives weapons of spirit","weapons of spirit quest giver","uzeri quest"}},{q="What does Witch Doctor Uzer'i do during this step?",a="Uzer'i works to bind the captured muisek into weapons. The work is difficult, so Uzer'i asks you to wait while the weapons are prepared.",al={"what happens in weapons of spirit","what does uzeri do"}},{q="What is needed before Uzer'i can begin?",a="Uzer'i has the needed materials and the spirits you captured, so the work can begin.",al={"requirements for weapons of spirit","prerequisites for weapons of spirit"}}},kw={"feralas","muisek","spirit weapons","weapons of spirit","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","quest:3127","zone:feralas"},m={start="Witch Doctor Uzer'i",["end"]="Witch Doctor Uzer'i",level="50",faction="Horde",id=3129},src={"Classic quest text: Weapons of Spirit"}}
E["quest:3130"] = {t="quest",n="Against the Hatecrest",z="feralas",s="In Feathermoon Stronghold, Shandris sends you to Latronicus as she weighs the naga threat.",h="In Feathermoon Stronghold, Shandris sends you to Latronicus as she weighs the naga threat.",sec={{t="Shandris Weighs the Risk",b="General Shandris Feathermoon sends you to Latronicus Moonspear, her second. He has watched the naga forces closely, and Shandris must judge the wider danger they pose.\n\nShe would like to commit a full force against them. But then Feathermoon Stronghold would be open to a direct attack from the Horde, or something worse. Latronicus awaits you in the stronghold.",sp=0},{t="What Latronicus Intends",b="Latronicus Moonspear says General Shandris charged him with confronting the naga directly. His plan has two parts: weaken their numbers and their command, then learn what they are doing in the ruins.\n\nWith your help, the naga can be countered while Feathermoon Stronghold stays secure.",sp=1}},faq={{q="Why does Shandris Feathermoon send you to Latronicus?",a="Shandris will not commit a full force against the naga if it leaves Feathermoon Stronghold open to the Horde, or something worse. She sends you to Latronicus, her second, who has been watching the naga.",al={"why talk to latronicus","why latronicus moonspear","feathermoon referral"}},{q="Where is Latronicus Moonspear located?",a="Latronicus Moonspear is in Feathermoon Stronghold, where Shandris sends you to report to him.",al={"latronicus location","where is latronicus","find latronicus moonspear"}},{q="What came before this assignment?",a="You return to Feathermoon Stronghold, and Shandris sends you on to Latronicus.",al={"against the hatecrest prerequisite","previous quest","hatecrest chain start"}}},kw={"against the hatecrest","feathermoon stronghold","feralas","hatecrest","horde","latronicus moonspear","naga","shandris feathermoon"},rel={"npc:shandris-feathermoon","subzone:feathermoon-stronghold-classic","quest:2867","quest:2869","topic:naga","topic:horde","zone:feralas"},m={start="Shandris Feathermoon",["end"]="Latronicus Moonspear",level="43",faction="Alliance",id=3130},src={"Against the Hatecrest"}}
E["quest:3445"] = {t="quest",n="The Sunken Temple",z="feralas",s="Angelas Moonbreeze points you toward a buried place and a missing scholar. Far below the earth, the Sunken Temple lies beyond any power Angelas has seen. To learn more, seek Marvon Rivetseeker, last known to be in Tanaris.",h="Angelas Moonbreeze points you toward a buried place and a missing scholar.",sec={{t="A Place Banished Below",b="Angelas Moonbreeze tells you that the Sunken Temple was driven deep beneath the earth by forces beyond anything she has seen. She sends you to Marvon Rivetseeker, a goblin who studies ancient sites with her and Troyas.\n\nMarvon left his home in Ratchet to investigate the troll ruins of Tanaris. No word of him has come for some time.",sp=0},{t="What Marvon Says",b="Marvon Rivetseeker says he has seen the Sunken Temple with his own eyes. He takes you for someone eager to travel and offers to share more, with knowledge he believes will intrigue you.",sp=1}},faq={{q="Who starts the search for the Sunken Temple?",a="Angelas Moonbreeze points you toward the Sunken Temple, sunk deep beneath the earth by forces mightier than any she has seen.",al={"sunken temple quest giver","who gives the sunken temple","angelas moonbreeze"}},{q="Who is Marvon Rivetseeker?",a="Marvon Rivetseeker is a goblin who studies ancient sites across the world with Angelas and Troyas.",al={"marvon rivetseeker","where is marvon rivetseeker","who is marvon"}},{q="Where did Marvon Rivetseeker go?",a="Marvon Rivetseeker left his home in Ratchet to investigate the troll ruins of Tanaris. No word of him has come for some time.",al={"marvon location","where to find marvon","marvon tanaris"}}},kw={"angelas moonbreeze","feralas","marvon rivetseeker","ratchet","sunken temple","tanaris","troll ruins"},rel={"quest:3444","zone:feralas","zone:tanaris","subzone:ratchet"},m={start="Angelas Moonbreeze",["end"]="Marvon Rivetseeker",level="51",faction="Alliance",id=3445},src={"The Sunken Temple (Alliance)"}}
E["quest:3567"] = {t="quest",n="To the Top",z="feralas",s="Marli Wishrunner offers you a view from one of Feralas's twin colossals, with one warning: the way up is one way.",h="Marli Wishrunner offers you a view from one of Feralas's twin colossals, with one warning: the way up is one...",sec={{t="One Way Up",b="Marli Wishrunner can send you to the top of one of Feralas's twin colossals for a view. She warns you to think about how you will get down. The journey goes only one way.",sp=0}},faq={{q="Who can send you to the top of a colossal?",a="Marli Wishrunner, who can send you up one of Feralas's twin colossals to take in the view.",al={"who gives to the top","to the top quest giver","marli wishrunner"}},{q="Where does this journey lead?",a="You reach the top of one of the twin colossals.",al={"where does marli send you","destination","to the top location"}},{q="Does Marli provide a way back down?",a="No. Marli warns that the journey goes only one way, so think about how you will get down.",al={"how do i get down","is there a return trip","way down from twin colossals"}}},kw={"colossals","feralas","marli wishrunner","summit","to the top","twin colossals"},rel={"subzone:twin-colossals","zone:feralas"},m={start="Marli Wishrunner",["end"]="Marli Wishrunner",level="25",id=3567},src={"To the Top"}}
E["quest:3841"] = {t="quest",n="An Orphan Looking For a Home",z="feralas",s="Kindal Moonweaver has news for you after Darnassus: the nest was saved, but its mother died. The eggs will soon hatch, and Kindal offers you one to care for. Quentin waits by the race tracks in the Shimmering Flats of Thousand Needles.",h="Kindal Moonweaver has news for you after Darnassus: the nest was saved, but its mother died.",sec={{t="A Nest Without a Mother",b="Kindal Moonweaver greets you after your return from Darnassus. The nest was saved, but its mother died before help could reach her. The eggs are close to hatching, and they need a good keeper. Kindal offers you one as a pet. Carry the egg to Quentin at the race tracks in the Shimmering Flats if you want to care for it. Quentin can tell you more.",sp=0},{t="Quentin at the Flats",b="Quentin waits in Thousand Needles, though the races are not why he is there. He studies whether new, fertile soil can restore the land. He hopes to find a water source nearby. The change from Feralas to Thousand Needles seems strange to him. Quentin says strange magic was at work when it happened.",sp=0},{t="What Quentin Makes of the Egg",b="Quentin identifies the egg as a sprite darter egg, nearly mature and in remarkably good condition. He is amazed you found one. Sprite darters are rarely seen in Feralas these days, and Quentin has heard that poachers hunt them to capture or kill them for various reasons. He thinks that is a shame. Grown sprite darters are beautiful. How did you come across such a find?",sp=1}},faq={{q="Where did the egg come from?",a="While you were in Darnassus, Kindal Moonweaver and others saved a nest full of eggs. The mother died before they could reach her.",al={"where did the egg come from","egg origin","sprite darter egg lore"}},{q="Where can Quentin be found?",a="At the race tracks in the Shimmering Flats of Thousand Needles.",al={"quentin location","where is quentin","quentin shimmering flats"}},{q="Why is Quentin at the Shimmering Flats?",a="Quentin studies whether new, fertile soil can restore the land and hopes to find a nearby water source. He is not there for the races.",al={"why is quentin at the raceway","what is quentin doing","quentin research"}}},kw={"egg","feralas","kindal moonweaver","quentin","shimmering flats","sprite darter","thousand needles"},rel={"npc:kindal-moonweaver","quest:3842","npc:sprite-darter","subzone:shimmering-flats","zone:feralas","zone:thousandneedles","quest:2972","zone:darnassus"},m={start="Kindal Moonweaver",["end"]="Quentin",level="47",faction="Alliance",id=3841},src={"An Orphan Looking For a Home"}}
E["quest:4041"] = {t="quest",n="The Videre Elixir",z="feralas",s="Bring Gregan Brewspewer an Evoroot, and he can brew the Videre Elixir. He boasts of his knowledge of herbs and alchemy.",h="Bring Gregan Brewspewer an Evoroot, and he can brew the Videre Elixir.",sec={{t="An Evoroot for the Brewer",b="Gregan Brewspewer needs an Evoroot before he can brew your Videre Elixir. He boasts that he knows a great many things about herbs and alchemy, then begins a tale about turning the cheese meant for lunch into gold. When you walk away, he asks where you are going. Ask Gregan where to find an Evoroot.",sp=0},{t="When the Evoroot Arrives",b="When you return with the Evoroot, Gregan greets you with a claim: you pulled a fast one on old Miblon.",sp=1}},faq={{q="Who brews the Videre Elixir?",a="Gregan Brewspewer can brew the Videre Elixir once you bring him an Evoroot.",al={"who gives the videre elixir","where do i get videre elixir"}},{q="What ingredient is required to make the elixir?",a="Gregan needs an Evoroot to make the elixir. Ask him where to find one.",al={"videre elixir ingredients","what does gregan need"}},{q="What does Gregan Brewspewer boast about?",a="Gregan boasts that he knows a great many things about herbs and alchemy. He begins a tale about turning a lunchtime cheese into gold.",al={"gregan brewspewer boasts","gregan herbs and alchemy"}}},kw={"alchemy","evoroot","feralas","gregan brewspewer","miblon","videre elixir"},rel={"zone:feralas"},m={start="Gregan Brewspewer",["end"]="Gregan Brewspewer",level="52",id=4041},src={"The Videre Elixir (2)"}}
E["quest:4120"] = {t="quest",n="The Strength of Corruption",z="feralas",s="At Camp Mojache, Talo Thornhoof sends you north to Felwood to judge the strength of its tainted beasts.",h="At Camp Mojache, Talo Thornhoof sends you north to Felwood to judge the strength of its tainted beasts.",sec={{t="Know Your Enemy",b="Talo Thornhoof hunts by studying the strengths of his foes. He believes knowing an enemy can turn a battle in your favor. Felwood lies north of Ashenvale, where fel has tainted the creatures. Talo fears its maddened bears and wolves have grown stronger. Face twelve Angerclaw grizzlies and twelve Felpaw ravagers there. Fel-touched creatures glow a strange green. Talo senses that fel is evil, yet very powerful.",sp=0},{t="What Talo Hears",b="After hearing your account, Talo finds mindless ferocity in the beasts. He warns you to stay alert and learn more about the corruption. An enemy should always be known.",sp=1}},faq={{q="Who sends you to Felwood?",a="Talo Thornhoof, a hunter at Camp Mojache in Feralas, sends you to Felwood.",al={"quest giver","who gives the strength of corruption","talo thornhoof location"}},{q="Why does Talo Thornhoof want the beasts of Felwood faced?",a="Talo believes knowing an enemy can turn a battle, and wants you to learn whether Felwood's fel-tainted creatures are as strong as believed.",al={"why kill the bears and wolves","purpose of the strength of corruption","talo thornhoof motive"}},{q="Which creatures are targeted in Felwood?",a="You face twelve Angerclaw grizzlies and twelve Felpaw ravagers in Felwood.",al={"which beasts","targets in felwood","what monsters to fight"}},{q="What does Talo say about fel?",a="Talo senses that fel is evil but very powerful, and the creatures it touches glow a strange green.",al={"what is the taint","green glow felwood","what is fel"}}},kw={"angerclaw grizzly","camp mojache","fel corruption","felpaw ravager","felwood","feralas","talo thornhoof"},rel={"subzone:camp-mojache","zone:feralas","zone:felwood","zone:ashenvale"},m={start="Talo Thornhoof",["end"]="Talo Thornhoof",level="52",faction="Horde",id=4120},src={"The Strength of Corruption"}}
E["quest:4124"] = {t="quest",n="The Missing Courier",z="feralas",s="In Feathermoon Stronghold, Latronicus Moonspear seeks help after a courier vanishes. The courier and his parcels have been gone about a week, and the stronghold's searches found nothing. Latronicus has declared him missing in action and sends you to Ginro Hearthkindle.",h="In Feathermoon Stronghold, Latronicus Moonspear seeks help after a courier vanishes.",sec={{t="A Courier Gone Missing",b="Latronicus Moonspear has exhausted the stronghold's search for a courier and his parcels. Both have been missing for about a week, and Latronicus has declared the courier missing in action.\n\nGinro Hearthkindle, Latronicus's associate, is looking for help in Feathermoon Stronghold, perhaps in his quarters. Latronicus asks you to speak with Ginro if you have time and means to spare.",sp=0},{t="Ginro's Weary Search",b="Ginro Hearthkindle knows Latronicus Moonspear sent you, though Ginro calls him Latro. The search seems a lost cause to Ginro, but he accepts whatever help is offered and longs to put the matter to rest.\n\nEach day, Ginro searches Feralas for signs of Raschal. Each night, he returns with only gnoll teeth and disappointment.",sp=1}},faq={{q="Who has gone missing?",a="A courier and the parcels he carried have been missing for about a week. Feathermoon Stronghold's searches found nothing, and the courier has been declared missing in action.",al={"who is the courier","who went missing","missing courier name"}},{q="Where can Ginro Hearthkindle be found?",a="Ginro Hearthkindle is in Feathermoon Stronghold, perhaps in his quarters.",al={"ginro hearthkindle location","where is ginro","find ginro"}},{q="Who starts the search for the courier?",a="Latronicus Moonspear, in Feathermoon Stronghold, sends you to Ginro Hearthkindle for help.",al={"who gives the missing courier","latronicus moonspear quest","who starts missing courier"}}},kw={"courier","feathermoon stronghold","feralas","ginro hearthkindle","gnolls","latronicus moonspear","parcels","raschal"},rel={"subzone:feathermoon-stronghold-classic","zone:feralas","topic:gnoll"},m={start="Latronicus Moonspear",["end"]="Ginro Hearthkindle",level="43",faction="Alliance",id=4124},src={"The Missing Courier"}}
E["quest:4125"] = {t="quest",n="The Missing Courier",z="feralas",s="Ginro Hearthkindle searches Feralas's coast for Raschal, missing for about a week. Raschal set out for Thalanaar, planning to row down the coast. Ginro could not find the boat and asks you to search the shore for a clue.",h="Ginro Hearthkindle searches Feralas's coast for Raschal, missing for about a week.",sec={{t="A Route Down the Coast",b="Ginro Hearthkindle believes Raschal planned to row down the coast toward Thalanaar. Raschal set out about a week ago and knows Feralas well. Raschal has served with the expeditionary forces since General Feathermoon led them here.\n\nThe route crosses southern Feralas, away from the Horde camp. Ginro could not find the boat, so it may be hidden or sunk. It could hold a clue to Raschal's whereabouts. On the mainland, the Forgotten Coast runs south from the jetty.",sp=0},{t="At the Shore",b="Through muddy water, a wrecked row boat lies riddled with gaping holes along one side. It is shredded nearly to its wooden frame. Whatever struck the boat seems to have tried to split it in half.\n\nA small crest of Feathermoon Stronghold is painted on the other side. In the mud at the boat's base, something metallic glints.",sp=1}},faq={{q="Who is Raschal?",a="Raschal is the missing courier. Raschal knows Feralas well and has served with the expeditionary forces since General Feathermoon led them here.",al={"who is raschal","missing courier identity","who went missing"}},{q="Where was Raschal heading?",a="Raschal was heading to Thalanaar. The plan was to row down the coast, then cross southern Feralas to avoid the Horde camp.",al={"raschal destination","where was he going","courier route"}},{q="How long has Raschal been missing?",a="Raschal has been missing about a week, since setting out for Thalanaar.",al={"when did raschal leave","how long gone"}},{q="Where did this search begin?",a="You began the search after speaking with Ginro Hearthkindle about the missing courier.",al={"previous step","how did this quest start"}}},kw={"feathermoon stronghold","feralas","forgotten coast","ginro hearthkindle","raschal","rowboat","thalanaar"},rel={"quest:4124","quest:4127","subzone:feathermoon-stronghold-classic","subzone:forgotten-coast","subzone:thalanaar","zone:feralas","topic:horde"},m={start="Ginro Hearthkindle",["end"]="Wrecked Row Boat",level="43",faction="Alliance",id=4125},src={"The Missing Courier (2)"}}
E["quest:4127"] = {t="quest",n="Boat Wreckage",z="feralas",s="Off the coast, Boat Wreckage holds a clue for Ginro Hearthkindle in Feathermoon Stronghold. A well-cared-for knife lies in the mud, and you sense something else in the water.",h="Off the coast, Boat Wreckage holds a clue for Ginro Hearthkindle in Feathermoon Stronghold.",sec={{t="A Knife in the Mud",b="Near the wrecked boat, you feel through the mud and find a well-cared-for knife. Whoever was aboard may have lost it when the large chunk went missing from the boat. You take the knife to Ginro Hearthkindle in Feathermoon Stronghold. Ginro asked you to bring back any clue you found, yet something else still shares the water.",sp=0},{t="A Question for You",b="Ginro believes the knife belonged to Raschal and asks if you found it on the bottom beside his boat. The knife alone may not link the boat to Raschal's disappearance. Ginro has another way to learn more: psychometry. Have you heard of it?",sp=1}},faq={{q="Where is the knife discovered?",a="The knife lies in the mud beside the wrecked row boat, in the water off the coast.",al={"knife location","where is discarded knife","where do i find the knife"}},{q="Who wants the clue brought back?",a="Ginro Hearthkindle in Feathermoon Stronghold asked you to bring back any clue you found.",al={"who sent me to boat","who wants the knife","boat wreckage turn in"}},{q="What sort of knife is it?",a="The knife is well cared for and lies in the mud beside the wrecked boat. Whoever was aboard may have lost it.",al={"who owns the knife","whose blade is it"}},{q="What comes directly before investigating the wreckage?",a="It follows the second part of The Missing Courier, when you were asked to find the courier's boat.",al={"previous quest","what led to boat wreckage"}}},kw={"boat wreckage","discarded knife","feathermoon stronghold","feralas","ginro hearthkindle","missing courier","raschal","row boat"},rel={"quest:4125","quest:4129","subzone:feathermoon-stronghold-classic","zone:feralas"},m={start="Wrecked Row Boat",["end"]="Ginro Hearthkindle",level="44",faction="Alliance",id=4127},src={"Boat Wreckage"}}
E["quest:4129"] = {t="quest",n="The Knife Revealed",z="feralas",s="Ginro Hearthkindle sends you to Quintis Jonespyre with the knife, seeking a reading of its past. Ginro says the reading will settle Quintis's Kalimdor Hold 'Em debt.",h="Ginro Hearthkindle sends you to Quintis Jonespyre with the knife, seeking a reading of its past.",sec={{t="A Druid's Debt",b="After Boat Wreckage, Ginro Hearthkindle sends you to Quintis Jonespyre with the knife. Quintis is Feathermoon Stronghold's resident druid, and he lives in a little tree-house there.\n\nBy touching an object, Quintis can learn its past. Ginro calls this psychometry magic he does not understand and chooses not to understand, though he has seen it work. Quintis owes Ginro a Kalimdor Hold 'Em debt, and Ginro says the knife's reading will clear it.",sp=0},{t="King of the Bad Beats",b="Quintis says psychometric readings drain the psyche, much like losses at Kalimdor Hold 'Em. The Stronghold calls him the King of the Bad Beats. He is unlucky at cards, yet lucky with nature's secrets.\n\nQuintis agrees to read the knife. He hopes it will bring the breakthrough needed to uncover Raschal's fate.",sp=0},{t="Before the Reading",b="Quintis thanks you and says psychometry is no exact art. He has used it to shed light on situations others had written off as lost causes. The knife may offer a glimpse of what happened to Raschal.\n\nThe reading takes only a moment, though it is hard going for a caster. Quintis asks you to bear with him.",sp=1}},faq={{q="Who is Quintis Jonespyre?",a="Quintis Jonespyre is Feathermoon Stronghold's resident druid. He lives in a little tree-house there and can learn an object's past by touching it.",al={"quintis","who is quint","druid in feathermoon"}},{q="What is psychometry?",a="Psychometry is the art of learning an object's past by touching it. Quintis says its readings drain the psyche.",al={"how does psychometry work","reading the knife","quintis psychometry"}},{q="Why does Quintis help with the knife?",a="Quintis owes Ginro Hearthkindle a Kalimdor Hold 'Em debt, and Ginro says a reading of the knife will clear it. Quintis also hopes it will help uncover Raschal's fate.",al={"why help quintis","ginro debt","kalimdor hold em"}},{q="Where does this happen in the investigation?",a="The investigation reaches this point after Boat Wreckage, where the knife was found.",al={"what quest is before this","what quest comes next","knife revealed chain"}}},kw={"discarded knife","feathermoon stronghold","ginro hearthkindle","kalimdor hold em","psychometry","quintis jonespyre","raschal"},rel={"quest:4127","quest:4130","subzone:feathermoon-stronghold-classic","zone:feralas"},m={start="Ginro Hearthkindle",["end"]="Quintis Jonespyre",level="44",faction="Alliance",id=4129},src={"The Knife Revealed"}}
E["quest:4130"] = {t="quest",n="Psychometric Reading",z="feralas",s="After Psychometric Reading, Quintis Jonespyre is still unsteady. His vision shows Raschal and the Woodpaw gnolls, and Quintis asks you to carry word to Ginro Hearthkindle in Feathermoon Stronghold.",h="After Psychometric Reading, Quintis Jonespyre is still unsteady.",sec={{t="What Quintis Saw",b="Quintis Jonespyre is unsteady, but his vision may help. Raschal pulls two large leather backpacks from the boat, heads inland, then returns to the boat. Gnoll scalps appear, and Quintis believes Raschal met Woodpaw gnolls. Raschal is very worried, almost terrified, and does not notice water elementals forming behind him. Then the images end. Quintis needs rest, so he asks you to tell Ginro, who needs to know.",sp=0},{t="Ginro's Answer",b="Ginro Hearthkindle thanks you for bringing Quintis's visions. Raschal can handle a fight, and gnolls would not worry him, let alone terrify him. Even so, Ginro hopes you and your companions can act on this and make the breakthrough they badly need.",sp=1}},faq={{q="Who has the vision to share?",a="Quintis Jonespyre has the vision to share. Still wobbly after reading the knife, he asks you to carry word of it to Ginro.",al={"who gives psychometric reading","quest giver psychometric reading"}},{q="What did Quintis see in his vision?",a="Raschal took two large leather backpacks from the boat inland, then returned to it. Quintis saw gnoll scalps and believed the gnolls were Woodpaw. He also saw Raschal very worried, almost terrified, while water elementals formed behind him.",al={"what was quintis's vision","what happened to raschal vision"}},{q="Where does this report need to go?",a="Take the report to Ginro Hearthkindle in Feathermoon Stronghold.",al={"where do i deliver the vision","who do i talk to psychometric reading"}}},kw={"feathermoon stronghold","ginro hearthkindle","psychometric reading","quintis jonespyre","raschal","water elementals","woodpaw"},rel={"quest:4129","quest:4131","subzone:feathermoon-stronghold-classic","topic:gnoll","zone:feralas"},m={start="Quintis Jonespyre",["end"]="Ginro Hearthkindle",level="44",faction="Alliance",id=4130},src={"Psychometric Reading"}}
E["quest:4131"] = {t="quest",n="The Woodpaw Gnolls",z="feralas",s="In southern Feralas, you search Woodpaw camps for Raschal, the courier. After Quintis's vision, Ginro Hearthkindle sends you to find him or his belongings, though Ginro doubts the gnolls were his undoing.",h="In southern Feralas, you search Woodpaw camps for Raschal, the courier.",sec={{t="Where to Start Looking",b="Ginro Hearthkindle admits the Woodpaw, whom Ginro calls “friends,” may have done for Raschal after all. Still, Ginro feels the gnolls were not responsible, and their camps are the best place to start. Ginro has no clearer plan than to search them.\n\nGnolls keep what they scavenge and fight over it, so they may have found the backpacks Quintis mentioned. Ginro once avoided open fighting during earlier searches. Now the vision guides you, and Ginro says to rip into them. The camps lie in southern Feralas.",sp=0},{t="At the Camps",b="In the Lower Wilds, two large leather backpacks are tacked to a nearby tree. Each bears a small insignia of Feathermoon Stronghold on its front.",sp=1}},faq={{q="Who is being searched for?",a="Ginro Hearthkindle is searching for Raschal, the courier. Ginro wants evidence of Raschal or his belongings.",al={"who is missing","woodpaw gnolls search target","who is raschal"}},{q="Why search the Woodpaw gnoll camps?",a="Ginro says the Woodpaw camps are the best place to start. Gnolls keep what they scavenge and fight over it, so they may have found the backpacks Quintis mentioned.",al={"why woodpaw gnolls","why kill gnolls","why search gnoll camps"}},{q="Where did the clue about the backpacks come from?",a="Quintis Jonespyre mentioned the backpacks in his vision of Raschal taking two large leather backpacks from the boat.",al={"who mentioned backpacks","quint vision backpacks","how does ginro know about backpacks"}},{q="Where are the Woodpaw camps?",a="The Woodpaw camps lie in southern Feralas.",al={"woodpaw gnoll location","where are gnoll camps feralas","woodpaw camps map"}}},kw={"feathermoon stronghold","feralas","ginro hearthkindle","leather backpacks","lower wilds","quintis jonespyre","raschal","woodpaw gnolls"},rel={"quest:4130","zone:feralas","subzone:feathermoon-stronghold-classic","subzone:lower-wilds","topic:gnoll"},m={start="Ginro Hearthkindle",["end"]="Large Leather Backpacks",level="44",faction="Alliance",id=4131},src={"The Woodpaw Gnolls"}}
E["quest:4135"] = {t="quest",n="The Writhing Deep",z="feralas",s="In the Writhing Deep, Raschal has gone to investigate a grave danger to Feralas. Your search for him leads there.",h="In the Writhing Deep, Raschal has gone to investigate a grave danger to Feralas.",sec={{t="The Note in the Packs",b="The backpacks hold a parcel for Thalanaar and a hurried note with no recipient named. Raschal of Feathermoon wrote it after finding bug-like creatures in the Writhing Deep, south of the gnoll camps. He feared they threatened all of Feralas, so he went to investigate them himself. His note shows where he went.",sp=0},{t="What Waits Below",b="Below the Writhing Deep, you find a large pod of an alien kind. Its mucous surface bears hardened growths, and it is broad and tall enough to hold a person. Through its skin, you can make out the faint shape of a humanoid inside.",sp=1}},faq={{q="Who is Raschal?",a="Raschal of Feathermoon wrote the note found in the backpacks. He went to investigate bug-like creatures he had discovered, and your search for him continues.",al={"raschal lore","who is raschal","raschal feathermoon"}},{q="Where is the Writhing Deep located?",a="Raschal's note places the Writhing Deep south of the Woodpaw gnoll camps.",al={"writhing deep location","where is writhing deep","how to find writhing deep"}},{q="Why did Raschal go to the Writhing Deep?",a="Raschal wrote that he found insidious bug-like creatures there and felt he had to investigate them himself. He feared they threatened all of Feralas.",al={"why raschal went to the hive","raschal motives","why the writhing deep"}},{q="What comes before this search?",a="The search follows The Woodpaw Gnolls, the step before it.",al={"writhing deep prerequisite","what quest comes first"}}},kw={"feathermoon","feralas","pod","raschal","thalanaar","woodpaw","writhing deep","zukk'ash"},rel={"quest:4131","quest:4265","subzone:writhing-deep","zone:feralas","subzone:thalanaar","topic:gnoll"},m={start="Large Leather Backpacks",["end"]="Zukk'ash Pod",level="46",faction="Alliance",id=4135},src={"The Writhing Deep (quest)"}}
E["quest:4265"] = {t="quest",n="Freed from the Hive",z="feralas",s="At the Writhing Deep, Raschal lives, but the Zukk'ash hive has left him deeply stunned. He needs word sent to Ginro Hearthkindle in Feathermoon Stronghold.",h="At the Writhing Deep, Raschal lives, but the Zukk'ash hive has left him deeply stunned.",sec={{t="Out of the Pod",b="You help a night elf down from the pod, and he begins to stir. He names himself Raschal and says the bugs overwhelmed him, leaving him paralyzed inside. Though he looks healthy, he remains deeply stunned. He asks if the Stronghold sent you.",sp=0},{t="Word for Feathermoon Stronghold",b="Ginro Hearthkindle waits in Feathermoon Stronghold. Tell him Raschal lives and is well.",sp=0},{t="Back at the Stronghold",b="Raschal has reached the Stronghold and told Ginro what happened. Ginro says the whole Stronghold cannot begin to thank you. Raschal would have died without your timely arrival, and you asked for no mercenary's fee. Ginro names you a true hero and his friend for good.",sp=1}},faq={{q="Who is trapped inside the Zukk'ash pod?",a="Raschal, a night elf and the missing courier, is trapped inside the Zukk'ash pod. The bugs overwhelmed him and left him paralyzed inside.",al={"who is in the pod","who is raschal","freed from the hive trapped elf"}},{q="Who do I tell once Raschal is free?",a="Tell Ginro Hearthkindle in Feathermoon Stronghold that Raschal is alive and well.",al={"where to turn in freed from the hive","who do i talk to after freeing raschal","ginro hearthkindle location"}},{q="What came before this in the search?",a="The search follows The Writhing Deep, where you found the pod.",al={"what quest comes before freed from the hive","freed from the hive prerequisites","previous quest"}}},kw={"courier","feathermoon stronghold","feralas","ginro hearthkindle","pod","raschal","writhing deep","zukk'ash"},rel={"quest:4135","quest:4266","subzone:feathermoon-stronghold-classic","zone:feralas","quest:4124"},m={start="Zukk'ash Pod",["end"]="Ginro Hearthkindle",level="46",faction="Alliance",id=4265},src={"Freed from the Hive"}}
E["quest:4266"] = {t="quest",n="A Hero's Welcome",z="feralas",s="General Shandris Feathermoon has asked to see you in person. Ginro Hearthkindle thinks she may thank you for aiding Feathermoon Stronghold and speak about the Zukk'ash insects you and Raschal met in southern Feralas.",h="General Shandris Feathermoon has asked to see you in person.",sec={{t="A Summons",b="Ginro Hearthkindle says General Shandris Feathermoon is waiting in Feathermoon Stronghold's main compound. The reports about the Zukk'ash insects frighten him.",sp=0},{t="At the General's Side",b="General Shandris Feathermoon thanks you warmly for Feathermoon Stronghold and gives you a gift. She says your bravery against overwhelming odds deserves a thousand times more. A Zukk'ash hive has been found in Feralas, so she asks for your help again. She believes you are the best choice.",sp=1}},faq={{q="Why does General Feathermoon want to see me?",a="Ginro expects General Shandris Feathermoon wants to thank you for your help and discuss the Zukk'ash insects you and Raschal met in southern Feralas.",al={"why see shandris","shandris summons","a hero's welcome why"}},{q="Who sends you to speak with Shandris Feathermoon?",a="Ginro Hearthkindle says General Shandris Feathermoon wants to see you in person.",al={"who starts a hero's welcome","quest giver hero's welcome","ginro hearthkindle quest"}},{q="Where is General Shandris Feathermoon located?",a="General Shandris Feathermoon is waiting in the main compound of Feathermoon Stronghold.",al={"where is shandris","feathermoon stronghold general location","find shandris feathermoon"}},{q="What is the concern about the Zukk'ash insects?",a="Ginro finds the reports about the Zukk'ash insects frightening, and General Shandris Feathermoon wants to discuss them with you.",al={"what are zukk'ash","why are zukk'ash dangerous","insect hive feralas"}}},kw={"a hero's welcome","feathermoon stronghold","feralas","ginro hearthkindle","hive","raschal","shandris feathermoon","zukk'ash"},rel={"npc:shandris-feathermoon","subzone:feathermoon-stronghold-classic","quest:4265","zone:feralas"},m={start="Ginro Hearthkindle",["end"]="Shandris Feathermoon",level="46",faction="Alliance",id=4266},src={"A Hero's Welcome (Classic)"}}
E["quest:4267"] = {t="quest",n="Rise of the Silithid",z="feralas",s="In Darnassus, a copy of Raschal's account is bound for Gracina Spiritmight. General Shandris Feathermoon gives it to you, trusting the priestess's knowledge of such creatures.",h="In Darnassus, a copy of Raschal's account is bound for Gracina Spiritmight.",sec={{t="A Copy for the Protectorate",b="General Shandris Feathermoon entrusts you with a copy of Raschal's account for Gracina Spiritmight, an associate of the Protectorate. The main report has been filed in Darnassus, where Gracina lives as a priestess in the Temple of the Moon. Shandris believes her broad knowledge of such creatures will benefit everyone who receives the account. She sends you on with good wishes and a prayer that Elune watch over all.",sp=0},{t="What the Priestess Knows",b="Gracina Spiritmight welcomes you to the blessed Temple of the Moon. The night elves already know the terror Raschal describes, she says. Silithid will consume Feralas swiftly and rank among the greatest menaces anyone will face. Yet they are only tools of one of the gravest threats the Horde and the Alliance will ever face. Gracina prays that resolve will be found to defeat them before they destroy us.",sp=1}},faq={{q="Who sends you to Darnassus with this report?",a="General Shandris Feathermoon gives you a copy of Raschal's account for Gracina Spiritmight in Darnassus.",al={"who starts rise of the silithid","quest giver rise of the silithid","who gives rise of the silithid"}},{q="Who is Gracina Spiritmight?",a="Gracina Spiritmight is a priestess who lives in Darnassus's Temple of the Moon. Shandris Feathermoon calls her an associate of the Protectorate with broad knowledge of the creatures in Raschal's account.",al={"who is gracina","gracina spiritmight lore","where is gracina spiritmight"}},{q="What is Raschal's report about?",a="Raschal's account tells of the infestation in southeastern Feralas.",al={"what is raschals report","what did raschal find","contents of raschal report"}},{q="What came before this delivery?",a="This follows A Hero's Welcome, where you met General Feathermoon at the Stronghold.",al={"rise of the silithid prerequisite","what quest comes before rise of the silithid"}}},kw={"darnassus","feathermoon stronghold","feralas","gracina spiritmight","raschal","shandris feathermoon","silithid","temple of the moon"},rel={"subzone:feathermoon-stronghold-classic","subzone:temple-of-the-moon","npc:shandris-feathermoon","zone:feralas","zone:darnassus","topic:elune","topic:alliance","topic:horde"},m={start="Shandris Feathermoon",["end"]="Gracina Spiritmight",level="46",faction="Alliance",id=4267},src={"Rise of the Silithid (Feralas)"}}
E["quest:4281"] = {t="quest",n="Thalanaar Delivery",z="feralas",s="At the Woodpaw camps, a parcel for Thalanaar still waits for its recipient. The hand-written name may guide you there.",h="At the Woodpaw camps, a parcel for Thalanaar still waits for its recipient.",sec={{t="A Parcel Gone Astray",b="You find goods for Thalanaar in the Woodpaw gnoll camps. The small way-station lies in southeastern Feralas. A hand-written name on the parcel points you toward the person expecting the goods: Falfindel Waywarder.",sp=0},{t="Word at the Way-station",b="Falfindel Waywarder praises Elune as the shipment from Feathermoon Stronghold arrives at last. Falfindel fears Raschal, the usual courier, has met with ill fate. The Woodpaw have grown agitated over something to their south, and Falfindel suspects Raschal fell to the wilds there. Take care as you travel.",sp=1}},faq={{q="Who is Falfindel Waywarder?",a="Falfindel Waywarder is the hand-written name on the parcel. Falfindel is the person you are to find in Thalanaar.",al={"falfindel","who is falfindel","falfindel waywarder thalanaar"}},{q="Where is Thalanaar?",a="Thalanaar is a small way-station in southeastern Feralas. That is where the parcel was meant to go.",al={"thalanaar location","where is thalanaar"}},{q="Where was the parcel found?",a="You found the parcel in the Woodpaw gnoll camps.",al={"where did the parcel come from","package origin","undelivered parcel origin"}},{q="What happened to the courier?",a="The courier's fate is unknown. The delivery remains unfinished, and the parcel still needs to reach Thalanaar.",al={"who was the courier","missing courier name","who carried the parcel"}}},kw={"falfindel waywarder","feathermoon stronghold","feralas","raschal","thalanaar","undelivered parcel","woodpaw"},rel={"subzone:thalanaar","npc:falfindel-waywarder","subzone:feathermoon-stronghold-classic","zone:feralas","topic:gnoll","quest:4124"},m={start="Undelivered Parcel",["end"]="Falfindel Waywarder",level="44",faction="Alliance",id=4281},src={"Thalanaar Delivery"}}
E["quest:7003"] = {t="quest",n="Zapped Giants",z="feralas",s="On Feralas's Forgotten Coast, Zorbin Fandazzle tests a shrinking ray on the giants near the docks. He built it from a gnomish design and improved it with goblin know-how, then gives you the Ultra-Shrinker to try on Feralas's giants.",h="On Feralas's Forgotten Coast, Zorbin Fandazzle tests a shrinking ray on the giants near the docks.",sec={{t="A Shrinking Ray for the Giants",b="Zorbin Fandazzle needs the giants of Feralas dealt with so he can stay and keep his business. His answer is a shrinking ray based on a gnomish design, improved with what he calls superior goblin advances. He would rather you test it than risk his own life.\n\nUse the Ultra-Shrinker on Cliff Giants, Deep Striders, Wave Striders, Shore Striders or Land Walkers. Gather the miniaturization residue left behind when they shrink, then bring it back to the docks.",sp=0},{t="Why Zorbin Wants the Residue",b="Zorbin calls miniaturization residue valuable in engineering. It helps keep a zapper from exploding on its user. Then he adds that this applies only to other zappers, not the one in your hands.",sp=0},{t="Back at the Docks",b="Zorbin is delighted when you return with the residue and all your major appendages intact. He insists the Ultra-Shrinker was never risky and calls you a friend to goblins everywhere.",sp=1}},faq={{q="Who is behind the Ultra-Shrinker?",a="Zorbin Fandazzle built the Ultra-Shrinker by the docks on Feralas's Forgotten Coast.",al={"who gives zapped giants","zorbin fandazzle quest giver","where to start zapped giants"}},{q="Why does Zorbin want the giants shrunk?",a="Zorbin says the giants are bad for business if he is to stay there. Shrunken giants are far more manageable.",al={"why zap giants","why shrink giants feralas","zorbin fandazzle motivation"}},{q="Which giants can be shrunk?",a="Any kind of giant in Feralas will do. Along the Forgotten Coast, you can find Cliff Giants, Deep Striders, Wave Striders, Shore Striders and Land Walkers.",al={"what giants can i zap","which giants count","zapped giants targets"}},{q="What is miniaturization residue?",a="Miniaturization residue is left on a giant after it shrinks. Zorbin calls it valuable in engineering because it helps keep a zapper from exploding on its user.",al={"why miniaturization residue","what does residue do","zorbin residue purpose"}}},kw={"cliff giant","feralas","forgotten coast","land walker","miniaturization residue","ultra-shrinker","zapped giants","zorbin fandazzle"},rel={"quest:7725","zone:feralas","subzone:forgotten-coast","topic:goblin"},m={start="Zorbin Fandazzle",["end"]="Zorbin Fandazzle",level="48",id=7003,ri={"Miniaturization Residue"}},src={"Zapped Giants"}}
E["quest:7721"] = {t="quest",n="Fuel for the Zapping",z="feralas",s="On the Forgotten Coast, Zorbin Fandazzle puts his engineering shop to work in a poor place. The elementals trouble him, but their water cores can power the refining of the Ultra-Shrinker.",h="On the Forgotten Coast, Zorbin Fandazzle puts his engineering shop to work in a poor place.",sec={{t="Power from the Surf",b="Zorbin Fandazzle curses the unchecked power of elementalism and calls the coast's elementals pests. Yet he sees their water elemental cores as raw power for refining the Ultra-Shrinker. He asks you to fight the Sea Elementals and Sea Sprays along the coast. Keep their cores and bring them to him by the dock.",sp=0},{t="Zorbin's Thanks",b="Zorbin is delighted with the cores. They will keep his work going for some time, and fewer elementals now roam the coast. He admits that opening his shop in what may be the worst place imaginable gave him reason to cry at night. The payment strains his finances, but he offers it in gratitude.",sp=1}},faq={{q="Who is asking for the elemental cores?",a="Zorbin Fandazzle is asking for the elemental cores. His engineering shop is by the dock on the Forgotten Coast of Feralas.",al={"who gives fuel for the zapping","zorbin fandazzle quest giver","who starts fuel for the zapping"}},{q="Why does Zorbin Fandazzle need water elemental cores?",a="Zorbin Fandazzle needs water elemental cores as raw power for refining the Ultra-Shrinker. He considers the local elementals an ideal supply.",al={"why water elemental cores","what are cores used for","ultra-shrinker fuel"}},{q="Where are the elemental cores gathered?",a="Gather the cores from Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas.",al={"where to find cores","sea elemental location","where are sea sprays"}}},kw={"feralas","forgotten coast","sea elemental","sea spray","ultra-shrinker","water elemental core","zorbin fandazzle"},rel={"zone:feralas","subzone:forgotten-coast","quest:7726"},m={start="Zorbin Fandazzle",["end"]="Zorbin Fandazzle",level="48",id=7721,ri={"Water Elemental Core"}},src={"Fuel for the Zapping"}}
E["quest:7725"] = {t="quest",n="Again With the Zapped Giants",z="feralas",s="At the Forgotten Coast docks, Zorbin Fandazzle has another offer for you. Bring him more residue from Feralas giants shrunk with the Ultra-Shrinker. He can pay far less this time, but promises to spread word of your service.",h="At the Forgotten Coast docks, Zorbin Fandazzle has another offer for you.",sec={{t="An Encore for the Ultra-Shrinker",b="Zorbin Fandazzle asks you to shrink giants in Feralas again and bring ten miniaturization residues to the Forgotten Coast docks. There is always room for more, even after your first haul.\n\nHe cannot offer nearly as much this time. Instead, he promises to praise your service among his goblin friends, who have quite large ears.",sp=0},{t="Zorbin's Thanks",b="Zorbin Fandazzle is overjoyed that you have come through again, though the coin is less than you are used to. He says word of your great deeds for goblindom is already ringing through the Steamwheedle Cartel's seats of power.",sp=1}},faq={{q="Who asks for more residue?",a="Zorbin Fandazzle waits by the Forgotten Coast docks in Feralas and asks you for more residue.",al={"quest giver","zorbin location","who gives again with the zapped giants"}},{q="What came before this?",a="This follows Zapped Giants, your first round of residue gathering for Zorbin Fandazzle.",al={"prerequisite","previous quest","what do i do first"}},{q="How is the residue gathered?",a="Use Zorbin's Ultra-Shrinker on any kind of giant in Feralas to shrink it. Then find the residue on the shrunken giants.",al={"how to get residue","miniaturization residue","how to shrink giants"}},{q="Where are the giants found?",a="The giants are along Feralas's western coast.",al={"giant location","where are feralas giants","forgotten coast giants"}},{q="Will Zorbin take more residue another time?",a="Zorbin says he can always use more residue, so you can return with another batch of ten.",al={"is this repeatable","can i repeat again with the zapped giants","repeatable giant quest"}}},kw={"feralas","forgotten coast","giants","miniaturization residue","steamwheedle cartel","ultra-shrinker","zorbin fandazzle"},rel={"quest:7003","subzone:forgotten-coast","zone:feralas","topic:steamwheedle-cartel","topic:goblin"},m={start="Zorbin Fandazzle",["end"]="Zorbin Fandazzle",level="55",id=7725,ri={"Miniaturization Residue"}},src={"Again With the Zapped Giants"}}
E["quest:7726"] = {t="quest",n="Refuel for the Zapping",z="feralas",s="On the Forgotten Coast, Zorbin Fandazzle needs more water elemental cores. The shop is hard to establish, so the pay is small. Still, Zorbin promises to tell nearby folk of your help and says there are friends in the Cartel.",h="On the Forgotten Coast, Zorbin Fandazzle needs more water elemental cores.",sec={{t="More of the Same",b="Zorbin Fandazzle makes light of the heroic work of gathering goo from elemental beings. Then Zorbin asks if you want more of the same. Beneath the jest, Zorbin needs more water elemental cores.\n\nEstablishing a shop on the Forgotten Coast is a desperate business, so little can be given in return. Zorbin promises to tell everyone nearby how you helped, and says the promise is worth trusting because Zorbin knows people in the Cartel. Bring six cores from Sea Elementals and Sea Sprays on the Forgotten Coast to Zorbin near the dock.",sp=0},{t="Zorbin's Thanks",b="Zorbin is pleased with your work, though the coin may not be the most you will ever receive for it. Zorbin will tell comrades in the Steamwheedle Cartel of your efforts. There is more to do if you want it: Zorbin still needs further cores and similar things.",sp=1}},faq={{q="Who is requesting the water elemental cores?",a="Zorbin Fandazzle is waiting near the dock on the Forgotten Coast of Feralas.",al={"who gives this quest","who is zorbin fandazzle","where is zorbin"}},{q="Where do the water elemental cores come from?",a="The cores come from Sea Elementals and Sea Sprays on the Forgotten Coast of Feralas.",al={"where do cores drop","water elemental core location","which enemies drop cores"}},{q="Why does Zorbin Fandazzle need more cores?",a="Zorbin says more water elemental cores are needed while struggling to establish a shop on the coast.",al={"why does zorbin want cores","zorbin fandazzle motive","what are the cores for"}},{q="What came before this?",a="It follows Fuel for the Zapping, when you first gathered elemental cores for Zorbin.",al={"previous quest","prerequisite quest","what quest comes first"}}},kw={"feralas","forgotten coast","sea elemental","sea spray","steamwheedle cartel","water elemental core","zorbin fandazzle"},rel={"quest:7721","subzone:forgotten-coast","zone:feralas","topic:steamwheedle-cartel"},m={start="Zorbin Fandazzle",["end"]="Zorbin Fandazzle",level="55",id=7726,ri={"Water Elemental Core"}},src={"Refuel for the Zapping"}}
E["quest:7730"] = {t="quest",n="Zukk'ash Infestation",z="feralas",s="At Camp Mojache, Hadoken Swiftstrider suspects the Zukk'ash south of the gnolls are driving them into a frenzy. He sends you to the Writhing Deep to thin their numbers and return with twenty carapaces.",h="At Camp Mojache, Hadoken Swiftstrider suspects the Zukk'ash south of the gnolls are driving them into a...",sec={{t="The Foe South of the Gnolls",b="Hadoken Swiftstrider believes insect-like creatures live south of the gnolls. Whether they can think matters little to him. If they drive the gnolls into a frenzy against Camp Mojache, they threaten the camp as much as the gnolls do. So you enter their home, the Writhing Deep, to thin their numbers. Bring back twenty Zukk'ash carapaces as proof, and tell Hadoken what you find.",sp=0},{t="Hadoken's Verdict",b="Hadoken Swiftstrider is pleased when you return. Only a full-scale invasion can end the Zukk'ash presence, but your work has bought Camp Mojache time to devise a proper strategy. The camp will study the carapaces and learn all it can about these creatures. The danger has grown far beyond what anyone expected.",sp=1}},faq={{q="Who sends you after the Zukk'ash?",a="Hadoken Swiftstrider sends you from Camp Mojache in Feralas.",al={"quest giver","hadoken swiftstrider","who starts zukkash infestation"}},{q="What are the Zukk'ash?",a="Hadoken believes the Zukk'ash are insect-like creatures south of the gnolls. Whether they can think matters little to him; he fears they may be driving the gnolls into a frenzy.",al={"what are zukkash","zukkash insects","writhing deep bugs"}},{q="Where is the Writhing Deep?",a="The Writhing Deep, home to the Zukk'ash, lies south of the gnolls.",al={"writhing deep location","where is writhing deep","where are the insects"}},{q="Why does Hadoken want Zukk'ash carapaces?",a="Hadoken wants the carapaces as proof of your work against the Zukk'ash.",al={"why carapaces","zukkash carapace use","purpose of carapaces"}}},kw={"camp mojache","carapace","feralas","gnolls","hadoken swiftstrider","insects","writhing deep","zukk'ash"},rel={"quest:7732","subzone:writhing-deep","subzone:camp-mojache","zone:feralas","topic:gnoll"},m={start="Hadoken Swiftstrider",["end"]="Hadoken Swiftstrider",level="45",faction="Horde",id=7730,ri={"Zukk'ash Carapace"}},src={"Zukk'ash Infestation (Classic)"}}
E["quest:7731"] = {t="quest",n="Stinglasher",z="feralas",s="In the Writhing Deep, Hadoken Swiftstrider's scout has found an insect far larger than the others.",h="In the Writhing Deep, Hadoken Swiftstrider's scout has found an insect far larger than the others.",sec={{t="A Giant Among the Insects",b="A scout has found a giant insect wandering the twisted terrain of the Writhing Deep. It seems to give off an aura unlike the others, and Hadoken Swiftstrider has named it Stinglasher. Hadoken wants its secretion glands brought straight to Camp Mojache. By studying the insect's innards, Hadoken hopes to learn how to deal with this new threat.",sp=0},{t="Hadoken's Thanks",b="Hadoken Swiftstrider is impressed by your work. If Stinglasher is among the strongest insects, studying it may prove valuable. Hadoken must keep the camp defended long enough to benefit. In thanks from the whole camp, Hadoken gives you a coin bounty.",sp=1}},faq={{q="Who sends you after Stinglasher?",a="Hadoken Swiftstrider at Camp Mojache in Feralas sends you after Stinglasher.",al={"quest giver","who gives stinglasher","hadoken swiftstrider"}},{q="Where is Stinglasher found?",a="Stinglasher wanders the twisted terrain of the Writhing Deep.",al={"stinglasher location","where is stinglasher","writhing deep location"}},{q="What makes Stinglasher different from the other insects?",a="A scout reports that Stinglasher is far larger than the other insects and seems to give off an aura they lack.",al={"why stinglasher","what is stinglasher","stinglasher aura"}},{q="Why does Hadoken want Stinglasher's glands?",a="Hadoken wants Stinglasher's glands so its innards can be studied while a plan against this new threat is worked out.",al={"why collect glands","stinglasher glands purpose"}}},kw={"camp mojache","feralas","glands","hadoken swiftstrider","insect","stinglasher","writhing deep","zukk'ash"},rel={"quest:7730","quest:7732","subzone:camp-mojache","subzone:writhing-deep","zone:feralas"},m={start="Hadoken Swiftstrider",["end"]="Hadoken Swiftstrider",level="47",faction="Horde",id=7731},src={"Stinglasher (Classic)"}}
E["quest:7732"] = {t="quest",n="Zukk'ash Report",z="feralas",s="At Camp Mojache, Hadoken Swiftstrider says your work against the Zukk'ash has gone doubly well, though danger remains. He asks you to carry the camp's report to Zilzibin Drumlore in Orgrimmar.",h="At Camp Mojache, Hadoken Swiftstrider says your work against the Zukk'ash has gone doubly well, though danger...",sec={{t="A Document for the Drag",b="Hadoken Swiftstrider has a document about what Camp Mojache has learned of the Zukk'ash insects. Their threat remains, so he asks you to take the report to Orgrimmar. Zilzibin Drumlore lives in the Drag and knows alien creatures like these. Hadoken hopes the camp's findings will prove useful.",sp=0},{t="The Expert's Verdict",b="Zilzibin Drumlore has been expecting the report. He calls the creatures you faced an ancient threat the Horde keeps choosing to ignore. Hadoken was wise to send both the document and you. Zilzibin names the Zukk'ash as silithid. Some dismiss them as a mindless nuisance, but he says they threaten the Horde more than the Alliance could.",sp=1}},faq={{q="Who sends the report to Orgrimmar?",a="Hadoken Swiftstrider gives you the document at Camp Mojache in Feralas.",al={"who gives zukkash report","who starts zukkash report","quest giver"}},{q="To whom is the report delivered?",a="You deliver the report to Zilzibin Drumlore, who lives in the Drag of Orgrimmar.",al={"where does the report go","who gets zukkash report","drumlore location"}},{q="Why is the document taken to Orgrimmar?",a="Hadoken hopes Zilzibin Drumlore can put the camp's findings to use. Zilzibin is an expert on alien creatures like the Zukk'ash.",al={"why send to orgrimmar","purpose of report"}},{q="What came before this delivery?",a="The delivery follows your efforts against the Zukk'ash insects in Zukk'ash Infestation and Stinglasher.",al={"previous quests","prerequisites"}}},kw={"camp mojache","drag","feralas","hadoken swiftstrider","orgrimmar","silithid","zilzibin drumlore","zukk'ash report"},rel={"subzone:camp-mojache","zone:feralas","zone:orgrimmar","subzone:drag","topic:horde","topic:alliance"},m={start="Hadoken Swiftstrider",["end"]="Zilzibin Drumlore",level="48",faction="Horde",id=7732},src={"Zukk'ash Report"}}
E["quest:7733"] = {t="quest",n="Improved Quality",z="feralas",s="In northern Feralas, Pratt McGrubben wants tougher yeti hides from Rage Scar Hold. He asks you to bring ten to Feathermoon Stronghold.",h="In northern Feralas, Pratt McGrubben wants tougher yeti hides from Rage Scar Hold.",sec={{t="A Tougher Throng of Yetis",b="After The Mark of Quality, Pratt McGrubben has found finer hides. A tougher throng of yetis lives inside Rage Scar Hold in northern Feralas. Bring ten hides to Pratt at Feathermoon Stronghold, and he will pay handsomely. If these hides match the Feral Scar hides, they may prove as resilient as thorium.",sp=0},{t="Pratt's Thanks",b="The Rage Scar hides are better than Pratt McGrubben hoped. He can tell they will grow much harder once properly cured. In thanks, he gives you one of his latest creations.",sp=1}},faq={{q="Who asks for the Rage Scar yeti hides?",a="Pratt McGrubben asks you for Rage Scar yeti hides at Feathermoon Stronghold in Feralas.",al={"who gives improved quality","improved quality questgiver","pratt mcgrubben"}},{q="Where do the Rage Scar yetis live?",a="The Rage Scar yetis live inside Rage Scar Hold in northern Feralas.",al={"rage scar yeti location","where is rage scar hold","where to get rage scar hides"}},{q="How many hides are wanted?",a="Pratt McGrubben wants ten Rage Scar yeti hides.",al={"how many yeti hides","improved quality items needed"}},{q="What came before this?",a="This follows The Mark of Quality, when you dealt with the first throng of yetis.",al={"prerequisite quest","what quest leads to improved quality","previous quest"}}},kw={"feathermoon stronghold","feralas","improved quality","pratt mcgrubben","rage scar hold","thorium","yeti hide","yetis"},rel={"subzone:rage-scar-hold","subzone:feathermoon-stronghold-classic","zone:feralas"},m={start="Pratt McGrubben",["end"]="Pratt McGrubben",level="48",faction="Alliance",id=7733,ri={"Rage Scar Yeti Hide"}},src={"Improved Quality (Classic Alliance)"}}
E["quest:7734"] = {t="quest",n="Improved Quality",z="feralas",s="At Camp Mojache, Jangdor Swiftstrider now seeks finer hides from the tougher yetis in Rage Scar Hold.",h="At Camp Mojache, Jangdor Swiftstrider now seeks finer hides from the tougher yetis in Rage Scar Hold.",sec={{t="A Tougher Throng of Yetis",b="After The Mark of Quality, Jangdor Swiftstrider has found a better source of hides. Tougher yetis roam inside Rage Scar Hold in northern Feralas. Bring ten hides to Camp Mojache, and Jangdor will pay handsomely. If they match the Feral Scar hides, they may prove as resilient as thorium.",sp=0},{t="Jangdor's Thanks",b="Jangdor Swiftstrider finds the hides better than he hoped. Once properly cured, he can tell they will grow much harder. In thanks, he gives you one of his latest creations.",sp=1}},faq={{q="Who asks for the Rage Scar yeti hides?",a="Jangdor Swiftstrider asks for ten Rage Scar yeti hides at Camp Mojache in Feralas.",al={"who gives improved quality","improved quality questgiver","jangdor swiftstrider"}},{q="Where do the Rage Scar yetis live?",a="The Rage Scar yetis live inside Rage Scar Hold, in northern Feralas.",al={"rage scar yeti location","where is rage scar hold","where to get rage scar hides"}},{q="How many hides are wanted?",a="Jangdor Swiftstrider wants ten Rage Scar yeti hides.",al={"how many yeti hides","improved quality items needed"}},{q="What came before this?",a="It follows The Mark of Quality, when you dealt with the first throng of yetis.",al={"prerequisite quest","what quest leads to improved quality","previous quest"}}},kw={"camp mojache","feralas","improved quality","jangdor swiftstrider","rage scar hold","rage scar yeti","yeti hides"},rel={"subzone:camp-mojache","subzone:rage-scar-hold","zone:feralas"},m={start="Jangdor Swiftstrider",["end"]="Jangdor Swiftstrider",level="48",faction="Horde",id=7734,ri={"Rage Scar Yeti Hide"}},src={"Improved Quality (Classic Horde)"}}
E["quest:7735"] = {t="quest",n="Pristine Yeti Hide",z="feralas",s="In Feralas, a hide from Rage Scar's yetis may catch Pratt McGrubben's eye. It is unusually thick and tough, and Pratt is looking to buy yeti hides.",h="In Feralas, a hide from Rage Scar's yetis may catch Pratt McGrubben's eye.",sec={{t="A Hide Out of the Ordinary",b="Among the hides from Rage Scar's yetis, this one is unusually thick and sturdy. Pratt McGrubben wants to buy yeti hides at Feathermoon Stronghold in Feralas, so this hide may interest him.",sp=0},{t="Pratt's Reaction",b="Pratt is amazed by the hide and wonders if any yeti hide could be greater. He offers more than a single hide usually fetches, believing something special can be made from it.",sp=1}},faq={{q="Who wants the Pristine Yeti Hide?",a="Pratt McGrubben is looking to buy yeti hides at Feathermoon Stronghold in Feralas.",al={"who takes pristine yeti hide","where do i bring the yeti hide","pratt mcgrubben yeti hide"}},{q="What makes this hide special?",a="Compared with hides from Rage Scar's yetis, this one is unusually thick and tough.",al={"pristine yeti hide source","what makes the hide special","feralas yeti hide"}},{q="Where is Pratt McGrubben?",a="Pratt McGrubben is at Feathermoon Stronghold in Feralas.",al={"where is pratt mcgrubben","where to bring pristine yeti hide"}}},kw={"feathermoon stronghold","feralas","pratt mcgrubben","pristine yeti hide","rage scar","yeti pelt"},rel={"subzone:feathermoon-stronghold-classic","zone:feralas"},m={start="Pristine Yeti Hide",["end"]="Pratt McGrubben",level="48",id=7735},src={"Classic quest text: Pristine Yeti Hide"}}
E["quest:7738"] = {t="quest",n="Perfect Yeti Hide",z="feralas",s="At Camp Mojache, Jangdor Swiftstrider is buying yeti hides, and one you found may be perfect. It is thicker and tougher than the hides from the yetis of Rage Scar.",h="At Camp Mojache, Jangdor Swiftstrider is buying yeti hides, and one you found may be perfect.",sec={{t="A Hide Worth Showing",b="The hide feels thicker and sturdier than those from the yetis of Rage Scar. Jangdor Swiftstrider at Camp Mojache in Feralas buys yeti hides. This one is worth bringing to him.",sp=0},{t="Jangdor's Verdict",b="Jangdor Swiftstrider delights in the hide and calls it the finest he has ever seen. He offers more than he usually pays for one hide, sure he can make something special from it.",sp=1}},faq={{q="Who is interested in the Perfect Yeti Hide?",a="Jangdor Swiftstrider at Camp Mojache in Feralas wants to buy yeti hides.",al={"who wants the hide","who turns in perfect yeti hide","jangdor yeti pelt"}},{q="Why is this hide considered special?",a="Its unusual thickness and toughness set it apart from the hides from the yetis of Rage Scar.",al={"why is it perfect","what makes the hide special"}},{q="Where is Jangdor Swiftstrider?",a="Jangdor Swiftstrider is at Camp Mojache in Feralas.",al={"where is jangdor swiftstrider","where to bring perfect yeti hide"}}},kw={"camp mojache","feralas","jangdor swiftstrider","perfect yeti hide","rage scar","yeti pelt"},rel={"subzone:camp-mojache","zone:feralas"},m={start="Perfect Yeti Hide",["end"]="Jangdor Swiftstrider",level="48",id=7738},src={"Classic quest text: Perfect Yeti Hide"}}
E["quest:92858"] = {t="quest",n="WANTED: Ohk'zi",z="feralas",s="Latronicus Moonspear posts a bounty for the ogre Ohk'zi at Gordunni Outpost. His Gordunni kin threaten Feralas, though the naga pose the greater danger.",h="Latronicus Moonspear posts a bounty for the ogre Ohk'zi at Gordunni Outpost.",sec={{t="The Bounty",b="General Feathermoon offers payment for Ohk'zi's death, and Latronicus Moonspear posts the notice at Feathermoon Stronghold. The Gordunni ogres trouble Feralas, though they pose less danger than the naga. Ohk'zi was last seen at the outpost east of the stronghold. You are asked to bring his staff to Latronicus as proof of his death.",sp=0}},faq={{q="Who is Ohk'zi?",a="Ohk'zi is an ogre of the Gordunni, last seen at their outpost east of Feathermoon Stronghold.",al={"ohkzi","ohk'zi ogre","who is ohkzi"}},{q="Why is there a bounty on Ohk'zi?",a="General Feathermoon offers a bounty for Ohk'zi's death because the Gordunni ogres threaten Feralas.",al={"ohkzi bounty","why kill ohkzi","wanted ohkzi"}},{q="Where was Ohk'zi last seen?",a="Ohk'zi was last seen at the Gordunni outpost east of Feathermoon Stronghold.",al={"ohkzi location","where ohkzi","gordunni outpost"}},{q="What proof does Latronicus want?",a="Latronicus Moonspear asks you to bring the Staff of Ohk'zi to Feathermoon Stronghold as proof of his death.",al={"ohkzi proof","bring what to latronicus","staff of ohkzi"}},{q="Are the Gordunni the greatest threat in Feralas?",a="The Gordunni are a menace to Feralas, but the naga pose a greater threat.",al={"gordunni threat","naga or ogres","feralas danger"}}},kw={"bounty","feathermoon stronghold","feralas","gordunni","latronicus moonspear","naga","ohk'zi","ohkzi","staff of ohk'zi"},rel={"zone:feralas","subzone:feathermoon-stronghold-classic","subzone:gordunni-outpost","topic:naga"},m={id=92858},src={"In-game quest text: WANTED: Ohk'zi"},fv=true}
E["quest:92878"] = {t="quest",n="Lost for Words",z="feralas",s="At Camp Mojache, Blaise Montgomery hands you a scrawled note instead of speaking, having lost his lower jaw to Grimtotem raiders. A druid named Namida led the assault from the northwest, and he demands vengeance for what he suffered.",h="At Camp Mojache, Blaise Montgomery hands you a scrawled note instead of speaking, having lost his lower jaw...",sec={{t="A Scrawled Vengeance",b="At Camp Mojache, a Forsaken named Blaise Montgomery cannot speak. A violent skirmish with Grimtotem tauren cost him his lower jaw, leaving him only scraps of paper to scrawl his thoughts. His note names a druid named Namida as the leader of the raiders from a camp to the northwest. He wants her to pay for what she took.",sp=0}},faq={{q="Who is Blaise Montgomery?",a="Blaise Montgomery is a Forsaken resting at Camp Mojache who lost his lower jaw in a fight with Grimtotem tauren.",al={"who is blaise montgomery","blaise montgomery camp mojache","who gave this quest"}},{q="Who is Namida?",a="Namida is a Grimtotem druid leading a camp to the northwest, responsible for the attack on Blaise Montgomery.",al={"who is namida","namida grimtotem","grimtotem druid"}},{q="Why is Blaise Montgomery unable to speak?",a="He lost his lower jaw in an ambush by Grimtotem attackers, forcing him to write his thoughts on paper instead of speaking.",al={"why cant blaise talk","what happened to blaise","blaise missing jaw"}},{q="Where is the Grimtotem camp located?",a="Her camp lies to the northwest of Camp Mojache.",al={"where is namida camp","namida location","where to find namida"}},{q="What does Blaise Montgomery demand?",a="He asks for proof that the Grimtotem druid Namida has been slain, seeking vengeance for his lost jaw.",al={"what proof does blaise want","proof of demise","namida dead"}}},ang={["race:Undead"]="As a fellow Forsaken, you understand what it means to hold your frame together when limbs and jaws can be torn away in battle.",["class:Druid"]="As a druid, facing one of your own calling among the Grimtotem is a stark reminder that nature's power can be bent to violence."},kw={"blaise montgomery","camp mojache","druid","feralas","forsaken","grimtotem","lost for words","namida grimtotem"},rel={"subzone:camp-mojache","topic:druid","topic:forsaken"},m={faction="Horde",id=92878},src={"In-game quest text: Lost for Words"},fv=true}
E["quest:98155"] = {t="quest",n="Pristine Pesterhide Pelts",z="feralas",s="In Thousand Needles, Kristy Grant hopes to send Pesterhide pelts to her sisters in Stormwind. They can make the hides into garments and goods, while Kristy relies on travelers to gather them.",h="In Thousand Needles, Kristy Grant hopes to send Pesterhide pelts to her sisters in Stormwind.",sec={{t="A Sisterly Ambition",b="As Kristy Grant crosses the canyon floor of Thousand Needles, the Pesterhide hyenas catch her eye. Their pelts are little known in the Eastern Kingdoms, and she hopes to send some home to her sisters in Stormwind. Skilled hands in her family can turn the hides into fine garments and goods.",sp=0},{t="Hunters of the Salt Flats and Canyons",b="Kristy Grant knows craft and trade, but she has no combat experience. Pesterhide hyenas roam beneath the mesas in vicious packs, so gathering their hides alone is dangerous. She relies on seasoned travelers to bring her five undamaged pelts for her sisters to work with back home.",sp=0}},faq={{q="Who is Kristy Grant?",a="Kristy Grant is a traveler from Stormwind journeying through Kalimdor. She has no fighting experience, but a keen eye for valuable materials, and asks capable travelers to gather goods such as hyena pelts for her.",al={"kristy grant lore","who gives pristine pesterhide pelts","who is kristy grant"}},{q="What are Pesterhide hyenas?",a="Pesterhide hyenas are wild predators native to Thousand Needles. They hunt and scavenge in packs across the canyon floor and dusty expanses, and their striking coats catch the eye of travelers who work with hides and fur.",al={"pesterhide hyena","thousand needles hyenas","what are pesterhides"}},{q="Why does Kristy Grant want the pelts?",a="Kristy Grant wants pristine Pesterhide hyena pelts to send across the sea to her sisters in Stormwind. She admires their color and trusts her sisters to make the furs into fine goods.",al={"why collect pesterhide pelts","pesterhide pelt purpose","what does kristy do with the pelts"}},{q="Where do the pelts end up?",a="The pelts are bound for Stormwind in the Eastern Kingdoms. Kristy plans to send them across the Great Sea to her sisters, who can work with materials rarely found in Elwynn or Redridge.",al={"where are the pelts sent","pelts stormwind","who gets the hyena pelts"}},{q="Why can't Kristy hunt the hyenas herself?",a="Kristy Grant has no fighting experience, and the wild beasts of Thousand Needles are dangerous. She relies on skilled travelers to hunt the hyenas rather than risk injury or death among their packs.",al={"why can't kristy fight","kristy grant combat","why does kristy need help"}},{q="What makes these pelts pristine?",a="The pelts must be undamaged so Kristy's sisters can use their color and texture in fine garments. Careful hunting preserves the best hides.",al={"pristine pelts meaning","why pristine hides","pristine pesterhide pelt quality"}}},ang={["faction:Alliance"]="Kristy's effort to supply her artisan family in Stormwind shows Alliance subjects traveling deep into Kalimdor for rare materials.",["race:Human"]="Kristy Grant shows the enterprising spirit of Stormwind humans who cross the sea while keeping close ties with kin at home.",["profession:Tailoring"]="Crafters who work with cloth and decorative furs can appreciate Kristy's sisters' plan to turn wild Kalimdor hides into fine garments."},kw={"fur","hunting","hyena","kristy grant","pelts","pesterhide","stormwind","thousand needles"},rel={"zone:thousandneedles","topic:stormwind-kingdom"},m={faction="Alliance",id=98155},src={"In-game quest text: Pristine Pesterhide Pelts"},fv=true}
E["quest:98156"] = {t="quest",n="Packaged Pristine Pelts",z="feralas",s="A traveler asks you to carry pristine pelts to her sisters in Stormwind. The delivery can reach them before she can return home.",h="A traveler asks you to carry pristine pelts to her sisters in Stormwind.",sec={{t="A Family Delivery",b="The package of pristine pelts is meant for Kimberly Grant. She cannot return home for some time, and expects you to reach Stormwind first. Her sisters Kelly and Kimberly can usually be found in the Park.",sp=0}},faq={{q="Who wants the pelts delivered?",a="A traveler asks you to deliver the pristine pelts to her sisters, Kelly and Kimberly.",al={"who gave me pelts","pelt delivery giver"}},{q="Who should receive the package?",a="The package is to be delivered to Kimberly Grant in Stormwind.",al={"pelts for who","deliver to kimberly"}},{q="Where can I find the sisters?",a="Kelly and Kimberly can usually be found in the Park in Stormwind.",al={"kelly kimberly location","sisters in stormwind"}},{q="Why am I carrying the pelts?",a="The traveler cannot return to Stormwind for some time and asks you to bring the pelts to her sisters.",al={"why deliver pelts","pelt package reason"}}},kw={"kelly","kimberly grant","package","park","pristine pelts","sisters","stormwind"},rel={"subzone:park","topic:stormwind-kingdom"},m={faction="Alliance",id=98156},src={"In-game quest text: Packaged Pristine Pelts"},fv=true}
E["subzone:camp-mojache"] = {t="subzone",n="Camp Mojache",z="feralas",s="At Camp Mojache, the Horde holds a foothold in eastern Feralas beside the stream that feeds Wildwind Lake. The tauren outpost offers provisions and flight connections amid dangerous wildlife and ancient ruins.",h="At Camp Mojache, the Horde holds a foothold in eastern Feralas beside the stream that feeds Wildwind Lake.",sec={{t="A Tauren Bastion in the Rainforest",b="In eastern Feralas, Camp Mojache gives Horde travelers shelter beside the stream that feeds Wildwind Lake. Deep forest surrounds the camp, with savage wildlife, Gordunni ogres, and Woodpaw gnolls nearby. Lodging, trade supplies, and a wind rider roost support travelers crossing the region.",sp=0},{t="Frontier Outpost",b="Tauren hunters and braves watch for attacks from the wilderness. Holding Mojache extends the Horde's reach across Feralas, where Night Elves hold the coast and dark forces lurk within Dire Maul.",sp=0}},faq={{q="What is Camp Mojache?",a="Camp Mojache is the Horde's main base in Feralas. Mostly tauren built and maintain it beside the stream flowing into Wildwind Lake, where it offers lodging, trade supplies, and flight transport.",al={"camp mojache purpose","what is this camp","tauren town feralas"}},{q="Who leads or defends the camp?",a="Seasoned tauren braves defend Camp Mojache from local beasts, Gordunni ogres, and Woodpaw gnolls that prowl the hills just to the south.",al={"camp mojache guards","who defends mojache","who is in charge of camp mojache"}},{q="Where does the local flight master travel?",a="From Camp Mojache's wind rider perch, you can fly to Thunder Bluff, the Crossroads in the Barrens, Shadowprey Village in Desolace, and nearby Gadgetzan in Tanaris.",al={"camp mojache flight paths","where can i fly from camp mojache"}},{q="What major threats surround Camp Mojache?",a="Woodpaw gnolls live in the woods to the south, while Gordunni ogres range to the north and south. Alliance forces operate from Feathermoon Stronghold on the distant western coast.",al={"feralas danger camp mojache","threats near camp mojache","enemies near mojache"}}},ang={["race:Tauren"]="As a tauren, you find Camp Mojache at the farthest southern reach of your people's traditional craftsmanship and settlements in Kalimdor. Here, your people carve out harmony within the deep rainforest.",["faction:Horde"]="As a member of the Horde, you can rely on Mojache as Feralas's sole fortified hub for rest, provisions, and swift travel through the deep forest."},kw={"braves","camp mojache","feralas","flight master","gordunni","tauren","wildwind lake","woodpaw"},rel={"zone:feralas","topic:tauren","topic:horde","zone:thunderbluff","subzone:crossroads","subzone:shadowprey-village","subzone:gadgetzan","topic:gnoll"},src={"Camp Mojache"}}
E["subzone:capital-gardens"] = {t="subzone",n="Capital Gardens",z="feralas",s="In Dire Maul's western wing, corrupted growth and spirits haunt the Capital Gardens. Once a park for Kaldorei nobles, the grounds now shelter corrupted ancients, ghosts, and Shen'dralar remnants.",h="In Dire Maul's western wing, corrupted growth and spirits haunt the Capital Gardens.",sec={{t="A Decayed Sanctuary",b="Broken marble terraces and twisted gray boughs fill the Capital Gardens. Corrupted treants haunt the courtyards. Ten millennia ago, Eldre'Thalas was one of the Kaldorei empire's great cities. Its outdoor district offered enchanted plants and broad terraces where Highborne sorcerers met to debate and rest.\n\nAfter the Great Sundering, the enclave fell on hard times. Without the Well of Eternity, the Shen'dralar turned to dark magic to preserve their immortality. The gardens withered, and lingering corruption keeps the woodland from healing.",sp=0},{t="The Athenaeum and the Prison",b="Overgrown paths pass hostile ancients on the way to the Court of the Highborne and the Athenaeum. The library preserves centuries of arcane lore and forgotten treatises. Farther in, the Prison of Immol'thar holds a demon bound by the surviving elves, who sought to draw on its power. That desperate act warped the gardens around it.",sp=1}},faq={{q="What is the Capital Gardens?",a="The Capital Gardens occupy Dire Maul's western wing, among the ruins of Eldre'Thalas in central Feralas. They once served as a public park and home for the city's Highborne elite.",al={"what is capital gardens","dire maul west gardens","eldre'thalas park"}},{q="Why are the trees and ancients corrupted here?",a="After the Well of Eternity was destroyed, the surviving Shen'dralar drew dark fel energy from the summoned demon Immol'thar to sustain themselves. The leaking magic warped local plants and drove the resident ancients mad with violence.",al={"why are ancients evil here","what happened to the trees","why is it blighted"}},{q="Where does this area lead?",a="The gardens lead deeper into Dire Maul's western complex, to the Court of the Highborne, the scholarly Athenaeum, and the inner sanctuary where Immol'thar is held.",al={"what connects to capital gardens","where does it go"}},{q="Are there any friendly elves left in the gardens?",a="Most Highborne on the paths are hostile spirits or maddened defenders. Some Shen'dralar scholars still endure in the nearby Athenaeum, where they barter ancient knowledge or trade for lost elven librams.",al={"any allies inside","who lives in capital gardens"}}},ang={["race:NightElf"]="For night elves, the Capital Gardens' blighted paving recalls Highborne hubris and the ruinous cost of arcane addiction.",["class:Mage"]="The gardens' paths lead toward the Athenaeum, one of Kalimdor's greatest surviving collections of pre-Sundering magical theory."},kw={"athenaeum","capital gardens","dire maul west","eldre'thalas","feralas","immol'thar","shen'dralar"},rel={"subzone:dire-maul","zone:feralas","topic:highborne","subzone:gordok-commons"},src={"Capital Gardens"},nf=true}
E["subzone:dire-maul"] = {t="subzone",n="Dire Maul",z="feralas",s="In Feralas, Dire Maul's broken halls and coliseums are divided among rival powers. Once called Eldre'Thalas, the ancient Highborne city guarded Queen Azshara's arcane secrets. Gordok ogres, invading satyrs, and withered elven caretakers now divide its crumbling plazas.",h="In Feralas, Dire Maul's broken halls and coliseums are divided among rival powers.",sec={{t="Eldre'Thalas and the Great Sundering",b="Eldre'Thalas sheltered Queen Azshara's favored sorcerers, the Shen'dralar. When the Well of Eternity collapsed in the Great Sundering, Prince Tortheldrin raised a magical barrier that saved the city. Cut off from their source of magic, the surviving Highborne trapped the colossal demon Immol'thar beneath their sanctum. For millennia, they drew on its fel essence to preserve their immortality and arcane power.",sp=0},{t="A Divided Ruin",b="Centuries of isolation and dwindling power drove Prince Tortheldrin mad. He purged most of his own citizens so a small cabal could monopolize the demon's remaining energy. Beyond their sanctuaries, other powers hold the ruins. Gordunni ogres control the Gordok Commons and stage brutal gladiatorial games in the arena. In the Warpwood Quarter, Alzzin the Wildshaper and his corrupt satyrs spread their rot.",sp=1}},faq={{q="What was Dire Maul originally called?",a="Dire Maul was once Eldre'Thalas, an opulent night elf city built twelve thousand years ago by the Shen'dralar. They raised it to protect Queen Azshara's most precious arcane lore.",al={"dire maul original name","eldre'thalas history","who built dire maul"}},{q="Who lives in Dire Maul now?",a="Hostile powers divide Dire Maul. Gordunni ogres control the northern commons under King Gordok, satyrs and corrupted treants infest the eastern gardens, and a reclusive remnant of Highborne sorcerers clings to survival in the western sanctuaries.",al={"who is in dire maul","dire maul occupants","what monsters are in dire maul"}},{q="How did the city survive the Sundering?",a="When the Great Sundering tore the continent apart, Prince Tortheldrin and his arcanists cast a massive protective spell. It shielded Eldre'Thalas from the devastation that submerged the surrounding empire.",al={"how did eldre'thalas survive","sundering shield dire maul","why wasn't it destroyed"}},{q="Why are the Highborne here using demonic energy?",a="After the Well of Eternity was destroyed, the Shen'dralar suffered severe arcane withdrawal. To preserve their power and immortality, they bound Immol'thar and siphoned the demon's essence to survive.",al={"immol'thar dire maul","why do shen'dralar drain a demon","demon in dire maul"}},{q="What happens in the arena at Dire Maul?",a="Ogres and slavemasters use the open coliseum in the city center, known as the Maul, as a fighting pit. There they hold gladiatorial tournaments, blood sports, and challenges to the Gordok throne.",al={"dire maul coliseum","the maul pvp","gladiators dire maul"}}},ang={["race:NightElf"]="As a night elf, you can see Eldre'Thalas as a tragic monument to unchecked arcane hubris and the demonic compromises that broke the ancient Kaldorei Empire.",["class:Mage"]="As a mage, you can find arcane treatises and secrets from before the Great Sundering in the ruined Shen'dralar libraries, guarded by the ghosts of master sorcerers."},kw={"dire maul","eldre'thalas","feralas","gordok","gordunni","immol'thar","shen'dralar","tortheldrin"},rel={"zone:feralas","topic:highborne","subzone:gordok-commons","subzone:capital-gardens","subzone:warpwood-quarter","subzone:maul-subzone","topic:satyr","topic:war-of-the-ancients"},src={"Dire Maul"}}
E["subzone:dream-bough"] = {t="subzone",n="Dream Bough",z="feralas",s="On an island in northern Feralas, green dragons guard Dream Bough. The ancient Great Tree shelters a gateway into the Emerald Dream.",h="On an island in northern Feralas, green dragons guard Dream Bough.",sec={{t="The Great Tree of Jademir",b="Dream Bough rises above the forest on an island in Jademir Lake. It is the largest tree in northern Feralas. A natural portal opens in its trunk and leads straight into the untamed Emerald Dream.",sp=0},{t="The Emerald Watchers",b="The Green Dragonflight guards Dream Bough and the gateway in its trunk. Dragonkin and drakes patrol the lake’s banks and the approaches to the great tree. Druids come to contemplate and sleep as they pass between realms. Few uninvited travelers are tolerated near this threshold, so approach with care.",sp=0}},faq={{q="What is the Dream Bough?",a="Dream Bough is a massive Great Tree on an island in Jademir Lake, in northern Feralas. A gateway in its trunk opens directly into the Emerald Dream.",al={"dream bough tree","what is dream bough","jademir lake tree"}},{q="Who planted the Dream Bough?",a="No account from this age records who planted Dream Bough. The Great Tree shelters a gateway into the Emerald Dream, and the Green Dragonflight watches over it.",al={"who grew dream bough","origin of dream bough","staghelm tree"}},{q="Why are there green dragons here?",a="The Green Dragonflight guards the Emerald Dream. Since a direct gateway opens in Dream Bough’s trunk, dragons and their kin keep watch to protect it from intruders.",al={"green dragonflight dream bough","dragons at jademir lake"}},{q="Can players enter the portal into the Emerald Dream?",a="The portal in Dream Bough’s trunk opens into the Emerald Dream, but mortal adventurers awake in the physical realm cannot pass through it. Powerful sleeping druids and the Green Dragonflight cross freely.",al={"can i use dream bough portal","enter emerald dream feralas"}}},ang={["class:Druid"]="As a druid, you know Dream Bough as sacred ground, a living bridge between Azeroth’s wilderness and the Emerald Dream your order tends.",["race:NightElf"]="As a night elf, you can see in this great tree your people’s ancient duty to nurture and defend the natural world."},kw={"dream bough","emerald dream","feralas","great tree","green dragonflight","jademir lake"},rel={"zone:feralas","topic:emerald-dream","topic:druid"},src={"Dream Bough"}}
E["subzone:eldreth-row"] = {t="subzone",n="Eldreth Row",z="feralas",s="Gordunni ogres patrol Eldreth Row, the ruined western halls of Dire Maul. Overgrown stone once marked the outer threshold of ancient Eldre'Thalas.",h="Gordunni ogres patrol Eldreth Row, the ruined western halls of Dire Maul.",sec={{t="The Threshold of Eldre'Thalas",b="Eldreth Row opens onto the outer halls of ancient Eldre'Thalas. The avenue lies before the deeper quarters and the Broken Commons. Centuries of neglect have cracked the stone, and Feralas plants overrun its colonnades. The Highborne halls now serve the Gordunni ogres as a staging ground. Their patrols guard the paths east toward the Warpwood Quarter and west past the Dire Pool.",sp=0}},faq={{q="What is Eldreth Row?",a="Eldreth Row is Dire Maul's outer entrance hall in Feralas. It lies before the Broken Commons and the inner gateways.",al={"eldreth row","what is this place","dire maul entrance"}},{q="Who controls Eldreth Row right now?",a="Gordunni ogres occupy Eldreth Row and patrol its broken avenues, guarding the Dire Maul ruins.",al={"who lives here","who controls eldreth row","eldreth row monsters"}},{q="Where does Eldreth Row lead?",a="Eldreth Row leads inward toward the Broken Commons and Dire Maul's main complexes. The Warpwood Quarter lies to the east, and the Dire Pool to the west.",al={"where does this hall go","eldreth row exits","dire maul paths"}}},ang={["race:NightElf"]="As a night elf, you may see in Eldre'Thalas's ancient masonry a reminder of the Highborne's fall and the Sundering. Ogres now hold the ruins."},kw={"broken commons","dire maul","dire pool","eldre'thalas","eldreth row","feralas","gordunni","warpwood quarter"},rel={"subzone:dire-maul","subzone:commons","subzone:warpwood-quarter","zone:feralas"},src={"Eldreth Row"}}
E["subzone:feathermoon-stronghold-classic"] = {t="subzone",n="Feathermoon Stronghold",z="feralas",s="On Sardor Isle, Feathermoon Stronghold guards Feralas's western shore. General Shandris Feathermoon established it as the Alliance's main staging ground and military anchor in southern Kalimdor.",h="On Sardor Isle, Feathermoon Stronghold guards Feralas's western shore.",sec={{t="Sentinel Bastion of the South",b="Feathermoon Stronghold guards Sardor Isle, just off the Forgotten Coast. General Shandris Feathermoon built the fortress to carry Sentinel power deep into southern Kalimdor. Tyrande Whisperwind has trusted Shandris as her lieutenant for ten thousand years. The island shields the stronghold from beasts, ogres, and Horde forces crossing mainland Feralas.",sp=0},{t="Lifeline Across the Waves",b="Boats and hippogryphs link Feathermoon Stronghold to the mainland and distant Alliance hubs. A passenger boat crosses the channel between Sardor Isle and the Forgotten Coast dock. For longer journeys, a hippogryph roost connects the stronghold with Thalanaar on the Thousand Needles border, Nijel's Point in the Desolace highlands, and Auberdine in the north.",sp=0}},faq={{q="How do you reach Feathermoon Stronghold from mainland Feralas?",a="From mainland Feralas, take the ferry from a Forgotten Coast dock across the strait, or swim the narrow channel to Sardor Isle. Alliance travelers can also fly by hippogryph after discovering the flight master.",al={"how to get to feathermoon","feathermoon boat","getting to sardor isle"}},{q="Who commands Feathermoon Stronghold?",a="General Shandris Feathermoon commands Feathermoon Stronghold. She leads the Sentinels and has long served High Priestess Tyrande Whisperwind as a military subordinate.",al={"who leads feathermoon","feathermoon leader","shandris feathermoon"}},{q="Why is the stronghold located on an island instead of the mainland?",a="Sardor Isle's isolation shields Feathermoon Stronghold from Feralas's dense threats, including aggressive wildlife, primal ruins, and hostile forces. That protection lets the Sentinels hold a secure redoubt.",al={"why on sardor isle","why island fortress","feathermoon location lore"}},{q="Where do flight paths from Feathermoon connect?",a="Feathermoon's hippogryph routes connect to Auberdine in Darkshore, Nijel's Point in Desolace, and Thalanaar in Feralas.",al={"feathermoon flight master","where do feathermoon hippogryphs go"}}},ang={["faction:Alliance"]="For the Alliance, Feathermoon Stronghold offers a safe haven, vendor post, and staging center for operations deep in southern Kalimdor.",["race:NightElf"]="As a night elf, you can look to feathermoon stronghold as the southern military seat of General Shandris Feathermoon and the Sentinels, guarding the ancient wilderness."},kw={"alliance","feathermoon stronghold","feralas","forgotten coast","sardor isle","sentinels","shandris feathermoon"},rel={"subzone:sardor-isle","zone:feralas","subzone:forgotten-coast","topic:sentinels","topic:alliance","subzone:thalanaar","subzone:nijel-s-point","subzone:auberdine"},src={"Feathermoon Stronghold (Classic)"}}
E["subzone:feral-scar-vale"] = {t="subzone",n="Feral Scar Vale",z="feralas",s="In western Feralas, Feral Scar yetis hold a rocky gorge deep in the High Wilderness. Their caves lie beyond the forest trails, where travelers face danger.",h="In western Feralas, Feral Scar yetis hold a rocky gorge deep in the High Wilderness.",sec={{t="Lair of the Yetis",b="For generations the primal Feral Scar yetis have held the caves of Feral Scar Vale. Unlike the yetis of Alterac and Dun Morogh, these brutes have adapted to Feralas's humid wilds. They defend their cave network fiercely and keep bone trophies. Intruders are driven from their hunting grounds.",sp=0},{t="Curiosities in the Caves",b="Gnomish distress signals have sometimes led into the deeper caves of Feral Scar Vale. Lost devices have become trapped there among the yetis, including robotic survey chickens. They wait to be activated and recovered.",sp=0}},faq={{q="What kind of creatures live in Feral Scar Vale?",a="Feral Scar yetis dominate the vale. These massive, territorial predators live in its rocky caves and patrol the surrounding forest.",al={"feral scar vale mobs","what is in feral scar vale","vale creatures"}},{q="Where is Feral Scar Vale located?",a="Feral Scar Vale lies in western Feralas, within the High Wilderness and south of the main road through the rainforest canopy.",al={"feral scar vale location","where is feral scar vale","how to find feral scar vale"}},{q="Why are there yetis in a lush rainforest?",a="Though yetis are usually tied to snowy mountains, Kalimdor's ancient wilds also hold Feral Scar yetis. This distinct kind has thrived in dense forest valleys for generations.",al={"why yetis in feralas","jungle yetis","feralas yeti lore"}},{q="What is the mechanical chicken inside the cave?",a="Homing Robot OOX-22/FE is a mechanical survey chicken made by gnome engineers. It crashed in a cave deep in the vale and became stranded behind the yeti lines.",al={"oox-22/fe","robot chicken feralas","homing robot feral scar vale"}}},ang={["profession:Engineering"]="A stranded gnome homing robot lies in the yeti tunnels. As an engineer, you can use an emergency beacon to bring it safely back to civilization.",["class:Hunter"]="As a hunter, you can track Feral Scar yetis stalking the cliffs and test your skill at big-game hunting beneath the High Wilderness canopy."},kw={"feral scar vale","feralas","high wilderness","homing robot","oox-22/fe","yeti"},rel={"zone:feralas","subzone:high-wilderness"},src={"Feral Scar Vale"}}
E["subzone:forgotten-coast"] = {t="subzone",n="Forgotten Coast",z="feralas",s="Sea giants and water elementals roam Feralas’s western shore, where the Forgotten Coast meets the Veiled Sea.",h="Sea giants and water elementals roam Feralas’s western shore, where the Forgotten Coast meets the Veiled Sea.",sec={{t="Edge of the Rainforest",b="The rainforest ends at the Forgotten Coast, and the Veiled Sea opens beyond it. With no canopy overhead, the strand lies exposed to wind and weather. Sea giants tower over the shore while water elementals prowl the surf. Travelers crossing the forest must pass these ancient guardians to reach the water. A ferry carries them from the mainland to sardor isle, home of the night elven feathermoon stronghold.",sp=0}},faq={{q="What threats wander the Forgotten Coast?",a="Sea giants and water elementals roam the Forgotten Coast, emerging from the Veiled Sea.",al={"monsters on forgotten coast","forgotten coast dangers","what is on the coast"}},{q="How do you reach Feathermoon Stronghold from here?",a="Take the ferry across the channel from the coast to Sardor Isle, where the night elves hold Feathermoon Stronghold. Sea giants prowl the waters near the dock.",al={"how to get to feathermoon","boat to feathermoon","feathermoon ferry"}},{q="Is the Forgotten Coast accessible to the Horde?",a="Yes. A northern path leads down to the coast, so Horde travelers can avoid the southern route toward the night elven crossing and its sentinels.",al={"horde access forgotten coast","how does horde reach coast","safe horde path forgotten coast"}}},ang={["faction:Alliance"]="For the Alliance, the coast links the Kalimdor mainland to feathermoon stronghold on sardor isle. Sea giants roam the shore, so stay alert.",["faction:Horde"]="As a Horde traveler, take the northern forest paths for safer passage to the water. The southern trail runs near night elven ferry points."},kw={"feralas","forgotten coast","sardor isle","sea giants","veiled sea"},rel={"zone:feralas","subzone:feathermoon-stronghold-classic","topic:horde"},src={"Forgotten Coast"}}
E["subzone:frayfeather-highlands"] = {t="subzone",n="Frayfeather Highlands",z="feralas",s="In Feralas, Frayfeather hippogryphs defend their ancestral roosts. Scavengers and naturalists brave the flocks in search of intact eggs.",h="In Feralas, Frayfeather hippogryphs defend their ancestral roosts.",sec={{t="Aerie of the Hippogryphs",b="Wild hippogryphs raise their broods on steep slopes and crags above Feralas's forest floor. The flocks defend their scattered nests among the rock shelves with fierce aggression. Their mastery of the rugged cliffs draws outsiders to the nesting grounds. Goblin entrepreneurs in distant Gadgetzan seek unhatched eggs for study and profit.",sp=0}},faq={{q="What creatures live in the Frayfeather Highlands?",a="Large flocks of wild Frayfeather hippogryphs nest across the high rock faces. They defend their territory fiercely against trespassers.",al={"frayfeather wildlife","what is here","frayfeather beasts"}},{q="Why are travelers interested in the hippogryph nests?",a="Rare hippogryph eggs lie in the nests. Adventurers carry viable eggs across Tanaris to Gadgetzan, where goblins process them in the Super Egg-O-Matic for research and profit.",al={"hippogryph eggs","egg quest","why steal eggs"}},{q="Where are the Frayfeather Highlands located?",a="The highlands rise in southern Feralas above the main jungle canopy. Their craggy hillsides offer open perches for nesting.",al={"frayfeather location","where is frayfeather highlands","how to find frayfeather"}}},ang={["race:NightElf"]="As a night elf, you revere hippogryphs as sacred companions of Elune. Their wild nests in Feralas deserve protection from reckless exploitation.",["class:Druid"]="As a druid, you hold Kalimdor's wild beasts in high regard. The undisturbed aeries of the Frayfeather Highlands reflect the forest's primal vitality."},kw={"eggs","feralas","frayfeather","gadgetzan","highlands","hippogryph","nests"},rel={"zone:feralas","subzone:gadgetzan"},src={"Frayfeather Highlands"}}
E["subzone:gordok-commons"] = {t="subzone",n="Gordok Commons",z="feralas",s="In the Gordok Commons, King Gordok rules the Gordunni’s northern stronghold in Dire Maul.",h="In the Gordok Commons, King Gordok rules the Gordunni’s northern stronghold in Dire Maul.",sec={{t="Seat of the Ogre King",b="The Gordok Commons fill an old aristocratic wing of Eldre'Thalas. The ogres have remade its night elven pillars and arched passages for their own needs. Armories, crude barricades, and training grounds crowd the halls. Here the Gordok train, the fiercest and most disciplined fighters in the Gordunni clan. At the far end, King Gordok holds court at Gordok's Seat and rules through force and fear.",sp=0},{t="Law of Succession",b="Among the Gordunni, might decides who rules. By clan tradition, whoever slays the sitting monarch takes the title of King Gordok and wins the obedience of the surviving captains and guards. A challenger may slip past the king's lieutenants through stealth or guile. If the challenger kills only the king, the guards accept the victor's authority and bring lavish tributes instead of avenging their former ruler.",sp=0}},faq={{q="Where is the Gordok Commons located?",a="The Gordok Commons fill Dire Maul's northern quarter in Feralas. Enter the ruin through the Broken Commons, then follow the massive stone corridors to the northern entrance.",al={"gordok commons location","where is dire maul north","how to find gordok commons"}},{q="Who are the Gordok ogres?",a="The Gordok are the elite warrior caste of the Gordunni ogre clan. Their kin roam the Feralas wilderness in scattered, feral bands, while the Gordok in the Commons are organized, heavily armed, and obey a strict chain of command under their king.",al={"who are the gordok","gordok clan","gordunni elite"}},{q="How does ogre leadership work in the Commons?",a="Combat decides who rules the Gordok. Whoever kills the reigning King Gordok claims the crown, and the remaining ogres submit to their new sovereign.",al={"how to become king of gordok","gordok succession","king gordok lore"}},{q="Why do adventurers leave the ogre guards alive?",a="When an intruder defeats King Gordok and leaves his lieutenants alive, the commanders submit to the new king. The garrison brings valuable tribute to whoever claims the throne directly.",al={"why tribute run","sparing the guards","gordok tribute lore"}}},ang={["profession:Engineering"]="As an engineer, you can help Knot Thimblejack, the goblin prisoner, scavenge supplies, mend broken traps, and devise clever distractions against the ogre guards."},kw={"dire maul north","eldre'thalas","gordok","gordok commons","king gordok","knot thimblejack","mizzle","tribute run"},rel={"subzone:dire-maul","zone:feralas","subzone:eldreth-row","subzone:maul-subzone","topic:goblin"},src={"Gordok Commons"},nf=true}
E["subzone:gordunni-outpost"] = {t="subzone",n="Gordunni Outpost",z="feralas",s="North of Lariss Pavilion, the Gordunni ogres hold a fortified camp in the cliffs. Their presence leaves the surrounding wilderness dry and withered.",h="North of Lariss Pavilion, the Gordunni ogres hold a fortified camp in the cliffs.",sec={{t="A Blighted Foothold",b="Above Lariss Pavilion, Gordunni ogres patrol trails cut into Feralas's northern mountains. Their magic and destructive ways drain life from the wild. Plants die, and the hillsides lie bare.\n\nDirt paths lead to a shallow cave entrance and a larger mound burrowed into the rear cliffs. Hillguards, channelers, and tamers guard the camp. Near the deeper den, they keep Bigfist, a captured sasquatch, in crude confinement.",sp=0}},faq={{q="Why is the landscape withered around this outpost?",a="The Gordunni clan's sorcery and destructive occupation drain life from the surrounding soil. Jungle plants wither, and the ground turns dry and brown.",al={"why is it brown","dead grass feralas","ogre corruption"}},{q="What kinds of ogres occupy the Gordunni Outpost?",a="Gordunni Hillguards defend the outpost, Gordunni Channelers wield crude offensive magic, and Gordunni Tamers watch over the camp and its captive beasts.",al={"what mobs are here","gordunni types","who lives here"}},{q="Who is Bigfist?",a="Bigfist is a massive sasquatch held captive by the Gordunni ogres near the entrance to their rear cave. The tamers keep him bound as a trophy or for experiments.",al={"caged sasquatch","who is bigfist","ogre prisoner"}},{q="Where is the Gordunni Outpost located?",a="The Gordunni Outpost sits high in the mountain ridge north of Lariss Pavilion in eastern Feralas.",al={"where is gordunni outpost","outpost location","how to get to gordunni outpost"}}},ang={["class:Druid"]="As a druid, you see the Gordunni's presence harm nature. The fertile jungle canopy lies withered and barren.",["class:Hunter"]="As a hunter, you see ogre tamers capture and abuse mountain beasts. They keep creatures such as the great sasquatch Bigfist bound in cages."},kw={"bigfist","channeler","feralas","gordunni","hillguard","lariss pavilion","ogre","outpost","tamer"},rel={"zone:feralas","subzone:lariss-pavilion"},src={"Gordunni Outpost"}}
E["subzone:grimtotem-compound"] = {t="subzone",n="Grimtotem Compound",z="feralas",s="In central Feralas, the Grimtotem keep two encampments east of Dire Maul. Their compound is a base for mysterious, destructive operations in the region.",h="In central Feralas, the Grimtotem keep two encampments east of Dire Maul.",sec={{t="A Bastion of the Black Tribe",b="East of Dire Maul, two Grimtotem encampments give the clan a foothold in Feralas. Unlike the tauren who follow Cairne Bloodhoof in Thunder Bluff, they act alone and meet outsiders with hostility.\n\nIn the southern half, captive native sprite darters are held in a large wooden cage for reasons of their own. Rogue gnolls stalk the northern perimeter.",sp=0}},faq={{q="Who lives in the Grimtotem Compound?",a="The Grimtotem clan lives in the compound. These secretive, aggressive tauren act apart from the Horde-allied tribes in Mulgore and are known for their hostility to outsiders and ruthless methods.",al={"who is here","grimtotem compound mobs","who controls grimtotem compound"}},{q="Why are sprite darters caged in the compound?",a="The Grimtotem have captured native sprite darters and locked them in a large cage in the southern village. Why they hold the creatures is not known.",al={"why are faerie dragons caged","caged sprite darters","grimtotem sprite darters"}},{q="Where is the Grimtotem Compound located?",a="The compound lies in central Feralas, just east of the ancient Highborne ruins of Dire Maul. Wild gnoll packs camp nearby to the northeast.",al={"grimtotem compound location","where is grimtotem compound"}}},ang={["race:Tauren"]="As a tauren, you may know the Grimtotem pay nominal homage to Cairne Bloodhoof. Their compound shows their untamed ambition, far from Thunder Bluff's watchful eyes.",["faction:Alliance"]="As an Alliance member, you face Grimtotem who are relentlessly hostile to the Night Elves and their allies."},kw={"compound","dire maul","feralas","gnolls","grimtotem","sprite darter","tauren"},rel={"zone:feralas","subzone:dire-maul","npc:sprite-darter","topic:tauren","topic:gnoll"},src={"Grimtotem Compound"}}
E["subzone:high-wilderness"] = {t="subzone",n="High Wilderness",z="feralas",s="In western Feralas, the High Wilderness runs from the Verdantis River to the Forgotten Coast. Its towering trees shelter wildlife, wandering treants, and dangerous beasts.",h="In western Feralas, the High Wilderness runs from the Verdantis River to the Forgotten Coast.",sec={{t="The Primordial Canopy",b="The High Wilderness spreads across western Feralas beneath trees so vast and foliage so thick that little sky shows through. Wolves, bears, hippogryphs, and yetis roam below. Ancient treants wander among the roots, while aggressive ogre clans hold shaded clearings. Brush hides predators and hazards from an earlier age, so travelers must stay alert.",sp=0}},faq={{q="Where is the High Wilderness located?",a="The High Wilderness covers the forestlands of western Feralas, west of the Verdantis River. It reaches the cliffs and shores along the Forgotten Coast.",al={"high wilderness location","where is high wilderness","high wilderness feralas"}},{q="What creatures roam the High Wilderness?",a="Bears, wolves, hippogryphs, and feral yetis roam the forest. Wandering treants and aggressive ogres also dwell beneath the canopy.",al={"high wilderness wildlife","creatures in high wilderness","beasts feralas"}}},ang={["class:Druid"]="The ancient treants and vibrant wildlife of the High Wilderness reveal Kalimdor's primal strength, untouched by civilization in the eastern lands.",["class:Hunter"]="Fierce bears, wolves, and wild hippogryphs fill the High Wilderness, where you can track and tame formidable beasts."},kw={"feralas","forgotten coast","high wilderness","hippogryphs","treants","verdantis river","yetis"},rel={"zone:feralas","subzone:forgotten-coast"},src={"High Wilderness"}}
E["subzone:isle-of-dread"] = {t="subzone",n="Isle of Dread",z="feralas",s="South of Sardor Isle, sheer cliffs guard the Isle of Dread off Feralas’s southwestern coast. Chimaeroks roam its highlands, while naga hide in sea caves.",h="South of Sardor Isle, sheer cliffs guard the Isle of Dread off Feralas’s southwestern coast.",sec={{t="A Land of Monsters and Tides",b="A narrow path on the southeastern shore leads you into the island’s high valley. Two-headed chimaeroks roam this enclosed highland, strengthened by arcane energies. Lord Lakmaeran leads the beasts. Anyone crossing from Sardor Isle faces danger here.",sp=0},{t="The Northern Caverns",b="Hatecrest naga occupy caves along the island’s northern shore. Lord Shalzaru leads them as they plot against the night elven sentinels at nearby Feathermoon Stronghold. Submerged passages wind through the deep chambers to secluded grottoes. Their fortified lair stays beyond mainland scrutiny.",sp=0}},faq={{q="How do you reach the interior of the Isle of Dread?",a="Sheer cliffs block the way up from nearly every shore. A natural path on the southeastern side leads on foot to the central plateau.",al={"isle of dread entrance","how to get up isle of dread","climb isle of dread"}},{q="What kinds of creatures inhabit the island?",a="Fierce chimaeroks roam the high plateau, including arcane chimaeroks and massive devourers led by Lord Lakmaeran. Hostile Hatecrest naga occupy deep sea caves along the northern coast.",al={"isle of dread mobs","monsters on isle of dread","chimaeroks feralas"}},{q="Who leads the naga in the sea caves?",a="Lord Shalzaru leads the naga in the northern caves. Their presence threatens the nearby night elves at Feathermoon Stronghold.",al={"isle of dread naga boss","lord shalzaru cave","naga leader feralas island"}},{q="What makes chimaerok meat so famous?",a="Chimaeroks yield rich, tender meat prized by master gourmands. Dirge Quikcleave seeks meat from the island, including Lord Lakmaeran’s carcass, to craft legendary feasts.",al={"chimaerok tenderloin","dirge kickin chimaerok chops","isle of dread food"}}},ang={["profession:Cooking"]="The Isle of Dread’s chimaeroks are the only known source of Chimaerok Tenderloin, the key ingredient in Dirge Quikcleave’s legendary Chimaerok Chops.",["faction:Alliance"]="Night elven sentinels at nearby Feathermoon Stronghold watch the isle. They seek brave champions to strike at Lord Shalzaru and halt the naga presence off their shores."},kw={"chimaerok","feathermoon","feralas","isle of dread","lakmaeran","naga","sardor isle","shalzaru","szallah"},rel={"zone:feralas","subzone:sardor-isle","subzone:feathermoon-stronghold-classic","npc:lord-shalzaru","topic:naga"},src={"Isle of Dread"}}
E["subzone:lariss-pavilion"] = {t="subzone",n="Lariss Pavilion",z="feralas",s="At Lariss Pavilion, dryads attack those who draw near. The ancient retreat north of Camp Mojache now shelters an exiled Highborne mage.",h="At Lariss Pavilion, dryads attack those who draw near.",sec={{t="A Ruin of the Highborne",b="You stand on the bluffs north of Camp Mojache, where graceful stonework and towering arches overlook Feralas's dense canopy. The kaldorei empire built Lariss Pavilion to serve Eldre'Thalas, the great city now called Dire Maul. Yet the glades around it offer no safe refuge. Dryads once wandered here gently, but madness and corruption have taken hold. Now they attack anyone who draws near.",sp=0},{t="Azj'Tordin and the Hidden Passage",b="Azj'Tordin, an elusive elf, has made his home at Lariss Pavilion. He broke from Prince Tortheldrin's decadent rule in Dire Maul and escaped through a secret passage linking the pavilion to the ancient city's underbelly. But his quiet exile was disturbed by Pusillin, an erratic imp who stole his treasured book of incantations. Now the Highborne seeks outside aid to recover it.",sp=0}},faq={{q="Where is Lariss Pavilion located?",a="Lariss Pavilion rises above the forest in eastern Feralas, just north of Camp Mojache, the Horde outpost.",al={"lariss pavilion location","where is lariss pavilion","how to get to lariss pavilion"}},{q="Who is Azj'Tordin?",a="Azj'Tordin is an ancient Highborne sorcerer who fled Prince Tortheldrin's tyrannical rule in Dire Maul. He now camps at the pavilion and seeks help reclaiming his stolen book of incantations from an imp.",al={"azjtordin","who is the elf at lariss pavilion","lariss pavilion quest giver"}},{q="Why are the dryads around the pavilion hostile?",a="Corruption spreading through Feralas has overcome the dryads near the pavilion. These normally reclusive guardians of nature have become vicious attackers.",al={"angry dryads","why are dryads attacking","corrupted dryads feralas"}},{q="How does the pavilion connect to Dire Maul?",a="A concealed passage at the base of Lariss Pavilion leads into Dire Maul. Azj'Tordin used it to escape his brethren.",al={"dire maul backdoor","dire maul shortcut","secret passage"}}},ang={["class:Mage"]="As a mage, you can see in Azj'Tordin, the solitary Highborne, a living relic of Eldre'Thalas's ancient, unchecked spellcraft.",["race:NightElf"]="As a night elf, Lariss Pavilion may be a bitter sight. Highborne hubris shadows its beauty, and corruption afflicts the dryads who are your kin."},kw={"azj'tordin","camp mojache","dire maul","dryads","feralas","highborne","lariss pavilion","pusillin","xerash fireblade"},rel={"subzone:dire-maul","zone:feralas","subzone:camp-mojache","topic:highborne","topic:night-elf"},src={"Lariss Pavilion"}}
E["subzone:lower-wilds"] = {t="subzone",n="Lower Wilds",z="feralas",s="In eastern Feralas, the road runs west from Thalanaar toward the settlements beyond. Humid forest gives way to the dry canyons of Thousand Needles.",h="In eastern Feralas, the road runs west from Thalanaar toward the settlements beyond.",sec={{t="The Eastern Frontier",b="At Thalanaar, night elves guard the mountain pass where the road enters Feralas from Thousand Needles. You travel west beneath dense canopies, with ancient treants and native wildlife in the woods around you. Leave the road, and the forest grows perilous.",sp=0},{t="A Contested Highway",b="Travelers, scouts, and couriers use the Lower Wilds road between southern wilderness and eastern territories. Night elves hold Thalanaar at the gateway, while the Horde keeps Camp Mojache further inland. The road carries supplies across southern Kalimdor, though woodland dangers and faction tensions make the journey fraught.",sp=0}},faq={{q="Where are the Lower Wilds located?",a="The Lower Wilds stretch across eastern Feralas beside Thousand Needles. From Thalanaar at the mountain pass, the road runs west into the jungle.",al={"lower wilds location","where is lower wilds","how to get to lower wilds"}},{q="What creatures live in the Lower Wilds?",a="Ancient treants and native predatory beasts live among the woods and across the forest floor of the Lower Wilds.",al={"lower wilds mobs","what is in lower wilds","lower wilds enemies"}},{q="Which settlements are close to the Lower Wilds?",a="Thalanaar sits at the far eastern border, and Camp Mojache lies further west along the road.",al={"lower wilds towns","camps near lower wilds","horde alliance towns lower wilds"}},{q="Is the road through the Lower Wilds safe?",a="The road is the safest route through the Lower Wilds, but stay alert. Forest beasts, territorial guardians, and faction skirmishes threaten travelers.",al={"is lower wilds safe","lower wilds road safety"}}},ang={["faction:Alliance"]="As an Alliance traveler leaving Thousand Needles, you enter Feralas through the Lower Wilds, with Thalanaar at the frontier.",["faction:Horde"]="As a Horde messenger or supplier bound for Camp Mojache, you travel the length of the Lower Wilds after descending from the border canyons."},kw={"camp mojache","eastern feralas","feralas","lower wilds","thalanaar","thousand needles","treants"},rel={"zone:feralas","subzone:thalanaar","zone:thousandneedles","subzone:camp-mojache"},src={"Lower Wilds"}}
E["subzone:maul-subzone"] = {t="subzone",n="The Maul",z="feralas",s="In Maul, fighters face beasts and rivals in the sunken pit beyond Dire Maul. The Broken Commons ring once belonged to Eldre'Thalas, but no faction now keeps order on its floor.",h="In Maul, fighters face beasts and rivals in the sunken pit beyond Dire Maul.",sec={{t="The Sunken Pit",b="Deep in the Broken Commons, Maul’s stone pit once hosted the Highborne of Eldre'Thalas for theater or ceremony. After the Sundering, Gordok ogres took the ruins, and the pit became a raw colosseum. Like the Gurubashi Arena in distant Stranglethorn Vale, its sands erase allegiance. Fighters from opposing factions meet freely, and survival belongs to the strong.",sp=0},{t="Beasts and Bloodshed",b="Take care on the way down. Daring fighters sometimes leap from the Broken Commons’ high ledges, but the fall hits hard. A western archway leads down more safely through tunnels where Gordok hyenas sleep. It is the only way out on foot. Dangerous beasts and notorious gladiators enter at irregular times, so each descent brings an uncertain fight.",sp=0}},faq={{q="Why can I attack members of my own faction here?",a="Maul is a lawless fighting pit, much like the Gurubashi Arena in Stranglethorn Vale. Faction treaties and truces do not hold on its sands, and combatants may fight anyone outside their party.",al={"ffa pvp dire maul","free for all arena","why can i hit horde"}},{q="How do I safely enter and leave the Maul?",a="A leap from the Broken Commons can cause serious falling damage. Take the safer way through the western doorway and past sleeping Gordok hyenas. It is also the only route back out on foot.",al={"how to get into the maul","maul entrance","exit maul"}},{q="What kinds of enemies appear in the arena?",a="Rival adventurers meet dangerous beasts and gladiators in the pit. Among them are the fungal giant Mushgog, the chimera The Razza, and Skarr the Unbreakable.",al={"arena rares","who spawns in the maul","maul bosses"}},{q="What was this arena originally used for?",a="Before the Sundering, the stone colosseum belonged to the Highborne city of Eldre'Thalas. The Gordok ogres later turned the ancient elven structure into a blood arena.",al={"lore of the maul","who built the maul","eldre'thalas arena"}}},ang={["class:Warrior"]="As a warrior, you can test your strength in Maul outside organized battlegrounds. Personal prowess and thick armor decide who survives.",["race:NightElf"]="As a Night Elf, you see ancient Eldre'Thalas’s proud architecture reduced to an ogre-infested execution pit. It recalls the fall of Highborne civilization."},kw={"broken commons","dire maul arena","eldre'thalas","feralas","ffa pvp","mushgog","skarr the unbreakable","the maul","the razza"},rel={"subzone:dire-maul","subzone:commons","zone:feralas","subzone:gurubashi-arena","zone:stranglethorn"},src={"Maul (subzone)"}}
E["subzone:oneiros"] = {t="subzone",n="Oneiros",z="feralas",s="In northern Feralas, green dragonkin guard Oneiros and its ancient night elven ruins. The stones lie south of Jademir Lake, near portals that lead toward Ysera's realm.",h="In northern Feralas, green dragonkin guard Oneiros and its ancient night elven ruins.",sec={{t="Ruins Beneath the Dream",b="In northern Feralas, broken arches and columns mark an ancient Kaldorei settlement. Abandoned millennia ago, its stones are now threaded with roots and overgrowth. Green Dragonflight guardians patrol the shaded paths and ruined plazas, keeping mortals from ancient secrets.",sp=0},{t="Echoes and Corruption",b="Green dragonkin loyal to the Dreamer watch over Oneiros, where a spiritual link to the Emerald Dream makes the region volatile. Beyond the veil, darkness stirs. Powerful dragonspawn see any mortal who enters as a possible threat to the wards holding back corruption.",sp=1}},faq={{q="Where is Oneiros located?",a="Oneiros lies in northern Feralas, directly south of Jademir Lake and north of the forest's main thoroughfares. It lies near the Great Tree that borders the Emerald Dream portal.",al={"oneiros location","where is oneiros","find oneiros"}},{q="What creatures inhabit Oneiros?",a="Powerful green dragonspawn and dragonkin sworn to the Green Dragonflight patrol Oneiros. These elite guardians are formidable, so travelers should approach with caution.",al={"oneiros mobs","enemies in oneiros","who lives in oneiros"}},{q="Why are there night elf ruins here?",a="Oneiros was an ancient night elven settlement from before the Great Sundering. Its civilization crumbled over ten thousand years ago, leaving stone colonnades and courtyards for nature to reclaim.",al={"why are there ruins","kaldorei ruins feralas","oneiros history"}},{q="What is the connection between Oneiros and the Emerald Dream?",a="Oneiros lies near great boughs connecting Kalimdor to the Dream realm, where the boundaries between the physical and spirit worlds blur.",al={"oneiros emerald dream","dream connection feralas"}},{q="Is there a safe place to rest nearby?",a="There is no safe place to rest within the ruins, which belong to green dragonkin. Alliance travelers can retreat to Feathermoon Stronghold off the western coast, while the Horde can shelter at Camp Mojache in eastern Feralas.",al={"safe camp near oneiros","dreamers rest feralas","friendly hub oneiros"}}},ang={["class:Druid"]="As a druid, you may feel reverence and concern for Oneiros, whose ethereal link reaches Ysera's domain and whose dangers include lingering Nightmare corruption.",["race:NightElf"]="As a Night Elf, you can see in Oneiros a solemn reminder of your ancient empire's reach and the green dragonkin's vigilant guardianship."},kw={"dragonspawn","feralas","green dragonflight","jademir lake","oneiros"},rel={"zone:feralas","topic:emerald-dream","topic:night-elf"},src={"Oneiros"}}
E["subzone:rage-scar-hold"] = {t="subzone",n="Rage Scar Hold",z="feralas",s="At Rage Scar Hold, savage yetis guard their cavern in Feralas, not far from Feathermoon Stronghold. Deeper inside, books, symbols, and night elven stonework point to an older purpose.",h="At Rage Scar Hold, savage yetis guard their cavern in Feralas, not far from Feathermoon Stronghold.",sec={{t="A Beastly Domain",b="Savage yetis attack anyone who comes near Rage Scar Hold. Alliance sentinels and travelers face danger on the forest trails because of them. Yetis roam Kalimdor’s wild reaches, but these beasts are especially aggressive. They fiercely defend their lair.",sp=0},{t="Traces of the Past",b="Deeper in the cave, carved stonework and night elven architecture mark an older presence. Forgotten tomes and mystic symbols lie among dirt and bone. Did the yetis kill scholars here, or does lingering magic draw the beasts?",sp=0}},faq={{q="What is Rage Scar Hold?",a="Rage Scar Hold is a cave network in Feralas on the mainland, not far from Feathermoon Stronghold. Feral yetis now overrun its halls.",al={"rage scar hold","what is this cave","feralas yeti cave"}},{q="Why are there books and symbols inside a yeti den?",a="Abandoned tomes, scrolls, and arcane symbols remain inside the hold. They suggest spellcasters or night elf scholars once lived there and fell victim to the yetis.",al={"why books in yeti cave","are yetis studying magic","rage scar hold books"}},{q="Was this cavern built by night elves?",a="Night elven stonework and structures like those of a barrow den fill the cavern. No living kaldorei remain inside, so its first occupants either left long ago or died when the yetis moved in.",al={"night elf architecture","was rage scar hold an elf barrow","barrow den feralas"}},{q="Are the yetis here different from others in Kalimdor?",a="Travelers regard the yetis of Rage Scar Hold as among the fiercest in Feralas. They defend their stolen underground home with feral brutality.",al={"feralas yetis","how dangerous are the yetis","rage scar beasts"}}},ang={["race:NightElf"]="As a night elf, seeing filthy yetis defile what seems to be an ancient barrow den or sanctuary is a bitter reminder of wild perils reclaiming kaldorei lands.",["class:Mage"]="As a mage, arcane symbols and abandoned tomes in a beast’s den raise troubling questions about who died in the cavern’s depths."},kw={"barrow den","feathermoon","feralas","magic books","rage scar hold","yeti"},rel={"zone:feralas","subzone:feathermoon-stronghold-classic","topic:night-elf"},src={"Rage Scar Hold"}}
E["subzone:ruins-of-isildien"] = {t="subzone",n="Ruins of Isildien",z="feralas",s="In southwestern Feralas, Gordunni ogres hold the overgrown Ruins of Isildien. The ancient night elven city fell during the Great Sundering ten thousand years ago.",h="In southwestern Feralas, Gordunni ogres hold the overgrown Ruins of Isildien.",sec={{t="A Fallen City of the Kaldorei",b="Isildien once rose as a grand night elven settlement, before the world shattered. Marble arches and terraces showed the reach of kaldorei civilization and their devotion. Then the Well of Eternity imploded and tore the continents apart, leaving the city in ruins. Jungle growth covered its stones over the millennia.\n\nA colossal dome crowns the upper terrace. It recalls Darnassus's Temple of the Moon and suggests Isildien held an important sanctuary dedicated to Elune.",sp=0},{t="The Gordunni Stronghold",b="The Gordunni ogres have made Isildien's terraces and outcroppings one of their chief settlements in Feralas. They brace the crumbling walkways with bonfires, barricades, and war banners, defiling the ancient plazas. The ogres fiercely defend their stolen home from outsiders who venture too near the southern hills.",sp=0}},faq={{q="What was Isildien originally?",a="Isildien was a major night elven city built before the Great Sundering, ten thousand years ago. The cataclysm left its stone plazas, terraces, and temples in ruins.",al={"what is isildien","isildien history","who built isildien"}},{q="Who controls the Ruins of Isildien now?",a="The Gordunni ogres have seized and fortified the ruins. They use the broken marble halls and natural vantage points as a stronghold in southern Feralas.",al={"who lives in isildien","isildien enemies","ogres in isildien"}},{q="What is the large circular pavilion at the top of the stairs?",a="The circular pavilion recalls the Temple of the Moon in Darnassus. It suggests the upper dais once held a sanctuary dedicated to Elune.",al={"isildien temple","round building in isildien","temple of elune feralas"}},{q="Is there anything hidden inside the ruins?",a="A cave lies in the eastern cliffs along the ruins. The ogres use it alongside the scattered stone terraces across the northern and southern grounds.",al={"isildien cave","secrets in isildien"}}},ang={["race:NightElf"]="Walking through Isildien recalls the height of your pre-Sundering empire, now ruined and desecrated by Gordunni ogres.",["class:Priest"]="The great rotunda at the summit echoes Elune's high sanctuaries. Prayers to the White Lady were offered there ten thousand years ago."},kw={"elune","feralas","gordunni","isildien","kaldorei","ogres","sundering","temple of the moon"},rel={"zone:feralas","subzone:temple-of-the-moon","zone:darnassus","topic:elune"},src={"Ruins of Isildien"}}
E["subzone:ruins-of-ravenwind"] = {t="subzone",n="Ruins of Ravenwind",z="feralas",s="In northern Feralas, harpies nest among the Ruins of Ravenwind as dragonkin watch the broken stone. The marble once belonged to an ancient Highborne city.",h="In northern Feralas, harpies nest among the Ruins of Ravenwind as dragonkin watch the broken stone.",sec={{t="Echoes of the Highborne",b="Before the Great Sundering, the Highborne ruled from Ravenwind at the height of their power. Like Dire Maul to the east, the kaldorei city was abandoned long ago.\n\nNow foliage winds through broken arches and forgotten arcane altars. Northspring harpies roost there and prey on anything that wanders beneath the stone.",sp=0},{t="A Confluence of Wild Dangers",b="Northspring harpies are not the only danger near Ravenwind. Fierce green dragonkin called the Jaedemir circle the central groves and waterways, guarding ancient arboreal sites.\n\nNight elf explorers and solitary gnolls sometimes wander nearby. Lingering magic and wild predators can trap them among the ruins.",sp=0}},faq={{q="Who built the Ruins of Ravenwind?",a="The Highborne, the aristocratic upper class of the ancient kaldorei, built Ravenwind millennia ago. After the Sundering, it fell into ruin, like Dire Maul and other elven monuments across Feralas.",al={"who built ravenwind","ravenwind history","ruins of ravenwind origins"}},{q="What currently infests the ruins?",a="Northspring harpies nest among the broken stonework, while dragonkin of the Jaedemir flight prowl the surrounding waters and central grove. They fiercely guard the local flora.",al={"ravenwind monsters","what lives in ravenwind","ravenwind harpies"}},{q="Why does the Alliance visit this area?",a="Alliance scholars and sentinels at Feathermoon Stronghold send adventurers to seek lost arcane relics. They also use ancient altars to recharge powerful artifacts such as the Stave of Equinex.",al={"alliance ravenwind quest","feathermoon ravenwind"}}},ang={["race:NightElf"]="For the kaldorei, these ruins recall the reckless arcane empire that tore ancient Kalimdor apart. Harpies and wild beasts now foul the site.",["faction:Alliance"]="From Feathermoon Stronghold, Alliance outposts keep watch on Ravenwind. Scouts seek potent magical relics before feral creatures or darker powers consume them."},kw={"feathermoon","feralas","harpies","highborne","jaedemir","northspring","ravenwind"},rel={"zone:feralas","subzone:dire-maul","subzone:feathermoon-stronghold-classic","topic:highborne","topic:night-elf","topic:alliance","topic:gnoll"},src={"Ruins of Ravenwind"}}
E["subzone:sardor-isle"] = {t="subzone",n="Sardor Isle",z="feralas",s="At feathermoon stronghold, night elves hold Sardor Isle against beasts and naga along its wild shores. The island guards Feralas's western coast, north of the Isle of Dread.",h="At feathermoon stronghold, night elves hold Sardor Isle against beasts and naga along its wild shores.",sec={{t="Sentinel Bastion and Wild Shores",b="Across the water from mainland Feralas, Sardor Isle is held by feathermoon stronghold, an elven garrison commanded by General Shandris Feathermoon. The fortress is heavily fortified, and a regular ferry links it to the mainland.\n\nBeyond its walls, the island remains wild. Wolf packs roam the timbered slopes, while naga lurk along the rocky western and northern beaches, testing the night elven sentinels.",sp=0}},faq={{q="Where is Sardor Isle located?",a="Sardor Isle lies off Feralas's western coast in southern Kalimdor, just north of the Isle of Dread. A ferry runs from the Forgotten Coast on the mainland.",al={"sardor isle location","where is sardor","find sardor isle"}},{q="What is the main settlement on Sardor Isle?",a="Feathermoon Stronghold is Sardor Isle's main settlement, a night elven fortress and staging ground for the Alliance in Feralas. General Shandris Feathermoon commands it.",al={"who lives on sardor isle","sardor isle town","night elf base sardor"}},{q="What threats are found on the island outside the stronghold?",a="Beyond Feathermoon Stronghold's walls, wild wolves prowl the woods and hostile naga lurk around coastal reefs and beaches.",al={"sardor isle enemies","danger on sardor isle","monsters sardor"}},{q="How does Sardor Isle differ from the Isle of Dread?",a="Sardor Isle lies north of the Isle of Dread, held by the night elves of Feathermoon Stronghold. Farther south, the Isle of Dread is harsher and untamed, with dangerous chimaeras and naga.",al={"sardor isle vs isle of dread","difference from isle of dread"}}},ang={["faction:Alliance"]="For the Alliance, Sardor Isle is its main foothold in Feralas. Feathermoon Stronghold offers safe harbor, supplies, and flight masters.",["race:NightElf"]="As a night elf, you know the Sentinels under General Shandris Feathermoon watch the ancient ruins and rising naga threats throughout Feralas."},kw={"feathermoon stronghold","feralas","isle of dread","naga","sardor isle","sentinels","shandris feathermoon"},rel={"subzone:feathermoon-stronghold-classic","zone:feralas","npc:shandris-feathermoon","subzone:isle-of-dread","topic:naga"},src={"Sardor Isle"}}
E["subzone:shalzaru-s-lair"] = {t="subzone",n="Shalzaru's Lair",z="feralas",s="Hatecrest naga gather at Shalzaru's Lair on the Isle of Dread's northern tip. Their master directs them from flooded caverns south of Feathermoon Stronghold.",h="Hatecrest naga gather at Shalzaru's Lair on the Isle of Dread's northern tip.",sec={{t="A Serpent Den in the Shallows",b="At the Isle of Dread's northern end, the bluffs open into Shalzaru's Lair. A broad cavern and a smaller chamber join through submerged waterways. Hatecrest serpent guards patrol the dry paths, while sorceresses weave magic across the water. Deep within, Lord Shalzaru commands the Hatecrest brood across the island. The lair lies close to Sardor Isle, across the channel from the night elf Sentinels at Feathermoon Stronghold.",sp=0}},faq={{q="Where is Shalzaru's Lair located?",a="Shalzaru's Lair lies at the Isle of Dread's northern end, directly south of Sardor Isle and Feathermoon Stronghold off Feralas's western coast.",al={"where is shalzaru's lair","shalzaru lair location","how to find shalzaru lair"}},{q="Who is Shalzaru?",a="Shalzaru is a powerful naga warlord and master of the Hatecrest tribe on the Isle of Dread. He commands his forces from the lair's flooded caverns.",al={"who is shalzaru","shalzaru lore","boss of shalzaru lair"}},{q="What creatures inhabit this cave?",a="Hatecrest naga inhabit the cavern. Serpent guards watch the dry paths, and sorceresses weave magic across the underground waters.",al={"what enemies are in shalzaru lair","hatecrest naga cave mobs"}},{q="Why is this lair important to the local night elves?",a="The Isle of Dread lies across the water from Feathermoon Stronghold. The naga gathered in Shalzaru's Lair threaten Shandris Feathermoon's forces and Sardor Isle's security.",al={"why do night elves care about shalzaru","feathermoon naga threat"}}},ang={["faction:Alliance"]="The Hatecrest gathering in this cavern threatens Feathermoon Stronghold's supply lines and peace. Clearing Shalzaru and his brood is a priority for the Sentinels and their allies.",["race:NightElf"]="As a night elf, you see naga defiling Feralas's ancient coastal ruins. Their presence recalls the Sundering and the Highborne's fall into monstrous corruption."},kw={"feathermoon stronghold","feralas","hatecrest","isle of dread","naga cave","shalzaru","shalzaru's lair"},rel={"subzone:isle-of-dread","topic:naga","subzone:feathermoon-stronghold-classic","zone:feralas"},src={"Shalzaru's Lair"}}
E["subzone:thalanaar"] = {t="subzone",n="Thalanaar",z="feralas",s="At Feralas's eastern edge, Thalanaar shelters Alliance travelers and watches the road from Thousand Needles. Its hippogryph roost links the mainland with Feathermoon Stronghold.",h="At Feralas's eastern edge, Thalanaar shelters Alliance travelers and watches the road from Thousand Needles.",sec={{t="Gateway to the Forgotten Wilderness",b="From the east, Thalanaar is the first night elf outpost you meet at Feralas's edge. Here, Thousand Needles' sandstone gives way to forest canopy, with sturdy pavilions and sentinels on watch. Alliance scouts, couriers, and craftsmen find shelter before entering the forest. Beasts, ogres, and Horde forces roam southern Kalimdor, so the outpost is a refuge and a place to gather before venturing in.",sp=0},{t="A Vital Aerial Link",b="Thalanaar's hippogryph master connects Feralas with Theramore Isle in Dustwallow Marsh, Gadgetzan in Tanaris, and Feathermoon Stronghold to the west. These routes cross a region where overland travel is perilous, linking the wilderness to destinations across southern Kalimdor. Craftsmen also come here to seek master leatherworkers, who teach the ancient art of working wild hides beneath the woodland boughs.",sp=0}},faq={{q="What is Thalanaar?",a="At Feralas's eastern entrance beside Thousand Needles, Thalanaar shelters Alliance travelers. The outpost offers basic supplies and flight transport.",al={"thalanaar overview","what is this place","thalanaar camp"}},{q="Where can the flight master send me?",a="Thalanaar's hippogryph roost connects Feralas with Feathermoon Stronghold off its western coast, Theramore Isle in Dustwallow Marsh, and Gadgetzan in Tanaris.",al={"thalanaar flight paths","where can i fly","flight master thalanaar"}},{q="Why would crafters seek out Thalanaar?",a="Caryssia Moonhunter teaches Tribal Leatherworking at Thalanaar to skilled artisans from across Kalimdor.",al={"thalanaar trainers","leatherworking thalanaar","caryssia moonhunter"}},{q="Is Thalanaar safe for Horde adventurers?",a="No. Night elf sentinels guard Thalanaar as an Alliance settlement and attack Horde members on sight.",al={"is thalanaar horde friendly","horde in thalanaar"}}},ang={["faction:Alliance"]="As an Alliance traveler, you find your first safe haven and a reliable flight hub at Thalanaar. It lies west of the treacherous mesas of Thousand Needles, at Feralas's edge.",["race:NightElf"]="As a night elf, you find Thalanaar watching the border and welcoming kin back into Feralas's ancestral shadows beneath its ancient canopy."},kw={"caryssia moonhunter","feathermoon","feralas","flight master","sentinels","thalanaar","thousand needles","tribal leatherworking"},rel={"zone:feralas","zone:thousandneedles","subzone:feathermoon-stronghold-classic","subzone:theramore-isle","subzone:gadgetzan","topic:night-elf","topic:alliance"},src={"Thalanaar"}}
E["subzone:twin-colossals"] = {t="subzone",n="Twin Colossals",z="feralas",s="The Twin Colossals rise above northwestern Feralas, marking the way north into Desolace.",h="The Twin Colossals rise above northwestern Feralas, marking the way north into Desolace.",sec={{t="Pillars of the Rainforest",b="In western Feralas, the Twin Colossals rise above the forest. Travelers coming south from Desolace know these great cliffs at once. Their lower slopes meet the jungle and the lands near the Forgotten Coast, while their summits stand apart above the forest floor.",sp=0},{t="Reaching the Heights",b="No footpath climbs the sheer cliffs, but Marli Wishrunner helps travelers reach the eastern peak. A quiet pond rests atop the mesa, home to Diamond Head, an unusually large makrura. Kalin Windflight offers sturdy parachutes for the descent into the jungle canopy.",sp=0}},faq={{q="Where are the Twin Colossals located?",a="The Twin Colossals rise in northwestern Feralas, beside the main road north into Desolace. The surrounding subzone reaches west toward the Forgotten Coast.",al={"twin colossals location","where are twin colossals","twin colossi map"}},{q="How do you reach the top of the Twin Colossals?",a="The sheer cliffs cannot be climbed on foot. Marli Wishrunner helps travelers reach the eastern peak.",al={"how to climb twin colossals","get to top of twin colossi","to the top quest"}},{q="Who lives on the eastern summit?",a="Kalin Windflight sells parachutes on the eastern peak, where a deep pond is home to Diamond Head, an unusually large makrura.",al={"npc at top of twin colossals","who is on the mesa","diamond head feralas"}},{q="How do you get down safely from the top?",a="Kalin Windflight sells Colossal Parachutes atop the eastern summit. Travelers can leap from the cliffs and glide down into the Feralas jungle.",al={"leaving twin colossals","jump off twin colossals","colossal parachute"}}},ang={["race:NightElf"]="As a night elf, you know these heights and nearby corrupted moonwells recall Feralas's ancient history. Shadows still creep into its wilderness."},kw={"desolace","diamond head","feralas","kalin windflight","makrura","marli wishrunner","twin colossals","twin colossi"},rel={"zone:feralas","zone:desolace","subzone:forgotten-coast","subzone:rage-scar-hold","topic:night-elf","topic:satyr","topic:emerald-dream"},src={"Twin Colossals"}}
E["subzone:warpwood-quarter"] = {t="subzone",n="Warpwood Quarter",z="feralas",s="In Dire Maul, twisted growth and demonic corruption now overrun the Warpwood Quarter. Once its gardens nurtured nature, but frenzied plants and corrupted satyrs have taken the eastern district of Eldre'Thalas.",h="In Dire Maul, twisted growth and demonic corruption now overrun the Warpwood Quarter.",sec={{t="A Garden Corrupted",b="The Warpwood Quarter's grand gardens are now a choking tangle of twisted ancients and lethal lashers. Alzzin the Wildshaper, a satyr, turned dark magic against the ancient Fruit of Fertility. Under his influence, the plants grew grotesque and predatory. Vile Felvine shards now saturate the halls, where demons, rebellious imps and demonic thralls have gathered.",sp=0},{t="Pathways through the Overgrowth",b="Most explorers enter the district through Dire Maul's central Broken Commons. To the east, an overgrown passage runs beneath the Lariss Pavilion, though Alzzin's warped guardians make the way dangerous. The mischievous imp Pusillin brings another peril. His thievery sends pursuers racing toward secluded reaches of the ruins.",sp=0}},faq={{q="What is the Warpwood Quarter?",a="The Warpwood Quarter is Dire Maul's eastern district, within the ancient Highborne city of Eldre'Thalas. Demonic energies have overrun and changed its grand conservatories.",al={"what is warpwood quarter","warpwood district","dire maul east lore"}},{q="Who rules this district?",a="The satyr Alzzin the Wildshaper rules the quarter. He has used fell energies to corrupt the local plants and the legendary Fruit of Fertility, turning the district's plant guardians into vicious warped ancients.",al={"who controls warpwood","alzzin the wildshaper","warpwood boss"}},{q="How do you enter the Warpwood Quarter?",a="You can enter from the Broken Commons inside Dire Maul. A second, secluded passage beneath the Lariss Pavilion in eastern Feralas requires a Crescent Key to unlock.",al={"warpwood entrance","how to get to dire maul east","lariss pavilion entrance"}},{q="Why is the imp Pusillin running through the ruins?",a="Pusillin is a thieving imp who lurks near the quarter's entrance. When trespassers confront him, he taunts them and flees deeper into the ruins, mocking them as he runs toward the Hidden Reach.",al={"pusillin","who is pusillin","imp running dire maul"}}},ang={["class:Druid"]="As a druid, you see the twisted fate of the Warpwood ancients and the Fruit of Fertility's corruption into foul Felvine as affronts to Cenarion teachings. Druids from Moonglade seek to cleanse the quarter.",["race:NightElf"]="As a night elf, you see Eldre'Thalas's majestic conservatories perverted into a satyr den. Their ruin recalls the corruption that brought down the ancient Highborne Empire."},kw={"alzzin the wildshaper","dire maul east","eldre'thalas","felvine","fruit of fertility","lariss pavilion","pusillin","warpwood quarter"},rel={"subzone:dire-maul","zone:feralas","subzone:commons","subzone:lariss-pavilion","subzone:capital-gardens","topic:satyr","quest:5921"},src={"Warpwood Quarter"},nf=true}
E["subzone:woodpaw-den"] = {t="subzone",n="Woodpaw Den",z="feralas",s="Woodpaw gnolls hold their den beneath Feralas’s dense canopy, just north of Darkmist Ruins. Their fiercest alphas guard the pack’s home, and travelers crossing the southern wilderness face their threat.",h="Woodpaw gnolls hold their den beneath Feralas’s dense canopy, just north of Darkmist Ruins.",sec={{t="Heart of the Pack",b="Woodpaw Den is held by the seasoned alphas of the local gnoll pack. Unlike the smaller scout camps along the jungle tracks, this encampment is defended in force. The gnolls fight to keep their territory from intruders and the encroaching wilderness. Just north of the elven remnants at Darkmist Ruins, the den threatens travelers crossing this part of Feralas.",sp=0}},faq={{q="What is Woodpaw Den?",a="Woodpaw Den houses Woodpaw gnolls in southern Feralas, just north of Darkmist Ruins. The pack’s dangerous alphas live there.",al={"woodpaw den feralas","gnoll camp feralas","where is woodpaw den"}},{q="What creatures live here?",a="Woodpaw gnolls live at the den. Their formidable alphas lead and defend the pack against outsiders.",al={"who lives here","woodpaw den mobs","what enemies are in woodpaw den"}},{q="What landmarks are nearby?",a="Darkmist Ruins lie just south of the encampment. Dense rainforests border the den.",al={"landmarks near woodpaw den","what is next to woodpaw den"}}},ang={["race:NightElf"]="As a Kaldorei at Feathermoon Stronghold, you face expanding gnoll packs near ancestral sites like Darkmist Ruins. They call for watchful containment.",["race:Tauren"]="As a huntsman at Camp Mojache, you know the vicious Woodpaw clan competes for game and territory in Feralas’s primeval woods."},kw={"darkmist ruins","feralas","gnoll","woodpaw","woodpaw alpha","woodpaw den"},rel={"topic:gnoll","zone:feralas"},src={"Woodpaw Den"}}
E["subzone:woodpaw-hills"] = {t="subzone",n="Woodpaw Hills",z="feralas",s="In southeastern Feralas, silithid swarms and mountain giants press into Woodpaw Hills. The Woodpaw gnolls have lost ground in their old territory.",h="In southeastern Feralas, silithid swarms and mountain giants press into Woodpaw Hills.",sec={{t="A Beleaguered Stronghold",b="Woodpaw gnolls hold the forests of Woodpaw Hills, though their grip on the slopes has weakened. Silithid swarmers broke through the earth at the Writhing Deep, southeast of the hills, and drove the clan back. Their chieftains have retreated deeper into Woodpaw Den.\n\nMountain giants also roam these woods. They were summoned from the mountains during the Third War to repel the Burning Legion. Now they crush travelers and Horde interlopers who cross their path.",sp=0}},faq={{q="Who lives in the Woodpaw Hills?",a="The Woodpaw clan of gnolls lives in the hills and keeps defensive camps among the woods. Mountain giants patrol the slopes while silithid insects press in from the southeast.",al={"who inhabits woodpaw hills","woodpaw hills enemies","gnolls in feralas"}},{q="Why are mountain giants walking around this forest?",a="Mountain giants came down from the peaks to aid the night elves during the Burning Legion's invasion of Kalimdor in the Third War. The invasion was broken, but the giants remain in the woods, guarding the wild lands against intrusion.",al={"giants in woodpaw hills","why are there giants here","mountain giant lore feralas"}},{q="What is threatening the gnolls here?",a="Silithid swarms are driving the Woodpaw clan from its camps as they carve out hives at the Writhing Deep. The strongest alphas have retreated to Woodpaw Den and fortified their position.",al={"what are the gnolls fighting","woodpaw troubles","bugs attacking gnolls feralas"}},{q="Where are the Woodpaw clan leaders?",a="The Woodpaw Alphas have left the open camps and retreated into the sheltered underground caves of Woodpaw Den as silithid swarms press across the hills.",al={"woodpaw alphas location","gnoll bosses feralas","find woodpaw leader"}}},ang={["faction:Horde"]="As a member of the Horde, you face mountain giants hostile to you in Woodpaw Hills. Neutral cliff giants dwell near the western coast."},kw={"feralas","gnolls","mountain giants","woodpaw","woodpaw den","woodpaw hills","writhing deep"},rel={"zone:feralas","subzone:woodpaw-den","subzone:writhing-deep","topic:gnoll","topic:burning-legion","topic:horde"},src={"Woodpaw Hills"}}
E["subzone:writhing-deep"] = {t="subzone",n="Writhing Deep",z="feralas",s="In southeastern Feralas, the Writhing Deep’s hive keeps growing and threatens nearby wildlife and encampments. Zukk'ash silithid widen their burrow, upsetting the forest’s balance.",h="In southeastern Feralas, the Writhing Deep’s hive keeps growing and threatens nearby wildlife and encampments.",sec={{t="The Zukk'ash Swarm",b="Across southeastern Feralas, the Zukk'ash swarm spreads through the lowlands. Silithid dig winding tunnels and guard their resinous eggs. As the hive grows, wild creatures grow restless and nearby gnoll packs stir. Displaced predators press close to Horde paths and native sanctuaries.",sp=0}},faq={{q="What creatures inhabit the Writhing Deep?",a="Zukk'ash silithid crawl through the Writhing Deep. These giant insects include workers, tunnelers, stingers, and wasps. Dangerous brood champions such as Stinglasher and Qirot lead them.",al={"writhing deep mobs","what lives in writhing deep","silithid in feralas"}},{q="Why is the Writhing Deep a threat to Camp Mojache?",a="As the Zukk'ash swarm spreads, gnolls flee their hunting grounds. Frantic, they move north toward Camp Mojache and threaten the Horde outpost.",al={"camp mojache writhing deep","why attack horde","gnolls feralas"}},{q="Where is the Writhing Deep located?",a="The Writhing Deep lies in southeastern Feralas, south of the main road and east of the towering forested hills.",al={"writhing deep location","where is writhing deep","feralas hive location"}}},ang={["faction:Horde"]="Silithid spreading from the Writhing Deep threaten Camp Mojache. Crazed gnolls and roaming insect scouts press into your supply lines."},kw={"camp mojache","feralas","hive","qirot","silithid","stinglasher","writhing deep","zukk'ash"},rel={"zone:feralas","subzone:camp-mojache","topic:gnoll","topic:horde"},src={"Writhing Deep"}}
E["zone:feralas"] = {t="zone",n="Feralas",z="feralas",s="In Feralas, rainforest endures between Desolace, Thousand Needles, and the Veiled Sea. Mountain walls shelter an ancient wilderness of overgrown Kaldorei ruins and primordial beasts. Highborne remnants, Gordunni ogres, and rival Alliance and Horde outposts contend for its reaches.",h="In Feralas, rainforest endures between Desolace, Thousand Needles, and the Veiled Sea.",sec={{t="A Forest Untouched by the Wastes",b="You enter a rainforest still green while Desolace and Thousand Needles lie dry nearby. Mountain ranges keep the wastes at bay, sheltering ancient growth beneath warm, misty air and towering waterfalls. Much of Kalimdor looked this way before the Great Sundering. Over the ages, jungle growth swallowed the monuments of the Kaldorei who once ruled here, hiding forgotten temples and pavilions beneath moss and ferns.",sp=0},{t="The Ruins of Eldre'Thalas",b="At Feralas's heart, Eldre'Thalas lies in ruins, now called Dire Maul. The Kaldorei built the city at their empire's height, but the Gordunni ogres have defiled its vast stone courtyards. The clan spreads through the valley, pillaging sacred sites, fouling pristine groves, and driving wildlife to defend its territory. Whispers speak of Highborne remnants and powers trapped for ten thousand years in Dire Maul's sealed chambers.",sp=0},{t="The Struggle for Footholds",b="Alliance and Horde expeditions have pushed into the jungle, where every crossing brings danger. At Feathermoon Stronghold on Sardor Isle, General Shandris Feathermoon leads Sentinels against the ogres and advancing naga. Farther east, Camp Mojache anchors the Horde against aggressive Woodpaw gnolls, hostile Grimtotem tauren, and relentless ogres. Neither faction controls Feralas's wild interior.",sp=0}},faq={{q="What is Dire Maul?",a="Dire Maul is the name now given to Eldre'Thalas, a great elven city that survived the Sundering. It declined over the ages and fell to the brutal Gordunni clan. Ogres and treacherous spirits contest its wings, where ancient Highborne secrets remain.",al={"eldre'thalas","ogre city","ancient ruins center"}},{q="How do Alliance travelers safely reach Feathermoon Stronghold?",a="From Desolace, Alliance travelers can pass south through the Twin Colossals, though the beasts there are perilous. Or they can enter the sea at Sar'theris Strand and swim south along the Forgotten Coast to Sardor Isle, bypassing the dangerous road and Camp Mojache.",al={"getting to feathermoon","alliance entrance to feralas","how to get to feralas alliance"}},{q="Why is the Horde fighting the Gordunni ogres so aggressively?",a="The Gordunni ogres push out of Dire Maul, raiding supply caravans and attacking travelers across the jungle. Their war parties threaten Camp Mojache, so Horde leaders such as Belgrom Rockmaul call for swift, aggressive strikes on the clan's outposts.",al={"why kill gordunni","horde ogre war","camp mojache ogres"}},{q="What is the Dream Bough?",a="The Dream Bough is one of Azeroth's four Great Trees. Its mystical natural portal links the physical world to the Emerald Dream. The green dragonflight and ancient guardians watch over it, as they do its counterparts in Ashenvale, Duskwood, and the Hinterlands.",al={"green dragon portal","great tree feralas","emerald dream tree"}},{q="Why are Grimtotem tauren present in Feralas?",a="A renegade sect of Grimtotem tauren keeps a compound in the wilderness, beyond Thunder Bluff's authority. They are hostile to both the Alliance and Horde, have trapped local faerie dragons, and are targets of Horde scouts.",al={"grimtotem feralas","grimtotem compound","hostile tauren"}},{q="Are there Silithid in Feralas?",a="Yes. South of the main road, The Writhing Deep is a subterranean hive swarming with silithid insectoids. Their emergence in the rainforest signals that the hive mind is spreading far beyond southern Kalimdor's deserts.",al={"writhing deep","bugs in feralas","silithid hive"}}},ang={["race:NightElf"]="As a night elf, you feel the weight of ancient Kaldorei civilization in Feralas. Ogres defiling sacred ruins such as Eldre'Thalas bring sorrow and anger.",["faction:Alliance"]="As an Alliance operative, you work from Feathermoon Stronghold under Shandris Feathermoon. You watch the coast for naga and guard elven heritage.",["faction:Horde"]="At Camp Mojache, you help hold the Horde's frontier against Gordunni incursions, rogue Grimtotem, and Woodpaw gnolls.",["class:Druid"]="As a druid, you know the Dream Bough connects Feralas to the Emerald Dream. The place is sacred, and you must guard it from corruption and defilers.",["profession:Herbalism"]="As an herbalist, you find temperate and tropical plants beneath the damp, shaded canopy, including Sungrass, Purple Lotus, and Khadgar's Whisker."},kw={"camp mojache","dire maul","dream bough","eldre'thalas","feathermoon","feralas","gordunni","shandris","thalanaar"},rel={"subzone:dire-maul","subzone:feathermoon-stronghold-classic","subzone:camp-mojache","subzone:thalanaar","subzone:dream-bough","subzone:forgotten-coast","subzone:twin-colossals","zone:thousandneedles"},src={"Feralas (Classic)","Feralas"}}
